INSERT INTO bible_chapters (book_id, chapter_number, total_verses)
INSERT INTO bible_verses (chapter_id, verse_number, text) VALUES
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 1), 1, 'Toda a sabedoria vem do Senhor Deus, e com ele esteve sempre e existe antes de todos os séculos.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 1), 2, 'A areia do mar, as gotas da chuva e os dias do tempo, quem os pode contar? A altura do céu, e a extensão da terra, e a profundidade do abismo, quem os pode medir? (ver nota)'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 1), 3, 'Quem pode penetrar a sabedoria de Deus a qual precede todas as coisas?'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 1), 4, 'A sabedoria foi criada antes de tudo, e a luz da inteligência existe desde a eternidade.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 1), 5, 'A fonte da sabedoria é o Verbo de Deus nos céus e os seus caminhos são os mandamentos eternos. (ver nota)'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 1), 6, 'A quem foi descoberta a raiz da sabedoria, e quem conheceu os seus profundos desígnios? A quem foi revelada e manifestada a ciência da sabedoria? E quem compreende a multiplicidade dos seus passos?'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 1), 8, 'Um só, que é o altíssimo Criador omnipotente, rei poderoso, sumamente terrível, que está assentado sobre o seu trono, Deus dominador.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 1), 9, 'Foi ele que a criou no Espírito Santo, e que a viu, contou e mediu. (ver nota)'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 1), 10, 'Ele a difundiu por todas as suas obras e por toda a carne, segundo a medida da sua liberalidade, e a comunicou aos que o amam. (ver nota)'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 1), 11, 'O temor do Senhor é glória e honra, alegria e coroa de regozijo.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 1), 12, 'O temor do Senhor deleita o coração, e dará alegria, gozo e larga vida.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 1), 13, 'Aquele que teme ao Senhor encontrar-se-á bem no fim, será abençoado no dia da sua morte.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 1), 14, 'O amor de Deus é uma sabedoria digna de ser honrada.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 1), 15, 'Aqueles a quem ela se manifesta, amam-na logo que a vêem, desde que reconhecem as maravilhas que opera.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 1), 16, 'O princípio da sabedoria é o temor do Senhor. Forma-se com os homens fiéis no ventre de sua mãe, anda com as mulheres (santas e) escolhidas, vê-se em companhia dos justos e dos fiéis.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 1), 17, 'O temor do Senhor é a religião da ciência.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 1), 18, 'Esta religião guarda e santifica o coração, dá-lhe satisfação e alegria.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 1), 19, 'Quem teme o Senhor encontrar-se-á bem no dia da sua morte será abençoado.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 1), 20, 'O temor de Deus é a plenitude da sabedoria, e os seus frutos saciam (o que a possui).'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 1), 21, 'Ele encherá toda a casa (do sábio) com os seus produtos, e os celeiros com os seus tesouros.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 1), 22, 'O temor do Senhor é a coroa da sabedoria: ele dá a plenitude da paz e frutos de salvação.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 1), 23, 'Ele viu a sabedoria e contou-a; ambas as coisas são um dom de Deus.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 1), 24, 'A sabedoria espalha a ciência e a luz da prudência, e exalta a glória dos que a possuem.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 1), 25, 'A raiz da sabedoria é temer ao Senhor; os seus ramos são de muita dura. (ver nota)'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 1), 26, 'Nos tesouros da sabedoria acham-se a inteligência e a religião da ciência; mas para os pecadores a sabedoria é uma coisa execrável.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 1), 27, 'O temor do Senhor expulsa o pecado:'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 1), 28, 'quem não tem este temor não poderá ser justo, porque a sua cólera será a sua ruína. (ver nota)'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 1), 29, 'O homem paciente sofrerá até um certo tempo, e depois ser-lhe-á dada a alegria.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 1), 30, 'O homem de bom senso reterá em si mesmo as suas palavras até ao devido tempo, e os lábios de muitos publicarão a sua prudência.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 1), 31, 'Sábias sentenças estão encerradas nos tesouros da sabedoria; o pecador, porém, detesta o culto de Deus.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 1), 33, 'Filho, tu que desejas ardentemente a sabedoria observa os mandamentos, e Deus ta dará.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 1), 34, 'Porque o temor do Senhor é a sabedoria e a disciplina,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 1), 35, 'e o que lhe agrada é a fé e a mansidão; ele encherá os tesouros daquele (que as possui).'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 1), 36, 'Não sejas rebelde ao temor do Senhor, e não te aproximes dele com um coração dobre.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 1), 37, 'Não sejas hipócrita diante dos homens, e não te sejam os teus lábios motivo de queda.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 1), 38, 'Tem cuidado com eles para que não caias e não desonres a tua alma,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 1), 39, 'para que Deus não descubra os teus segredos, e não te lance a terra no meio da assembleia, (ver nota)'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 1), 40, 'por te teres aproximado do Senhor com disposição maligna, e por teres tido o teu coração cheio de dolo e de engano.');
INSERT INTO bible_chapters (book_id, chapter_number, total_verses)
INSERT INTO bible_verses (chapter_id, verse_number, text) VALUES
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 2), 1, 'Meu filho, se entrares no serviço de Deus, persevera firme na justiça e no temor, e prepara a tua alma para a prova.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 2), 2, 'Humilha o teu coração e tem paciência, inclina o teu ouvido e recebe as palavras da sabedoria, e não te precipites no tempo do infortúnio. (ver nota)'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 2), 3, 'Sofre as demoras de Deus; conserva-te unido a Deus, espera pacientemente, para que no fim a tua vida cresça.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 2), 4, 'Aceita (de boamente) tudo o que te suceder, aguenta-te no sofrimento, no tempo da humilhação tem paciência,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 2), 5, 'porque no fogo se prova o ouro e a prata, e os homens amados (de Deus provam-se) no cadinho da humilhação.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 2), 6, 'Confia em Deus, e ele te salvará, dirige bem o teu caminho e espera nele; conserva o seu temor até à velhice.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 2), 7, 'Vós, os que temeis o Senhor, esperai a sua misericórdia e não vos desvieis dele, para não cairdes.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 2), 8, 'Vós, os que temeis o Senhor, tende fé nele, e não se perderá a vossa recompensa.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 2), 9, 'Vós, os que temeis o Senhor, esperai nele: para vossa consolação virá sobre vós a sua misericórdia.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 2), 10, 'Vós, os que temeis o Senhor, amai-o, e os vossos corações serão alumiados.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 2), 11, 'Considerai, filhos, as gerações humanas, e sabei que ninguém, que esperou no Senhor, foi confundido.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 2), 12, 'Quem permaneceu firme nos seus mandamentos, e foi desamparado? Ou quem o invocou, e foi dele desprezado?'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 2), 13, 'Porque Deus é bom e misericordioso, e perdoará os pecados no dia da tribulação; ele é o protector de todos os que o buscam em verdade.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 2), 14, 'Ai do coração dobre, dos lábios criminosos, das mãos que fazem o mal, do pecador que anda sobre a terra por dois caminhos!'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 2), 15, 'Ai dos fracos de coração, que não confiam em Deus. Coragem: e que, por isso, não serão protegidos por ele!'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 2), 16, 'Ai dos que perderam a paciência, que deixaram os caminhos rectos e se extraviaram por veredas malignas!'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 2), 17, 'Que farão eles, quando o Senhor começar a examinar (tudo)?'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 2), 18, 'Os que temem o Senhor não são incrédulos à sua palavra, e os que o amam continuam no seu caminho.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 2), 19, 'Os que temem o Senhor procuram o que lhe é agradável, e os que o amam saciam-se da sua lei.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 2), 20, 'Os que temem o Senhor preparam os seus corações, e santificam as suas almas na sua presença. (ver nota)'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 2), 21, 'Os que temem o Senhor, guardam os seus mandamentos, e têm paciência até que lance os olhos sobre eles, dizendo: Se não fizermos penitência, cairemos nas mãos do Senhor, e não nas mãos dos homens.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 2), 22, 'Porque, na medida em que é elevada a sua grandeza, assim o é a sua misericórdia.');
INSERT INTO bible_chapters (book_id, chapter_number, total_verses)
INSERT INTO bible_verses (chapter_id, verse_number, text) VALUES
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 3), 1, 'Os filhos da sabedoria foram assembleia dos justos, e o povo que constituem e obediência e amor (de Deus).'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 3), 2, 'Ouvi, filhos, os preceitos do vosso pai, e procedei assim para que sejais salvos.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 3), 3, 'Porque Deus quis honrar o pai pelos filhos e firmou cuidadosamente sobre eles a autoridade da mãe.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 3), 4, 'O que ama a Deus implorará o perdão dos seus pecados, e se absterá de tornar a cair neles, e será ouvido na sua oração de todos os dias.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 3), 5, 'Como quem acumula tesouros, assim é aquele que honra sua mãe.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 3), 6, 'O que honra seu pai encontrará alegria nos seus filhos, e será atendido no dia da sua oração.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 3), 7, 'O que honra seu pai viverá uma vida larga: e consola sua mãe quem obedece a seu pai.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 3), 8, 'O que teme O Senhor honra seus pais; e servirá, como a senhores, aos que o geraram.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 3), 9, 'Honra teu pai por acções, por palavras e com toda a paciência, (ver nota)'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 3), 10, 'para que venha sobre ti a sua bênção, e esta bênção permaneça contigo até ao fim,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 3), 11, 'A bênção do pai torna firmes as casas dos filhos, e a maldição da mãe deita-as abaixo pelos alicerces.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 3), 12, 'Não te glories com aquilo que desonra teu pai porque a sua ignomínia não é glória para ti.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 3), 13, 'Com efeito, a glória do homem provém da honra de seu pai, e um pai sem honra é a vergonha de seu filho.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 3), 14, 'Filho, ampara a velhice de teu pai não o entristeças durante a sua vida.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 3), 15, 'Se o seu espírito se for enfraquecendo, suporta-o não o desprezes por teres mais vigor do que ele pois a caridade exercida com teu pai, não ficará no esquecimento.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 3), 16, 'Serás recompensado por teres suportado os defeitos de tua mãe:'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 3), 17, 'a tua casa prosperará na justiça, e no dia da tribulação (Deus) se lembrará de ti; os teus pecados se desfarão como o gelo em pleno sol.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 3), 18, 'Como é infame aquele que desampara o seu pai! E como é amaldiçoado de Deus o que exaspera sua mãe!'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 3), 19, 'Filho, leva ao cabo as tuas obras com mansidão, e atrairás não só a estima, mas também o amor dos homens.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 3), 20, 'Quanto maior és, mais te deves humilhar em todas as coisas, e acharás graça diante de Deus;'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 3), 21, 'Porque só o poder de Deus é que é grande, e é pelos humildes que ele é honrado. Não procures saber o que excede a tua capacidade, e não especules o que ultrapassa as tuas forças (intelectuais), mas pensa sempre no que Deus te mandou, e não tenhas a curiosidade de conhecer demasiado número das suas obras.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 3), 23, 'Porque não te é necessário ver com os teus olhos o que está escondido. (ver nota)'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 3), 24, 'Não te apliques a esquadrinhar com ânsia as coisas inúteis, e não tenhas a curiosidade de conhecer demasiado número das obras de Deus.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 3), 25, 'De facto, muitas coisas te foram reveladas, que excedem o espírito humano.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 3), 26, 'A muitos enganaram as suas opiniões, e o seu sentir reteve-os na vaidade.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 3), 27, 'O coração duro será oprimido de males no fim (da vida); aquele que ama o perigo perecera nele.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 3), 28, 'O coração que anda por dois caminhos, não será bem sucedido, e o depravado de coração achará neles a sua ruína.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 3), 29, 'O coração perverso será oprimido de dores, e o pecador ajuntará pecados sobre pecados.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 3), 30, 'A assembleia dos soberbos é incurável, porque a planta do pecado se arreigará neles, sem que o notem.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 3), 31, 'O coração do sábio manifesta-se pela sabedoria, e o ouvido dos bons escuta a sabedoria com grande avidez.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 3), 32, 'O coração sábio e inteligente abstém-se do pecado, e é bem sucedido nas obras de justiça.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 3), 33, 'A água apaga o fogo ardente, e a esmola resiste aos pecados.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 3), 34, 'Deus contempla aquele que pratica a misericórdia e lembra-se dele para o futuro, e (assim, o misericordioso) no tempo da desgraça encontrará um apoio.');
INSERT INTO bible_chapters (book_id, chapter_number, total_verses)
INSERT INTO bible_verses (chapter_id, verse_number, text) VALUES
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 4), 1, 'Filho, não prives o pobre da sua esmola, não apartes dele os teus olhos. Não desprezes aquele que tem fome, nem exasperes o pobre na sua necessidade.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 4), 3, 'Não aflijas o coração do desventurado, e não retardes a esmola ao necessitado.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 4), 4, 'Não rejeites a petição do atribulado, nem voltes a cara ao pobre.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 4), 5, 'Não afastes os teus olhos do indigente, para que não se irrite, nem dês ocasião, aos que te pedem, de te amaldiçoar por trás,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 4), 6, 'porque será ouvida a imprecação daquele que te amaldiçoa na amargura da sua alma; o seu Criador o ouvirá. Mostra-te afável no ajuntamento dos pobres; humilha a tua alma diante dum ancião; abaixa a tua cabeça diante dos grandes. (ver nota)'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 4), 8, 'Aplica o teu ouvido ao pobre, sem enfado, paga a tua dívida, dá-lhe mansamente uma resposta serena.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 4), 9, 'Livra da mão do soberbo o que padece injúria, e, quando julgares (uma causa), não o faças com aspereza.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 4), 10, '(No julgar) sê misericordioso com os órfãos como um pai, e como um marido para com a sua (pobre) mãe,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 4), 11, 'e serás como um filho obediente do Altíssimo, que se compadecerá de ti, mais do que uma mãe.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 4), 12, 'A sabedoria infunde vida a seus filhos, toma debaixo da sua protecção os que a buscam, vai adiante deles no caminho da justiça.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 4), 13, 'O que a ama, ama a vida, e os que fazem vigílias para a encontrar gozarão da sua doçura.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 4), 14, 'Aqueles que a possuírem, terão a vida (eterna) por herança, e onde ela entrar, Deus abençoará tudo.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 4), 15, 'Os que a servem, serão obedientes ao Santo, e Deus ama os que a amam. (ver nota)'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 4), 16, 'Aquele que a ouve, julgará as nações, e o que tem os olhos fixos nela permanecerá seguro.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 4), 17, 'Se tiver confiança nela, herdá-la-á, e a sua posse será confirmada em seus filhos.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 4), 18, 'Porque ela anda com ele na prova, e o escolhe entre os primeiros. (ver nota)'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 4), 19, 'Ela fará vir sobre ele o temor, o medo e a prova; atormentá-lo-á com a tribulação da sua disciplina, até que o experimente nos seus pensamentos, e se fie na sua alma.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 4), 20, 'Então ela o porá firme, encaminhar-se-á directamente a ele, enchê-lo-á de alegria, (ver nota)'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 4), 21, 'descobrir-lhe-á os seus segredos, e o enriquecerá com um tesouro de ciência e de inteligência da justiça.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 4), 22, 'Porém, se ele se extraviar, ela o abandonará e o entregará nas mãos do seu inimigo.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 4), 23, 'Filho, aproveita o tempo, foge do mal.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 4), 24, 'Não te envergonhes de dizer a verdade, para bem da tua alma.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 4), 25, 'Há vergonha que faz cair em pecado, e há vergonha que traz consigo glória e graça.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 4), 26, 'Não faças acepção de pessoas com prejuízo teu nem mintas à custa da tua alma.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 4), 27, 'Não respeites o teu próximo na tua queda. (ver nota)'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 4), 28, 'Não retenhas a palavra quando ela pode ser salutar. Não escondas a tua sabedoria pela tua vaidade.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 4), 29, 'Com efeito, a sabedoria dá-se a conhecer pela língua; o bom senso, a ciência e a doutrina mostram-se na palavra do homem cordato; a firmeza (manifesta-se) nas obras de justiça.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 4), 30, 'Não contradigas de modo algum a verdade; confunde-te da mentira em que tenhas caído por ignorância.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 4), 31, 'Não te envergonhes de confessar os teus pecados, mas não te submetas a ninguém que te leve a pecar.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 4), 32, 'Não resistas cara a cara ao homem poderoso, não te oponhas à corrente do rio. (ver nota)'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 4), 33, 'Combate pela justiça para (salvares) a tua vida, peleja até à morte pela justiça, e Deus combaterá por ti contra os teus inimigos.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 4), 34, 'Não sejas precipitado em falar, e (ao mesmo tempo) remisso e negligente nas tuas obras.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 4), 35, 'Não sejas como um leão na tua casa, fazendo tropelias contra os teus domésticos e oprimindo os teus súbditos.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 4), 36, 'A tua mão não esteja aberta para receber, e fechada para dar.');
INSERT INTO bible_chapters (book_id, chapter_number, total_verses)
INSERT INTO bible_verses (chapter_id, verse_number, text) VALUES
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 5), 1, 'Não te fies nas riquezas iníquas e não digas: eu tenho bastante com que viver — porque de nada te aproveitará isto no dia do castigo e da escuridão. Não te abandones, quando te sentires forte, aos maus desejos do teu coração.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 5), 3, 'e não digas: Como sou poderoso! Quem poderá obrigar-me a dar contas das minhas acções? Com efeito Deus exercerá a sua vingança.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 5), 4, 'Não digas; Eu pequei; e que mal me veio dai ? — porque o Altíssimo é lento em punir (os crimes). (ver nota)'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 5), 5, 'Não estejas sem temor da ofensa que te foi perdoada, e não ajuntes pecados sobre pecados.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 5), 6, 'Não digas; A misericórdia do Senhor é grande, ele se compadecerá da multidão dos meus pecados.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 5), 7, 'Porque a sua misericórdia e a sua ira estão perto uma da outra, e a sua ira olha para os pecadores.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 5), 8, 'Não tardes em te converter ao Senhor, não o difiras de dia para dia,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 5), 9, 'porque virá de improviso a sua ira, e no dia do castigo te perderá.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 5), 10, 'Não andes inquieto por (amor de) riquezas injustas, porque elas não te aproveitarão no dia do castigo e da escuridão.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 5), 11, 'Não te voltes a todo o vento, e não andes por todos os caminhos. porque é assim que todo o pecador de língua dobre se dá a conhecer. (ver nota)'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 5), 12, 'Se firme no caminho do Senhor, na sinceridade dos teus sentimentos e conhecimentos, e que a palavra de paz e de justiça te acompanhe sempre.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 5), 13, 'Sê manso para ouvir a palavra, a fim de que a entendas; então darás com sabedoria uma resposta justa.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 5), 14, 'Se tens inteligência, responde ao teu próximo; se não, põe a tua mão sobre a tua boca, para que te não suceda ser surpreendido numa palavra indiscreta e cair em confusão,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 5), 15, 'A honra e a glória acompanham o falar do homem sensato, mas a língua do imprudente é a sua ruína.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 5), 16, 'Que ninguém te chame intriguista, e que não te venha a tua língua a ser um laço e um motivo de confusão.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 5), 17, 'Porque sobre o ladrão virão a confusão e o arrependimento, e sobre a língua dobre uma nota de infâmia; ao mexeriqueiro (estão reservados) o ódio, a inimizade e a contumélia.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 5), 18, 'Faze igualmente justiça aos pequenos e aos grandes.');
INSERT INTO bible_chapters (book_id, chapter_number, total_verses)
INSERT INTO bible_verses (chapter_id, verse_number, text) VALUES
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 6), 1, 'De amigo não te tornes inimigo do teu próximo, porque o mau terá por sorte a vergonha e a ignomínia, como todo o pecador invejoso e de língua dobre.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 6), 2, 'Não te eleves como um touro no pensamento do teu coração, para não suceder que a tua loucura quebre a tua força,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 6), 3, 'consuma as tuas folhas e perca os teus frutos, e tu venhas a ficar como uma árvore seca no deserto.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 6), 4, 'A alma maligna perderá aquele que a tem, torná-lo-á a alegria dos seus inimigos. e conduzi-lo-á à sorte dos ímpios.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 6), 5, 'A palavra doce multiplica os amigos e amansa os inimigos; a linguagem amável abunda no homem bom.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 6), 6, 'Dá-te bem com muitos, mas seja teu conselheiro um entre mil.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 6), 7, 'Se queres ter um amigo, toma-o depois de o teres provado, e não te fies facilmente nele.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 6), 8, 'Com efeito, há tal amigo que somente o é quando nisso acha a sua conveniência, e que deixará de o ser no dia da tribulação.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 6), 9, 'E há amigo que se muda em inimigo; e há amigo que porá a descoberto ódios, disputas e rixas;'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 6), 10, 'e há amigo que só o é para a mesa, e que o não será no dia da necessidade.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 6), 11, 'Se o teu amigo perseverar firme, será para ti como um igual, tratará à vontade com os da tua casa.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 6), 12, 'Se ele se humilhar diante de ti e se apagar na tua presença, terás uma amizade excelente na união dos corações. (ver nota)'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 6), 13, 'Separa-te dos teus inimigos, e está alerta com os teus amigos.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 6), 14, 'O amigo fiel é uma forte protecção; quem o encontrou, encontrou um tesouro.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 6), 15, 'Nada se pode comparar com um amigo fiel, e o ouro e a prata não merecem ser postos em balança com a sinceridade da sua fé.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 6), 16, 'O amigo fiel é uma medicina de vida e de imortalidade; os que temem o Senhor acharão um tal amigo.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 6), 17, 'O que teme a Deus será, por isso mesmo, feliz na amizade, porque o seu amigo será semelhante a ele.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 6), 18, 'Filho, desde a tua mocidade recebe a Instrução, e adquirirás uma sabedoria que te dure até à velhice,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 6), 19, 'Aproxima-te da sabedoria, como o que lavra e semeia, e espera os seus bons frutos.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 6), 20, 'Trabalharás (apenas) um pouco na sua cultura, e depressa comerás dos seus frutos.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 6), 21, 'Quão excessivamente áspera é a sabedoria para os néscios! Não permanecerá junto dela o insensato.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 6), 22, 'Será para eles como uma pedra pesada que serve para provar, e não tardarão em se descarregarem dela. (ver nota)'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 6), 23, 'Porque a sabedoria que instrui é como o seu nome, não se manifesta a muitos (à maioria das pessoas); mas naqueles que a conhecem, permanece até (os levar) à presença de Deus.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 6), 24, 'Ouve, filho, recebe uma sábia advertência, não rejeites o meu conselho.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 6), 25, 'Mete os teus pés nos seus grilhões, e o teu pescoço nas suas cadelas. (ver nota)'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 6), 26, 'Baixa o teu ombro, leva-a às costas, e não te aborreças com as suas prisões.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 6), 27, 'Aproxima-te dela de todo o teu coração, guarda os seus caminhos com todas as tuas forças.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 6), 28, 'Segue os seus vestígios, e ela se te manifestará; quando já a possuíres, não a deixes,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 6), 29, 'porque nela encontrarás, no fim, o teu descanso,e ela se converterá para ti em gosto.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 6), 30, 'Os seus grilhões serão para ti uma forte protecção e um firme apoio, as suas cadeias um vestido de glória:'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 6), 31, 'nela está realmente uma beleza que dá a vida, e os seus vínculos são ligaduras que saram.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 6), 32, 'Tu te revestirás dela como duma veste de glória, e a porás sobre ti como uma coroa de regozijo.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 6), 33, 'Filho, se me deres atenção, aprenderás, e, se aplicares o teu espírito, serás sábio.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 6), 34, 'Se me ouvires, receberás a instrução, e se fores amigo de ouvir, serás sábio.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 6), 35, 'Frequenta a reunião dos velhos prudentes, une-te de coração à sua sabedoria; a fim de poderes ouvir tudo o que te disserem de Deus, e de não te escaparem as suas louváveis sentenças.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 6), 36, 'Se vires um homem sensato, madruga para ir ter com ele, e gastem os teus pés os degraus da sua porta.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 6), 37, 'Fixa a tua atenção nos preceitos de Deus medita continuamente os seus mandamentos, que ele mesmo te dará um coração (firme no bem), e ser-te-á dada a desejada sabedoria.');
INSERT INTO bible_chapters (book_id, chapter_number, total_verses)
INSERT INTO bible_verses (chapter_id, verse_number, text) VALUES
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 7), 1, 'Não faças o mal, e o mal não cairá, sobre ti.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 7), 2, 'Retira-te da injustiça, e a injustiça se afastará de ti.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 7), 3, 'Filho, não semeies males nos sulcos da injustiça, para não recolheres sete vezes mais.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 7), 4, 'Não peças ao Senhor o cargo de conduzir outros, nem ao rei um posto de honra. (ver nota)'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 7), 5, 'Não te tenhas por justo diante de Deus, porque ele conhece o (fundo do) coração, e não pretendas parecer sábio diante do rei.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 7), 6, 'Não procures ser juiz, se não tens coragem para despedaçar as injustiças, não vá acontecer que temas à vista do poderoso, e te exponhas a proceder contra a equidade.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 7), 7, 'Não ofendas a multidão duma cidade; não te metas entre o tumulto do povo;'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 7), 8, 'não ates um segundo pecado ao primeiro, porque, nem ainda por um só, ficarás impune.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 7), 9, 'Não te deixes cair no desânimo.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 7), 10, 'nem te descuides de fazer oração e dar esmola.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 7), 11, 'Não digas: Deus atenderá à multidão das minhas dádivas, e, oferecendo eu os meus dons ao Deus altíssimo, ele os receberá com agrado. (ver nota)'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 7), 12, 'Não escarneças do homem cuja alma está em amargura; porque Deus, que tudo vê, é quem humilha e exalta.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 7), 13, 'Não inventes mentiras contra teu irmão, nem tampouco o faças contra o teu amigo.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 7), 14, 'Não queiras proferir mentira alguma; porque o acostumar-se a isso é mau.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 7), 15, 'Não sejas verboso na assembleia dos anciães nem multipliques as palavras nas tuas orações. (ver nota)'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 7), 16, 'Não aborreças as obras penosas, nem o trabalho do campo, criado pelo Altíssimo.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 7), 17, 'Não te alistes entre a turba das pessoas indisciplinadas.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 7), 18, 'Lembra-te da ira (de Deus) que não tardará.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 7), 19, 'Humilha profundamente o teu espírito, porque a carne do ímpio será castigada com o fogo e com o verme.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 7), 20, 'Não faças mal a um teu amigo, porque difere dar-te o dinheiro, nem desprezes pelo ouro um teu irmão querido.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 7), 21, 'Não te separes da mulher sensata e virtuosa. que recebeste por sorte no temor do Senhor, porque a graça da sua modéstia é mais preciosa que o ouro.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 7), 22, 'Não trates mal o servo que trabalha com fidelidade, nem o mercenário que todo se dá a servir-te.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 7), 23, 'O servo sensato seja querido de ti como a tua alma, não lhe negues a liberdade (que ele merece), e não o deixes cair na pobreza.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 7), 24, 'Tens gados? Cuida deles; se te são úteis, conserva-os.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 7), 25, 'Tens filhos? Educa-os e acostuma-os à sujeição desde a sua infância.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 7), 26, 'Tens filhas? Vela pela pureza dos seus corpos, e não lhes mostres o teu rosto demasiado jovial. Casa a tua filha, e terás arrumado um assunto importante; dá-a a um homem de bom senso. (ver nota)'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 7), 28, 'Se tens mulher segundo o teu coração, não a repudies; e não confies na que é odiosa.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 7), 29, 'De todo o teu coração honra teu pai, e não te esqueças dos gemidos de tua mãe.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 7), 30, 'Lembra-te que não terias nascido sem eles, e faze por eles o que eles fizeram por ti.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 7), 31, 'Teme o Senhor com toda a tua alma, e venera os seus sacerdotes.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 7), 32, 'Ama com todas as tuas forças aquele que te criou, e não desampares os seus ministros.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 7), 33, 'Honra a Deus de toda a tua alma, respeita os sacerdotes, e purifica-te, oferecendo as espáduas. (ver nota)'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 7), 34, 'Dá-lhes a sua parte das primícias e das vítimas de expiação, como te é mandado: purifica-te das tuas negligências com pequenas ofertas;'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 7), 35, 'oferece ao Senhor as espáduas das vítimas, os sacrifícios de santificação e as primícias das coisas santas.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 7), 36, 'Estende a tua mão para o pobre, a fim de que o teu sacrifício de expiação e a tua oferta sejam perfeitos.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 7), 37, 'Dá graciosamente a todos os vivos, e não recuses os teus dons aos mortos.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 7), 38, 'Não deixes de consolar os que choram, e acompanha (na sua dor) os aflitos.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 7), 39, 'Não sejas preguiçoso em visitar os enfermos, porque é assim que tu te fortificarás na caridade,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 7), 40, 'Em todas as tuas obras lembra-te do teu fim, e nunca jamais pecarás.');
INSERT INTO bible_chapters (book_id, chapter_number, total_verses)
INSERT INTO bible_verses (chapter_id, verse_number, text) VALUES
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 8), 1, 'Não litigues com um homem poderoso, para que não suceda que lhe caias nas mãos.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 8), 2, 'Não contendas com o homem rico, para que não suceda que te mova algum processo, (ver nota)'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 8), 3, 'porque o ouro e a prata têm perdido muitos, e o seu poder chega até a desencaminhar o coração dos reis.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 8), 4, 'Não disputes com o grande falador, e não meterás mais lenha no seu fogo.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 8), 5, 'Não tenhas trato com o homem mal educado, para que não suceda falar mal dos teus antepassados. (ver nota)'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 8), 6, 'Não desprezes o homem que se retira do pecado, não o censures (pelo mal que fez antes): lembra-te que todos nós somos dignos de castigo. Não desprezes nenhum homem na sua velhice, porque alguns de entre nós envelhecerão também.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 8), 8, 'Não te regozijes com a morte do teu inimigo; considera que todos nós havemos de morrer e que não queremos que haja regozijo por isso.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 8), 9, 'Não desprezes o que contarem os velhos sábios, mas faze com que te sejam familiares as suas sentenças :'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 8), 10, 'deles aprenderás a sabedoria, os ensinamentos da inteligência e a arte de servir os grandes de um modo irrepreensível.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 8), 11, 'Não deixes de ouvir o que contam os velhos, porque eles o aprenderam de seus pais;'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 8), 12, 'deles aprenderás a inteligência e a arte de responder oportunamente.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 8), 13, 'Não acendas os carvões dos pecadores, arguindo-os. para que não sejas abrasado na chama do fogo dos seus pecados. (ver nota)'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 8), 14, 'Não resistas, cara a cara, a um homem insolente, para que não suceda que ele se ponha a armar laços às tuas palavras,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 8), 15, 'Não emprestes a um homem mais poderoso do que tu, porque, se lhe emprestares, faze de conta que o perdeste.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 8), 16, 'Não fiques por fiador em mais do que podem as tuas forças, porque, se ficares, considera-te obrigado a pagar.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 8), 17, 'Não arrazoes contra um juiz, porque ele julga o que supõe ser justo.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 8), 18, 'Não te metas a uma viagem com homem temerário, para que não suceda que ele faça recair sobre ti os seus males; com efeito, ele anda segundo a sua (caprichosa) vontade, e tu perecerás com ele pela sua loucura.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 8), 19, 'Não tenhas rixas com o homem colérico, e com o temerário não vás a um lugar solitário, porque para ele nada vale o sangue, e, longe de todo o socorro, te esmagará.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 8), 20, 'Não te aconselhes com loucos, porque eles não poderão amar senão o que lhes apraz.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 8), 21, 'Não deliberes diante dum estranho, porque não sabes o que ele poderá conceber.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 8), 22, 'Não descubras o teu coração a qualquer homem, para que não suceda que te mostre uma falsa amizade e te ultraje.');
INSERT INTO bible_chapters (book_id, chapter_number, total_verses)
INSERT INTO bible_verses (chapter_id, verse_number, text) VALUES
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 9), 1, 'Não sejas cioso da mulher que repousa no teu seio, para que não empregue contra ti a malícia que lhe ensinaste. (ver nota)'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 9), 2, 'Não dês à mulher poder sobre a tua alma. para que não usurpe a tua autoridade, e fiques envergonhado.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 9), 3, 'Não olhes para a mulher volúvel, para não caíres nos seus laços.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 9), 4, 'Não andes muito com uma bailarina, nem a ouças, para não pereceres à força dos seus atractivos.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 9), 5, 'Não detenhas os teus olhos sobre uma donzela. para que a sua beleza não te seja ocasião de queda.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 9), 6, 'Nunca entregues a tua alma às prostitutas, para que te não percas a ti e aos teus bens. Não deixes errar os olhos pelas ruas da cidade, nem andes vagueando pelas suas praças.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 9), 8, 'Afasta os teus olhos da mulher enfeitada, e não olhes com insistência para a formosura alheia.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 9), 9, 'Por causa da formosura da mulher pereceram muitos, e por ela se acende a concupiscência como fogo.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 9), 10, 'Toda a mulher devassa será pisada como esterco no caminho.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 9), 11, 'Muitos, por terem admirado a formosura da mulher alheia, se tornaram réprobos, porque a sua conversação queima como fogo.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 9), 12, 'Não te assentes jamais com a mulher alheia, nem te recostes com ela à mesa:'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 9), 13, 'não a incites a beber vinho (contigo) para que não suceda que o teu coração se converta para ela e que a tua paixão te faça cair na perdição.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 9), 14, 'Não deixes o amigo antigo, porque o novo não será semelhante a ele.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 9), 15, 'O amigo novo é um vinho novo; quando se fizer velho, (então) o beberás com gosto.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 9), 16, 'Não invejes a glória nem as riquezas do pecador, porque não sabes qual será a sua ruína.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 9), 17, 'Não te agrade a violência dos injustos, sabendo que até à sepultura não agradará o ímpio (a Deus).'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 9), 18, 'Conserva-te longe daquele homem que tem poder de mandar matar, e assim não saberás o que é temer a morte.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 9), 19, 'Mas, se te aproximares dele, vê não cometas algum mal, donde possa resultar tirar-te a vida.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 9), 20, 'Sabe que comunicas com a morte, porque caminhas no meio de laços, e andas sobre as armas de homens irritados.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 9), 21, 'Segundo as tuas forças acautela-te do teu próximo, e trata com os sábios e prudentes.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 9), 22, 'Os teus convivas sejam homens justos; no temor de Deus esteja posta a tua glória;'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 9), 23, 'ocupe o teu espírito o pensamento de Deus, e toda a tua conversação verse sobre os preceitos do Altíssimo.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 9), 24, 'Os artistas são louvados pelas obras das suas mãos, o príncipe do povo pela sabedoria dos seus discursos, e os velhos pela prudência das suas palavras.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 9), 25, 'É terrível na sua cidade o homem linguareiro. e o precipitado nas suas palavras será aborrecido.');
INSERT INTO bible_chapters (book_id, chapter_number, total_verses)
INSERT INTO bible_verses (chapter_id, verse_number, text) VALUES
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 10), 1, 'O juiz sábio fará justiça ao seu povo, e o governo do homem sensato será estável.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 10), 2, 'Qual o juiz do povo, tais os seus ministros; qual o governador da cidade, tais os seus habitantes.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 10), 3, 'O rei pouco sensato perderá o seu povo, e as cidades povoar-se-ão pelo bom senso dos governantes.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 10), 4, 'O domínio sobre um pais está na mão de Deus, e ele é que, a seu tempo, suscitará um governador útil.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 10), 5, 'A prosperidade do homem está na mão de Deus, e é ele que põe o sinal da sua honra sobre a fronte do escriba.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 10), 6, 'Esquece-te de todas as injúrias que recebeste do teu próximo, e não faças nada por via de violência. A soberba é aborrecida por Deus e pelos homens, e toda a iniquidade das nações é execrável.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 10), 8, 'Um reino é transferido dum povo para outro, por causa das injustiças, das violências, dos ultrajes e de diversos enganos.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 10), 9, 'Não há coisa mais criminosa do que o avarento. Por que se ensoberbece a terra e a cinza?'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 10), 10, 'Não há coisa mais iníqua do que amar o dinheiro; o que o ama venderia até a sua alma, visto que se despojou, em vida, das próprias entranhas.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 10), 11, 'A vida de todo o potentado é breve. A doença prolongada fatiga o médico.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 10), 12, 'O médico atalha a doença de pouca dura; assim um que hoje é rei, amanhã morrerá.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 10), 13, 'Quando morrer o homem, terá por herança as serpentes, os bichos, os vermes.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 10), 14, 'O princípio da soberba do homem é renegar a Deus,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 10), 15, 'porque o seu coração afasta-se daquele que o criou, porque o princípio de todo o pecado é a soberba. Aquele que se entrega a ela, será cheio de maldições, e ela por fim será a sua ruína.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 10), 16, 'Por isso é que o Senhor cobriu de opróbrios as assembleias dos maus, e as destruiu para sempre.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 10), 17, 'Deus destruiu os tronos dos chefes soberbos, e em seu lugar colocou os mansos.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 10), 18, 'Deus fez secar as raízes das nações soberbas, e plantou os que eram humildes dentre as mesmas nações.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 10), 19, 'O Senhor destruiu as terras das nações, e as arruinou até aos alicerces.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 10), 20, 'Mirrou muitas delas e destruiu-as, e fez apagar a sua memória de cima da terra.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 10), 21, 'Deus aboliu a memória dos soberbos, e conservou a dos humildes de coração. A soberba não foi criada com o homem, nem a ira com os nascidos das mulheres.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 10), 23, 'A descendência do homem, que teme a Deus, será honrada, porém aquela que transgride os mandamentos do Senhor, será desonrada.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 10), 24, 'Entre os irmãos, a honra é para o que governa; na presença do Senhor, serão honrados aqueles que o temem.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 10), 25, 'A glória dos ricos, dos nobres e dos pobres, é o temor de Deus.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 10), 26, 'Não desprezes o homem justo, ainda que pobre, e não glorifiques o pecador, ainda que rico.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 10), 26, 'Não desprezes o homem justo, ainda que pobre, e não glorifiques o pecador, ainda que rico.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 10), 27, 'O grande, o juiz e o poderoso gozam de honra; porém ninguém é tão grande como aquele que teme a Deus.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 10), 28, 'Os homens livres sujeitar-se-ão a um servo prudente; o homem prudente e educado não murmurará quando for repreendido, e o ignorante não será honrado.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 10), 29, 'Não te orgulhes do trabalho que fazes, e não te abandones à preguiça no tempo da adversidade.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 10), 30, 'Vale mais o que trabalha e que tudo tem em abundância, do que o jactancioso que não tem pão.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 10), 31, 'Filho, conserva a tua alma na mansidão, e dá-lhe a honra que ela merece.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 10), 32, 'Quem justificará o que peca contra a sua alma? E quem honrará o que desonra a sua vida?'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 10), 33, 'O pobre encontra a glória na sua ciência e no seu temor (de Deus); há quem seja (apenas) respeitado por causa das suas riquezas.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 10), 34, 'Ora o que é glorificado na pobreza, quanto mais o seria nas riquezas? Mas o que baseia a sua glória nas riquezas, tema a pobreza.');
INSERT INTO bible_chapters (book_id, chapter_number, total_verses)
INSERT INTO bible_verses (chapter_id, verse_number, text) VALUES
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 11), 1, 'A sabedoria do humilde exaltará a sua cabeça, e o fará assentar no meio dos grandes.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 11), 2, 'Não louves o homem pela sua beleza; nem o desprezes pelo seu aspecto.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 11), 3, 'Pequena é a abelha entre os animais voláteis, e contudo o seu fruto é o primeiro na doçura.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 11), 4, 'Não te vanglories jamais das tuas vestes, nem te desvaneças no dia da tua honra, porque só as obras do Altíssimo são admiráveis, gloriosas, misteriosas, invisíveis.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 11), 5, 'Muitos príncipes (homens anteriormente humildes) assentaram-se sobre o trono, e alguém, em quem se não pensava, levou o diadema.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 11), 6, 'Muitos poderosos foram profundamente humilhados; e homens ilustres foram entregues nas mãos de outros.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 11), 7, 'Não vituperes ninguém, antes de te haveres informado, e, quando te tiveres informado, repreende com equidade.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 11), 8, 'Antes de ouvir, não respondas nada. e enquanto outro fala não o interrompas.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 11), 9, 'Não disputes sobre coisas que não te dizem respeito, e não te assentes com os pecadores para julgar.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 11), 10, 'Filho, não empreendas muitos negócios, porque, se fores rico, não estarás isento de culpa. Se empreenderes muitas coisas, não poderás abrangê-las, e, por mais diligência que faças, não poderás dar saída a todas.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 11), 11, 'Há ímpio que trabalha, se dá pressa e se atormenta, mas, quanto mais faz, menos enriquece. (ver nota)'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 11), 12, 'Há homem sem vigor, que necessita de amparo, falto de forças e abundante em miséria, (ver nota)'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 11), 13, 'mas a quem Deus olha benignamente levanta da sua humilhação e exalta a cabeça: muitos se maravilharam dele e deram glória a Deus.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 11), 14, 'Os bens e os males, a vida e a morte, a pobreza e as riquezas, tudo isto vem de Deus.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 11), 15, 'É em Deus que se encontram a sabedoria, a instrução e a ciência da lei. A caridade e as boas obras nele residem.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 11), 16, 'O erro e as trevas foram criados com os pecadores; os que se comprazem no mal, no mal envelhecem.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 11), 17, 'O dom de Deus permanece nos justos, e o seu progresso assegura sucesso eterno.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 11), 18, 'Há quem enriqueça, vivendo com parcimónia, e toda a parte da sua recompensa'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 11), 19, 'consiste em dizer: Encontrei repouso, e agora comerei sozinho dos meus bens. (ver nota)'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 11), 20, '(Esse) não considera que o tempo passa, que a morte se avizinha, e que, morrendo, deixará tudo aos outros.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 11), 21, 'Mantém-te firme na tua aliança (com Deus), ocupa-te sempre dela, e envelhece na prática do que te foi mandado.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 11), 22, 'Não te detenhas nas obras dos pecadores, mas confia em Deus e persevera no teu trabalho.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 11), 23, 'Com efeito a Deus é fácil o enriquecer de repente o pobre.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 11), 24, 'A bênção de Deus apressa-se a recompensar o justo, e em pouco tempo o faz crescer e frutificar.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 11), 25, 'Não digas : De que preciso eu? Que bens poderei esperar daqui em diante? (ver nota)'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 11), 26, 'Não digas : Basta-me o que tenho; que mal posso temer para o futuro?'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 11), 27, 'No dia da felicidade não esqueças a desgraça, e no dia da desgraça não esqueças a felicidade.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 11), 28, 'Porque é fácil a Deus, no dia da morte, dar a cada um segundo as suas obras.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 11), 29, 'O mal presente faz esquecer grandes delícias; no fim do homem serão descobertas as suas obras.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 11), 30, 'Não louves nenhum homem antes da morte, porque um homem conhece-se pelos filhos que deixa.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 11), 31, 'Não introduzas em tua casa toda a sorte de pessoas, porque são muitos os embustes do doloso.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 11), 32, 'Assim como sai um hálito fétido dum estômago estragado, assim como a perdiz é metida na gaiola, e a cabra montesa no laço, assim é também o coração do soberbo, assim é aquele que está espiando para ver a queda do seu próximo.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 11), 33, 'Ele arma ciladas, convertendo o bem em mal, e põe mácula nas coisas mais puras.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 11), 34, 'Uma só faísca produz um incêndio; um só doloso derrama muito sangue, e o homem pecador arma traições para o derramar.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 11), 35, 'Evita o homem corrompido, pois está forjando males, para que não faça cair sobre ti uma perpétua infâmia.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 11), 36, 'Dá entrada em tua casa ao estrangeiro, e te derrubará num torvelinho, e te tornará estranho aos teus. (ver nota)');
INSERT INTO bible_chapters (book_id, chapter_number, total_verses)
INSERT INTO bible_verses (chapter_id, verse_number, text) VALUES
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 12), 1, 'Se fizeres bem, sabe a quem o fazes, e receberás gratidão pelos teus benefícios. Faze bem ao justo, e receberás uma grande recompensa, se não dele, pelo menos do Senhor.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 12), 3, 'Não há nada de bom para aquele que sempre faz o mal, e que não dá esmolas, porque o Altíssimo aborrece os pecadores e usa de misericórdia com os penitentes.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 12), 4, 'Dá ao bondoso, e não protejas o pecador, porque (Deus) dará o castigo aos ímpios e aos pecadores, guardando-os para o dia da vingança. (ver nota)'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 12), 5, 'Dá ao que é bom, e não acolhas o pecador.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 12), 6, 'Faze bem ao humilde, e não dês ao ímpio; impede que se lhe dê pão, a fim de se não tornar deste modo mais poderoso do que tu, porque acharás dobrado mal por todos os bens que lhe fizeres. O próprio Altíssimo aborrece também os pecadores, e pagará aos ímpios com o castigo.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 12), 8, 'Não é na prosperidade que o amigo se conhece, e o inimigo não ficará encoberto nas adversidades.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 12), 9, 'Quando um homem é feliz, estão tristes os seus inimigos; quando ele é desgraçado, conhece-se que é seu amigo.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 12), 10, 'Não te fies jamais no teu inimigo, porque a sua malícia é como o azebre que ataca o cobre.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 12), 11, 'Mesmo se ele todo humilhado vier cabisbaixo, põe-te alerta e guarda-te dele.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 12), 12, 'Não o ponhas junto de ti, nem ele se assente à tua direita, para que não suceda que ele se volte para o teu lugar, para ocupar a tua cadeira, e que, reconhecendo, por fim, a verdade das minhas palavras, te sintas compungido pela recordação dos meus avisos.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 12), 13, 'Quem se compadecerá do encantador ferido pela serpente e de todos os que se aproximam das feras ? o mesmo acontecerá com aquele que acompanha com o homem iníquo e que se encontra envolvido em seus pecados.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 12), 14, 'Permanecerá contigo uma hora, mas, se caíres em decadência, não te suportará.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 12), 15, 'O inimigo tem sobre os lábios a doçura, mas no seu coração arma laços para te fazer cair na cova.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 12), 16, 'O inimigo tem lágrimas nos olhos. mas, se encontrar ocasião, não se fartará de (teu) sangue.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 12), 17, 'Se vierem sobre ti os males, verás que ele é a sua primeira origem.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 12), 18, 'O inimigo tem lágrimas nos olhos, mas, fingindo socorrer-te, procurará fazer-te cair.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 12), 19, 'Abanará a cabeça, baterá palmas, e, falando muito entre dentes, mudará de semblante.');
INSERT INTO bible_chapters (book_id, chapter_number, total_verses)
INSERT INTO bible_verses (chapter_id, verse_number, text) VALUES
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 13), 1, 'O que tocar o pez, ficará manchado dele; o que trata com o soberbo, revestir-se-á de soberba.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 13), 2, 'Impõe-se uma pesada carga o que trata com outro mais poderoso que ele; (por isso) não te associes com o que é mais rico do que tu.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 13), 3, 'Como se associará uma panela (de barro) com um caldeirão? Quando estes vasos derem um no outro, ela se quebrará.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 13), 4, 'O rico faz uma injustiça, e (ainda por cima) solta clamores; o pobre, porém, maltratado, guarda silêncio.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 13), 5, 'Enquanto lhe fores útil, utilizará os teus serviços; quando não valeres nada, abandonar-te-á.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 13), 6, 'Se tens, fará convivência contigo, e te esgotará sem nenhuma pena ter de ti.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 13), 7, 'Se lhe fores necessário, ele te enganará, e, sorrindo-se, te dará boas esperanças; falando-te com boas palavras, dir-te-á: De que necessitas tu ?'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 13), 8, 'Confundir-te-á com os seus banquetes, até que te esgote em duas ou três vezes (que o convides), e, por último, zombará de ti; depois, vendo-te, abandonar-te-á e abanará a cabeça escarnecendo de ti. (ver nota)'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 13), 9, 'Humilha-te diante de Deus, e espera (que) a sua mão (obre).'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 13), 10, 'Tem cuidado, não te deixes seduzir para que não caias numa loucura que te humilhe.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 13), 11, 'Não te humilhes na tua sabedoria, não suceda que este abaixamento te arraste para a loucura.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 13), 12, 'Se fores chamado por algum grande, retira-te, porque isso o excitará mais a chamar-te. (ver nota)'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 13), 13, 'Não lhe sejas importuno, para que ele se não desgoste de ti; e não te afastes demasiado, para que te não esqueça.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 13), 14, 'Não pretendas falar com ele, como se fosses seu igual, nem te fies nas suas muitas palavras, porque ele te experimentará, fazendo-te falar muito, e, sorrindo, te interrogará sobre os teus segredos,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 13), 15, 'O seu coração desapiedado conservará todas as tuas palavras, e não te poupará, nem aos maus tratos, nem às prisões.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 13), 16, 'Tem cuidado contigo, e presta bem atenção aos teus ouvidos. pois andas em risco de te perder.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 13), 17, 'Mas, ouvindo essas coisas (as suas palavras), toma-as por um sonho, e vigiarás.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 13), 18, 'Ama a Deus durante toda a tua vida, e invoca-o para tua salvação.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 13), 19, 'Todo o ser vivo ama o seu semelhante; igualmente todo o homem ama o seu próximo.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 13), 20, 'Toda a carne se une à que se lhe assemelha, e todo o homem se une com o seu semelhante.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 13), 21, 'Quando o lobo tiver amizade com o cordeiro, então a terá o pecador com o justo.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 13), 22, 'Que relações pode ter um homem santo com um cão? Ou que sociedade pode ter um homem rico com um pobre?'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 13), 23, 'O asno montês é a presa do leão no deserto; assim também os pobres são a presa dos ricos.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 13), 24, 'E, assim como a humildade é a abominação do soberbo, assim também o pobre é a execração do rico.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 13), 25, 'O rico, se for abalado, é sustido pelos seus amigos; mas o pobre, quando cai, será repelido até pelos seus amigos.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 13), 26, 'Se o rico se engana, tem muitos defensores; se fala com arrogância, justificam-no. Se o pobre se engana, ainda em cima é repreendido; se fala avisadamente, não fazem caso.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 13), 28, 'Se fala o rico, todos se calam, e exaltam até às nuvens as suas palavras.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 13), 29, 'Se fala o pobre, dizem: Quem é este? Se puser um pé em falso, acabá-lo-ão de derrubar.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 13), 30, 'As riquezas são boas para o que não tem pecado na sua consciência; a pobreza é péssima na boca do ímpio.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 13), 31, 'O coração do homem muda-lhe o rosto, quer para bem, quer para mal.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 13), 32, 'O sinal dum bom coração, que é um rosto satisfeito, encontra-se dificilmente e com trabalho.');
INSERT INTO bible_chapters (book_id, chapter_number, total_verses)
INSERT INTO bible_verses (chapter_id, verse_number, text) VALUES
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 14), 1, 'Bem-aventurado o homem que não cometeu faltas com palavras da sua boca, e que não foi torturado pelos remorsos do pecado. Ditoso aquele que não teve tristeza na sua alma, e que não descaiu da sua esperança.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 14), 3, 'A riqueza é inútil ao homem cobiçoso e avaro; e de que serve o ouro ao homem invejoso? (ver nota)'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 14), 4, 'O que amontoa riquezas, defraudando-se do necessário com injustiça, ajunta-as para outros, e outrem se regalará com os seus bens. Para quem será bom aquele que é mau para si? Nem ele goza dos seus bens.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 14), 6, 'Nada há pior do que aquele que é avaro para si mesmo: nisto está o salário da sua malícia. Se faz bem, é só por inadvertência e sem querer; e por último descobre a sua malícia.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 14), 8, 'O olho do invejoso é mau; ele volta o seu rosto e despreza a sua alma. (ver nota)'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 14), 9, 'O olho do avaro não. se sacia com uma porção injusta; não se fartará, enquanto não tiver secado e consumido a sua vida.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 14), 10, 'O olho mau tende para o mal, e não se satisfará de pão, mas estará faminto e melancólico à sua própria mesa. (ver nota)'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 14), 11, 'Filho, se tens posses, faze com elas bem a ti mesmo, e oferece a Deus dignas oblações.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 14), 12, 'Lembra-te que a morte não tarda, e que te foi intimado o ir para o sepulcro, porque é decreto deste mundo o ter infalivelmente de morrer.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 14), 13, 'Faze bem ao teu amigo antes da morte, e, estendendo a mão, dá esmola ao pobre, segundo as tuas posses.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 14), 14, 'Não te prives dum bom dia, e não deixes perder nenhuma parcela do bem que te é concedido.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 14), 15, 'Não vês que hás-de deixar a outros o fruto das tuas penas e dos teus trabalhos, para eles o repartirem, pela sorte, entre si ?'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 14), 16, 'Dá, e recebe, e justifica a tua alma.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 14), 17, 'Pratica a justiça antes da tua morte. porque na sepultura não se vai procurar alimento.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 14), 18, 'Toda a carne envelhece como o feno, e como as folhas que crescem sobre as árvores verdes.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 14), 19, 'Umas folhas nascem, e outras caem: assim nas gerações de carne e de sangue; umas morrem e outras nascem.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 14), 20, 'Toda a obra corruptível virá enfim a perecer, e aquele que a fez irá com ela.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 14), 21, 'Toda a obra excelente será bem apreciada, e o que a executa, nela será honrado.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 14), 22, 'Bem-aventurado o homem que permanece constante na sabedoria. que medita na sua justiça, e que pensa, em seu coração, no olhar de Deus que vê tudo;'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 14), 23, 'que repassa no seu coração os caminhos da sabedoria, e que penetra na inteligência dos seus segredos, indo atrás dela como quem lhe segue o rasto, e se detém sobre os seus caminhos:'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 14), 24, 'que olha pelas suas janelas, que escuta à sua porta;'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 14), 25, 'que repousa junto da sua casa, e que, pregando uma estaca nas suas paredes, assenta ao lado dela a sua pequena cabana, dentro da qual terão perpétua morada (todos) os bens.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 14), 26, 'Ele porá seus filhos debaixo da sua cobertura, e ele mesmo morará debaixo dos seus ramos.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 14), 27, 'À sua sombra será defendido do calor, e repousará na sua glória.');
INSERT INTO bible_chapters (book_id, chapter_number, total_verses)
INSERT INTO bible_verses (chapter_id, verse_number, text) VALUES
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 15), 1, 'O que teme a Deus fará boas obras. e o que pratica a justiça possuirá a sabedoria;'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 15), 2, 'ela lhe sairá ao encontro, qual mãe honorificada, e o acolherá como uma esposa virgem (ver nota)'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 15), 3, 'Ela o sustentará do pão de vida e de inteligência, e lhe dará a beber da água da sabedoria salutar; e se fixará nele, e ele será constante.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 15), 4, 'Será o seu sustentáculo para que não seja confundido, e o exaltará entre os seus próximos.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 15), 5, 'Abrir-lhe-á a boca no meio da assembleia, enchê-lo-á de espírito de sabedoria e inteligência, e revesti-lo-á dum hábito de glória.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 15), 6, 'Acumulará sobre ele um tesouro de regozijo e alegria, e lhe dará por herança um nome eterno. Os homens insensatos não a alcançarão, mas os homens de bom senso encontrar-se-ão com ela. Os insensatos não a verão, porque ela está longe da soberba e do engano.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 15), 8, 'Os homens mentirosos não se lembrarão dela, mas os homens sinceros achar-se-ão com ela, e caminharão felizmente até à (hora da) visita de Deus.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 15), 9, 'O louvor não tem beleza na boca do pecador. (ver nota)'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 15), 10, 'porque a sabedoria sai de Deus; o louvor de Deus acompanha a sabedoria, abunda na boca fiel; é o (soberano) Dominador que lho inspira.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 15), 11, 'Não digas: Deus é causa de estar longe de mim (a sabedoria); não faças tu o que ele aborrece (e tê-la-ás).'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 15), 12, 'Não digas: Ele é que me transviou — porque não lhe são necessários os ímpios.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 15), 13, 'O Senhor aborrece todas as abominações do erro, e não amam tais coisas os que o temem.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 15), 14, 'Deus criou o homem desde o principio, e deixou-o na mão do seu conselho.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 15), 15, 'Deu-lhe mais os seus mandamentos e os seus preceitos.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 15), 16, 'Se quiseres observar os mandamentos e praticar sempre com fidelidade o que é agradável (a Deus), eles te guardarão.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 15), 17, 'Ele pôs diante de ti a água e o fogo; lança a tua mão ao que quiseres.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 15), 18, 'Diante do homem estão a vida e a morte, o bem e o mal; o que lhe agradar, isso lhe será dado. (ver nota)'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 15), 19, 'porque a sabedoria de Deus é grande, e ele é forte no seu poder, e está vendo todos sem cessar.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 15), 20, 'Os olhos do Senhor estão sobre os que o temem, e ele mesmo conhece o proceder do homem.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 15), 21, 'Ele a ninguém mandou obrar impiamente, a ninguém deu permissão de pecar; porque ele não deseja ter uma multidão'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 15), 22, 'de filhos infiéis e inúteis.');
INSERT INTO bible_chapters (book_id, chapter_number, total_verses)
INSERT INTO bible_verses (chapter_id, verse_number, text) VALUES
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 16), 1, 'Não te regozijes com ter muitos filhos, se são ímpios, nem ponhas neles a tua complacência, se não têm temor de Deus.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 16), 2, 'Não tenhas confiança na (duração da) sua vida, nem contes com os seus trabalhos,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 16), 3, 'porque mais vale um (filho) temente a Deus, do que mil filhos ímpios.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 16), 4, 'É mais útil morrer sem filhos, do que deixar filhos ímpios.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 16), 5, 'Por um só homem de juízo será povoado um país, uma tribo de ímpios virá a ficar deserta.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 16), 6, 'Eu vi com os meus olhos muitos exemplos destes, e com os meus ouvidos ouvi outros ainda maiores.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 16), 7, 'O fogo acender-se-á na reunião dos pecadores, e a ira (de Deus) inflamar-se-á contra uma nação incrédula. (ver nota)'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 16), 8, 'Não imploraram perdão dos seus pecados os antigos gigantes, que, confiados na sua força, foram destruídos.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 16), 9, 'Deus não perdoou ao lugar em que Lot morava, e detestou os seus habitantes, por causa da insolência das suas palavras.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 16), 10, 'Não teve compaixão deles, exterminou toda esta nação, que se ensoberbecia nos seus pecados.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 16), 11, 'Ele da mesma sorte (perdeu) os seiscentos mil homens de pé, que conspiraram entre si na dureza do seu coração; ainda que um só fora contumaz, seria grande maravilha, se tivesse ficado sem castigo. (ver nota)'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 16), 12, 'Porque a misericórdia e a ira estão sempre com ele; é poderoso para perdoar, e também o é para derramar a sua ira;'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 16), 13, 'os seus castigos igualam a sua misericórdia, julga o homem segundo as suas obras.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 16), 14, 'Não escapará (ao castigo) o pecador com as suas rapinas, e a paciência do que usa de misericórdia, não tardará em ser recompensada,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 16), 15, 'Toda a misericórdia preparará a cada um o seu lugar. segundo o merecimento das suas obras e segundo a sabedoria (com que tiver vivido) neste lugar de exílio.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 16), 16, 'Não digas: Esconder-me-ei de Deus; quem pensará em mim lá dos altos céus?'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 16), 17, 'Eu não serei conhecido entre um tão grande povo; pois, que coisa é a minha alma entre tamanha multidão de criaturas?'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 16), 18, 'Eis que o céu e o céu dos céus, o abismo, toda a extensão da terra e tudo o que neles se contém, tremerão à sua vista.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 16), 19, 'As montanhas, assim como os outeiros e os fundamentos da terra, quando Deus lhes puser os olhos, todos, a um tempo, serão abalados de terror.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 16), 20, 'E, no meio de tudo isto, ainda permanece insensato o coração (do homem); porém, todo o coração é visto por Deus.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 16), 21, 'Quem é que compreende os seus caminhos, e a tempestade, que a vista do homem nunca verá?'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 16), 22, 'Com efeito, a maior parte das suas obras são ocultas. Mas quem poderá anunciar as obras da sua justiça? Quem as poderá suportar? Porquanto os seus decretos estão longe de alguns, e o exame de todas as coisas é no último dia.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 16), 23, 'O homem sem coração pensa em coisas vãs, e o imprudente e extraviado pensa (somente) em loucuras.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 16), 24, 'Ouve-me, filho, aprende o meu ensinamento e está atento em teu coração às minhas palavras,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 16), 25, 'Eu te darei instruções muito acertadas e te manifestarei os arcanos da sabedoria. Está atento em teu coração às minhas palavras, e te direi, com rectidão de espírito, as maravilhas que desde o princípio Deus fez brilhar nas suas obras, e te mostrarei com verdade a sua ciência.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 16), 26, 'Por decisão de Deus, existem desde o princípio, as suas obras; desde que as criou, distinguiu-as em partes, e (colocou) as principais delas segundo as suas épocas.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 16), 27, 'Adornou para sempre as suas obras; elas não sentiram fome nem fadiga, e nunca interromperam o seu trabalho.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 16), 28, 'Nunca nenhuma delas embaraçará a outra.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 16), 29, 'Não sejas incrédulo à palavra do Senhor.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 16), 30, 'Depois disto, olhou Deus para a terra, e a encheu dos seus bens. (ver nota)'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 16), 31, 'Mostrou à sua superfície animais de todas as espécies, e é a ela que eles voltam.');
INSERT INTO bible_chapters (book_id, chapter_number, total_verses)
INSERT INTO bible_verses (chapter_id, verse_number, text) VALUES
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 17), 1, 'Deus criou o homem da terra, e formou-o à sua imagem. E ele o fez de novo voltar à terra, Revestiu-o de força segundo a sua natureza.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 17), 3, 'Assinalou-lhe determinado tempo e número de dias, e deu-lhe poder sobre tudo o que há na terra.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 17), 4, 'Ele o fez ser temido de toda a carne, e deu-lhe o império sobre os animais e sobre as aves. Deu-lhe uma auxiliar semelhante a ele, da sua própria substância. Dotou-os de discernimento, língua, olhos, ouvidos, coração para pensar, e encheu-os de saber e inteligência.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 17), 6, 'Criou neles a ciência do espírito, encheu de sabedoria o seu coração, e mostrou-lhes os males e os bens. Pôs o seu olhar sobre os seus corações, para lhes fazer ver as maravilhas das suas obras,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 17), 8, 'a fim de que louvassem a santidade do seu nome, glorificando-o pelas suas maravilhas e publicando a magnificência das suas obras.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 17), 9, 'Deu-lhes, além disso, a instrução, e entregou-lhes em herança a lei da vida.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 17), 10, 'Fez com eles uma aliança eterna. e mostrou-lhes a sua justiça e os seus juízos.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 17), 11, 'Com os seus próprios olhos viram as grandezas da sua glória, e os seus ouvidos ouviram a majestade da sua voz. Ele disse-lhes: Guardai-vos de toda a iniquidade.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 17), 12, 'Impôs a cada um deveres para com o próximo.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 17), 13, 'O proceder deles está-lhe sempre presente, não escapa aos seus olhos.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 17), 14, 'A cada nação constituiu quem a governasse,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 17), 15, 'mas Israel foi visivelmente a porção (privilegiada) de Deus.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 17), 16, 'Todas as suas obras estão diante de Deus como o Sol, e os seus olhos estão sempre fixos no seu proceder.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 17), 17, 'As leis divinas não foram obscurecidas pela maldade deles, e todas as suas iniquidades estão diante do Senhor.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 17), 18, 'A esmola do homem é para Deus como um selo, e ele conserva a beneficência do homem como a menina dos olhos.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 17), 19, 'Levantar-se-á depois (para juízo). dará a cada um o que for devido. e fá-los-á voltar às profundezas da terra.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 17), 20, 'Aos penitentes, porém, abre o caminho da justiça; conforta os desfalecidos. e destina-lhes a verdade por herança.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 17), 21, 'Converte-te ao Senhor, deixa os teus pecados;'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 17), 22, 'suplica ante a sua face e diminui as tuas ofensas.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 17), 23, 'Volta para o Senhor, afasta-te da tua injustiça, e tem grande horror àquilo que é abominável:'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 17), 24, 'reconhece a justiça dos juízos de Deus. e persevera no estado em que te colocou e na invocação do Deus Altíssimo.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 17), 25, 'Acompanha com o povo santo, com aqueles que vivem e que dão glória a Deus.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 17), 26, 'Não te demores no erro dos ímpios, louva (a Deus) antes da morte. O louvor do morto terminou, porque ele é como se não existisse. (ver nota)'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 17), 27, 'Louva-o enquanto vives, louva-o enquanto tens vida e saúde, louva a Deus e glorifica-te nas suas misericórdias.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 17), 28, 'Quão grande é a misericórdia do Senhor, e a sua compaixão para com todos os que se convertem a ele!'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 17), 29, 'Com efeito, nem tudo se pode encontrar nos homens, visto que os filhos dos homens não são imortais, e se comprazem na frivolidade da malícia. (ver nota)'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 17), 30, 'Que coisa há mais luminosa do que o Sol? E contudo ele eclipsa-se. Que coisa há pior do que os pensamentos da carne e do sangue? Ora isto será punido.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 17), 31, 'O Sol contempla o exército (dos astros) das alturas do céu, mas todos os homens não são mais do que terra e cinza.');
INSERT INTO bible_chapters (book_id, chapter_number, total_verses)
INSERT INTO bible_verses (chapter_id, verse_number, text) VALUES
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 18), 1, 'Aquele que vive eternamente, criou todas as coisas, sem excepção. Só o Senhor será reconhecido justo. Ele é o rei invencível que subsiste para sempre.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 18), 2, 'Quem é capaz de contar as suas obras?'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 18), 3, 'Quem poderá penetrar as suas maravilhas?'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 18), 4, 'Quem poderá descrever o poder (soberano) da sua grandeza? Quem empreenderá enumerar as suas misericórdias?'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 18), 5, 'Nada se pode diminuir ou acrescentar, nem é possível compreender as maravilhas de Deus.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 18), 6, 'Quando o homem tiver acabado, então estará no começo, e, quando cessar (a pesquisa), ficará perplexo. (ver nota)'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 18), 7, 'Que é o homem, e para que presta? E que bem ou que mal pode ele fazer? (ver nota)'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 18), 8, 'A duração dos dias do homem, quando muito, é de cem anos, mas, qual gota de água do mar, ou grão de areia, assim são estes poucos anos comparados com o dia da eternidade.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 18), 9, 'Por isso é que o Senhor é paciente com os homens, e derrama sobre eles a sua misericórdia.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 18), 10, 'Ele vê que a presunção do seu coração é má, e reconhece que o seu fim é deplorável.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 18), 11, 'Por isso é que os trata com a plenitude da sua doçura, e mostra-lhes o caminho da equidade.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 18), 12, 'A misericórdia do homem tem por objecto o seu próximo, porém a misericórdia de Deus estende-se a todo o ser vivo.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 18), 13, 'Cheio de compaixão, ensina e disciplina (os homens), como um pastor faz ao seu rebanho.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 18), 14, 'Compadece-se daquele que recebe a doutrina da sua misericórdia, e do que se apressa a cumprir os seus mandamentos.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 18), 15, 'Filho, não mistures a repreensão com o benefício, nem juntes às tuas dádivas a tristeza duma palavra má. (ver nota)'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 18), 16, 'Porventura o orvalho não mitiga o calor ardente? Assim vale mais a palavra (doce) do que a dádiva.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 18), 17, 'Porventura a palavra (doce) não vale mais que o próprio dom? Mas uma e outra coisa se encontra no homem justo.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 18), 18, 'O insensato impropera àsperamente; o dom do invejoso consome os olhos.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 18), 19, 'Antes de Julgar (os outros) procura ser justo, e aprende, antes de falar.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 18), 20, 'Antes da enfermidade emprega cuidados (para a evitar), interroga-te a ti mesmo antes do juízo, e encontrarás misericórdia diante de Deus.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 18), 21, 'Humilha-te antes da doença, e mostra o teu proceder no tempo da enfermidade.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 18), 22, 'Nada te embarace de orar sempre, e não te envergonhes de praticar boas obras até à morte, porque a recompensa de Deus dura para sempre.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 18), 23, 'Prepara a tua alma antes da oração, e não sejas como um homem que tenta a Deus.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 18), 24, 'Lembra-te da ira do último dia, e do tempo em que Deus castigará, desviando o seu rosto.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 18), 25, 'Lembra-te da pobreza no tempo da abundância, e das necessidades da indigência no dia das riquezas.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 18), 26, 'Desde manhã até à tarde se muda o tempo, e tudo isto se faz num momento aos olhos de Deus.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 18), 27, 'o homem sábio andará com temor em tudo, e nos dias do pecado se guardará da preguiça, (ver nota)'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 18), 28, 'Todo o homem hábil conhece a sabedoria, e dá louvor ao que a encontrou.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 18), 29, 'Os homens sensatos nas palavras, obram também com sabedoria, compreendem a verdade e a justiça, e espalham como chuva provérbios e sentenças.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 18), 30, 'Não te deixes ir atrás das tuas más tendências e refreia os teus apetites.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 18), 31, 'Se condescenderes com a tua alma no que deseja, ela fará de ti a alegria dos teus inimigos.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 18), 32, 'Não te comprazas em ir às assembleias, mesmo as mais pequenas, porque nelas comete-se incessantemente o mal.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 18), 33, 'Não te empobreças, pedindo dinheiro emprestado para rivalizares (com os outros em despesas), não tendo tu nada no bolso; isto equivaleria a seres inimigo da tua própria vida.');
INSERT INTO bible_chapters (book_id, chapter_number, total_verses)
INSERT INTO bible_verses (chapter_id, verse_number, text) VALUES
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 19), 1, 'O operário dado ao vinho não enriquecerá. Aquele que despreza as coisas pequenas, pouco a pouco cairá. O vinho e as mulheres desencaminham os próprios sábios, e tornam culpáveis os homens sensatos.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 19), 3, 'Aquele que se junta com prostitutas será mau, chegará a ser o pasto da podridão e dos vermes, ficará sendo um grande exemplo, e a sua alma será tirada do número (dos vivos).'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 19), 4, 'O crédulo é leve de coração e ficará prejudicado, e o que peca contra a sua alma será tratado com desprezo.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 19), 5, 'Aquele que se deleita com a iniquidade será desonrado; o que aborrece a correcção, abreviará a sua vida; o que aborrece a loquacidade, extingue a malícia.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 19), 6, 'O que peca contra a sua alma arrepender-se-á de o ter feito, e o que se deleita na malícia será desonrado, Não repitas uma palavra má e ofensiva, e não serás diminuído.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 19), 8, 'Não contes os teus pensamentos nem ao amigo nem ao inimigo, e, se cometeste algum pecado, não o descubras.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 19), 9, 'Com efeito, ouvir-te-á e se guardará de ti. e, aparentando desculpar o teu pecado, te aborrecerá, e estará sempre presente (para te prejudicar).'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 19), 10, 'Ouviste alguma palavra contra o teu próximo? Morra dentro de ti, ficando seguro de que ela te não fará rebentar.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 19), 11, 'O insensato está como com dores de parto, por causa duma palavra, como a mulher que geme para dar à luz uma criança. (ver nota)'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 19), 12, 'Como seta cravada na carne da coxa, assim é a palavra no coração do insensato.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 19), 13, 'Admoesta o teu amigo, porque talvez não tenha compreendido (que fez mal) e te diga; Eu não fiz tal — e para que, se o fez, o não torne a fazer.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 19), 14, 'Repreende o teu próximo porque talvez não tenha dito (o que se lhe atribui), e para que, se o disse, o não torne a dizer.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 19), 15, 'Repreende o teu amigo, porque muitas vezes se diz o que não é verdade;'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 19), 16, 'não acredites em tudo o que se diz. Homem há que peca pela língua, mas não do coração.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 19), 17, 'E quem há que não tenha pecado com a língua? Repreende o teu próximo antes de o ameaçares,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 19), 18, 'e dá lugar ao temor do Altíssimo, porque toda a sabedoria é temor de Deus, nela está o temer a Deus, e em toda a sabedoria há o cumprimento da lei.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 19), 19, 'Não é sabedoria a habilidade de fazei mal. nem o pensar dos pecadores é prudência.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 19), 20, 'Há uma malícia (habilidosa) que é execrável, e há (certos) insensatos que (apenas) têm falta de sabedoria'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 19), 21, 'Vale mais um homem que tem pouca sabedoria e que é falto de senso, mas que tem o temor de Deus, do que o que tem muito senso, mas que viola a lei do Altíssimo.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 19), 22, 'Há uma habilidade certeira, mas que é injusta.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 19), 23, 'Há quem fale com firmeza (rude), mas expondo a verdade. Há quem se humilhe maliciosamente com o coração cheio de dolo.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 19), 24, 'Há quem se submeta excessivamente, com uma profunda humilhação. Há quem abaixe a sua cabeça, fingindo não ver o que é segredo;'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 19), 25, 'porém, se a debilidade o impede de pecar, quando encontrar ocasião de fazer mal, fá-lo-á.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 19), 26, 'Pelo semblante se conhece o homem; pelo seu aspecto se conhece o homem sensato.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 19), 27, 'O vestuário do seu corpo, o riso dos dentes e o andar do homem, dão a conhecer o que ele é.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 19), 28, 'Há uma correcção falsa, que nasce da ira dum insolente, e há um juízo, que se prova não ser justo, e há quem se cale mostrando ser prudente.');
INSERT INTO bible_chapters (book_id, chapter_number, total_verses)
INSERT INTO bible_verses (chapter_id, verse_number, text) VALUES
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 20), 1, 'Quanto melhor é repreender do que irritar-se, e não impedir de falar aquele que confessa a sua falta! Como o eunuco que, concupiscentemente, procura desonrar a donzela,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 20), 3, 'assim é o que, por violência, faz um julgamento injusto.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 20), 4, 'Como é bom que o corrigido manifeste o seu arrependimento! Assim evitarás o pecado voluntário.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 20), 5, 'Há quem, estando calado, seja tido por sábio, e quem se torne odioso por ser descomedido no falar.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 20), 6, 'Há tal que se cala por não saber falar; e há tal que se cala, porque sabe qual é a ocasião oportuna.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 20), 7, 'O homem sábio está em silêncio até um certo tempo, mas o leviano e o imprudente não esperam a ocasião.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 20), 8, 'Aquele que fala muito prejudica a sua alma, e aquele que injustamente se excede será detestado.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 20), 9, 'O homem sem disciplina pode ser bem sucedido no mal, porém aquilo que ele inventa pode converter-se em sua própria ruína.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 20), 10, 'Há dom que não é útil, e há dom que é duplamente recompensado.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 20), 11, 'Há glória que leva à ruína, e há humilhação seguida de exaltação.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 20), 12, 'Há quem compre muitas coisas por baixo prego, mas que (de facto) as paga pelo séptuplo do seu valor. (ver nota)'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 20), 13, 'O sábio torna-se amável pelas suas palavras; porém as graças dos insensatos perder-se-ão.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 20), 14, 'O donativo do insensato não te será útil, porque ele tem sete olhos para te considerar. (ver nota)'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 20), 15, 'Ele dará pouco, e lançá-lo-á muitas vezes em rosto; quando a sua boca se abre, é como um incêndio.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 20), 16, 'Um empresta hoje, e torna-o a pedir amanhã: homem assim torna-se odioso.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 20), 17, 'O insensato não terá amigo, e o bem que ele faz não será agradecido,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 20), 18, 'porque os que comem o seu pão têm língua falsa. Quantas vezes e quantos homens escarnecerão dele?'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 20), 19, 'De facto dá, sem discernimento, o que devia reservar, e também aquilo que não devia guardar.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 20), 20, 'A falta duma língua enganadora é como uma queda sobre o pavimento; assim a ruína dos maus virá de súbito.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 20), 21, 'O homem desagradável é como um conto vão, que anda sempre na boca de gente mal educada. (ver nota)'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 20), 22, 'Será mal recebida a máxima procedente da boca do insensato, porque não a diz a seu tempo.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 20), 23, 'Há quem se abstenha de pecar por falta de meios, e sofra por ter de estar na inacção.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 20), 24, 'Há quem perca a sua alma por causa do respeito humano; perde-a, cedendo a uma pessoa imprudente, a si mesmo se perde, por atender demasiadamente a uma pessoa.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 20), 25, 'Tal há que, por falsa vergonha, promete ao seu amigo, e arranja gratuitamente nele um inimigo. (ver nota)'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 20), 26, 'A mentira é no homem uma vergonhosa mancha, e ela encontra-se habitualmente na boca da gente sem educação.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 20), 27, 'Melhor é um ladrão do que um homem que mente de contínuo, mas ambos terão por herança a perdição.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 20), 28, 'Os costumes dos homens mentirosos são sem honra, e a sua confusão acompanha-os sempre.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 20), 29, 'O sábio atrai a si a estima com as suas palavras, e o homem prudente agradará aos grandes.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 20), 30, 'Aquele que cultiva a sua terra, tornará mais alto o monte dos seus frutos, o que pratica obras de justiça será exaltado, e o que agrada aos grandes fugirá da iniquidade.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 20), 31, 'Os presentes e as dádivas cegam os olhos dos juízes, são como uma mordaça na sua boca, que os torna mudos e os impede de castigar.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 20), 32, 'Sabedoria escondida é tesouro invisível; que utilidade haverá em ambas estas coisas?'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 20), 33, 'Melhor é o homem que encobre a sua insipiência do que aquele que esconde a sua sabedoria.');
INSERT INTO bible_chapters (book_id, chapter_number, total_verses)
INSERT INTO bible_verses (chapter_id, verse_number, text) VALUES
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 21), 1, 'Filho, pecaste? Não tornes a pecar, mas faze oração pelas tuas faltas passadas, para que te sejam perdoadas.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 21), 2, 'Foge dos pecados como de uma serpente, porque, se te aproximares, serás apanhado.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 21), 3, 'Os seus dentes são dentes de leão, que matam as almas dos homens.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 21), 4, 'Todo o pecado é como uma espada de dois fios; a sua ferida não tem cura.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 21), 5, 'O ultraje e as violências aniquilam a riqueza; a mais opulenta casa será destruída pela soberba; do mesmo modo os bens do soberbo serão arrancados pela raiz.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 21), 6, 'A súplica do pobre chegará desde a sua boca até aos ouvidos de Deus, e prontamente lhe será feita justiça. Aquele que aborrece a repreensão caminha por cima das pegadas do pecador; aquele que teme a Deus converter-se-á do (intimo do) seu coração.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 21), 8, 'O homem poderoso de língua insolente dá-se a conhecer ao longe, mas o sábio sabe escapar-se dele.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 21), 9, 'Aquele que edifica a sua casa à custa alheia, é como o que ajunta as suas pedras no inverno.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 21), 10, 'A assembleia dos pecadores é como um montão de estopa: o seu fim será a fogueira.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 21), 11, 'O caminho dos pecadores é calcetado de pedras unidas entre si, mas vai dar à habitação dos mortos, às trevas e aos tormentos.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 21), 12, 'Aquele que guarda a justiça penetrará o espírito dela.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 21), 13, 'A sabedoria e o bom senso são a consumação do temor de Deus.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 21), 14, 'Aquele que não é sábio no bem, nunca será (bem) instruído.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 21), 15, 'Há uma sabedoria que é fecunda no mal, e não há bom senso onde há amargura.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 21), 16, 'A ciência do sábio derrama-se abundantemente, como (água de) uma inundação, e o seu conselho permanece como uma fonte de vida.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 21), 17, 'O coração do insensato é como um vaso rachado: nada pode reter da sabedoria.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 21), 18, 'O sábio, ouvindo qualquer palavra judiciosa, louvá-la-á e aplicá-la-á a si; se porém a ouve o voluptuoso, não lhe agradará, e deitá-la-á para trás das costas.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 21), 19, 'A conversação do insensato é (aborrecida) como uma carga durante a viagem, mas nos lábios do sensato achar-se-á a graça.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 21), 20, 'A boca do homem prudente é buscada na assembleia: as pessoas pensarão nas suas palavras dentro dos seus corações.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 21), 21, 'A sabedoria é para o insensato como uma casa arruinada; a ciência do insensato reduz-se a palavras sem sentido.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 21), 22, 'A doutrina é para o insensato como grilhões nos pés, e como algemas na mão direita. (ver nota)'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 21), 23, 'O insensato, quando se ri, levanta a sua voz; mas o varão sábio apenas se sorri discretamente.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 21), 24, 'A ciência é para o homem prudente um ornamento de ouro, e como um bracelete no seu braço direito.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 21), 25, 'O pé do insensato é fácil em se meter em casa do vizinho, porém o homem educado retrai-se diante duma pessoa poderosa.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 21), 26, 'O insensato olha pela janela dentro duma casa, mas o homem educado conserva-se fora.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 21), 27, 'É má educação escutar a uma porta; ao prudente será insuportável esta grosseria.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 21), 28, 'Os lábios dos imprudentes dirão fatuidades, mas as palavras dos homens prudentes serão pesadas na balança.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 21), 29, 'O coração dos insensatos está na sua boca, e a boca dos sábios está no seu coração.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 21), 30, 'Quando o ímpio amaldiçoa o inimigo, amaldiçoa-se a si mesmo.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 21), 31, 'O mexeriqueiro mancha-se a si próprio, e é aborrecido de todos; o que mora com ele será odioso; o homem prudente, que se cala, será honrado.');
INSERT INTO bible_chapters (book_id, chapter_number, total_verses)
INSERT INTO bible_verses (chapter_id, verse_number, text) VALUES
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 22), 1, 'Ao preguiçoso é atirado lodo e todos falam dele com desprezo. Ao preguiçoso é atirado excremento de bois e todo o que o tocar sacudirá as mãos. (ver nota)'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 22), 3, 'O filho mal educado é a vergonha do pai; a filha (semelhante) será pouco estimada.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 22), 4, 'A filha prudente será uma herança para seu marido, mas aquela, cujo procedimento envergonha, será a desonra de seu pai.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 22), 5, 'A mulher atrevida cobre de confusão seu pai e seu marido, e não será inferior aos ímpios: dum e doutro andará desprezada.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 22), 6, 'Um discurso fora de propósito é como a música em ocasião de luto; o castigo e a doutrina em todo o tempo (oportuno) são (empregados pela) sabedoria. (ver nota)'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 22), 7, 'Aquele que ensina o insensato é como o que quer tornar a unir os cacos de um vaso quebrado.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 22), 8, 'O homem que se põe a contar alguma coisa ao que o não ouve, é como o que desperta o adormecido dum pesado sono.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 22), 9, 'Aquele que fala da sabedoria a um insensato, é como o que fala com um homem adormecido, o qual, no fim do discurso, dirá: Quem é este?'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 22), 10, 'Chora sobre o morto porque lhe faltou a luz, e chora sobre o insensato, porque lhe falta o siso. (ver nota)'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 22), 11, 'Chora pouco sobre o morto, porque ele entrou no descanso;'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 22), 12, 'mas a vida criminosa do mau é pior que a morte.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 22), 13, 'O pranto sobre o morto dura sete dias. mas sobre o insensato e o ímpio dura toda a sua vida.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 22), 14, 'Não fales muito com o estulto, e não acompanhes com o insensato.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 22), 15, 'Guarda-te dele, para que não tenhas inquietações, e não serás contaminado com o seu pecado.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 22), 16, 'Desvia-te dele, e acharás descanso, e não te enfastiarás com a sua estultícia.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 22), 17, 'Que coisa haverá mais pesada do que o chumbo? E que outro nome se lhe pode dar melhor do que o de insensato?'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 22), 18, 'A areia, o sal e qualquer massa de ferro, são mais fáceis de levar do que o imprudente, o insensato e o ímpio.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 22), 19, 'A travação de madeixa, bem ligada e disposta no alicerce do edifício, não se desunirá; assim, também, o coração firmado sobre um bem pensado conselho.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 22), 20, 'A resolução do homem sensato nunca enfraquecerá com o medo.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 22), 21, 'Assim como uma paliçada posta em lugares elevados e uma parede de pedregulho, sem argamassa, não podem resistir à violência do vento,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 22), 22, 'também o coração tímido, de pensamentos insensatos, não resistirá à violência do temor.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 22), 23, 'O coração do insensato, oscilante nos seus pensamentos, não temerá em tempo algum; assim também (por outro motivo) o que está sempre firme nos preceitos de Deus. (ver nota)'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 22), 24, 'Aquele que pica o olho, faz sair dele lágrimas; o que pica o coração excita o sentimento.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 22), 25, 'Aquele que atira com uma pedra aos pássaros, fá-los fugir; assim também aquele que diz injúrias ao seu amigo, desfaz a amizade.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 22), 26, 'Ainda que tenhas arrancado a espada contra o teu amigo, não desesperes, porque o regresso é possível.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 22), 27, 'Ainda que tenhas dito ao teu amigo palavras contristadoras, não temas, porque a reconciliação é possível, excepto se se trata de afrontas, impropérios, orgulhoso desdém, revelação de segredo e golpes à traição: em todos estes casos fugirá de ti o amigo.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 22), 28, 'Permanece fiel ao teu amigo na sua pobreza, para que também te alegres com ele nas suas prosperidades.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 22), 29, 'Conserva-te fiel a ele no tempo da sua tribulação, para que tenhas parte com ele na sua herança.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 22), 30, 'O vapor e o fumo elevam-se da fornalha antes do fogo; assim também as injúrias, ultrajes e ameaças precedem a efusão de sangue.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 22), 31, 'Eu não me envergonharei de saudar o meu amigo, nem me esconderei da sua presença, e, se me vierem males por causa dele, sofrê-los-ei.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 22), 32, 'Mas toda a pessoa que souber isto se acautelará dele.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 22), 33, 'Quem porá uma guarda à minha boca, e um selo inviolável sobre os meus lábios, para que eu não caia por sua causa, e para que a minha língua me não perca?');
INSERT INTO bible_chapters (book_id, chapter_number, total_verses)
INSERT INTO bible_verses (chapter_id, verse_number, text) VALUES
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 23), 1, 'Senhor, que és meu pai e dono da minha vida, não me abandones ao conselho dos meus lábios, nem permitas que eu caia por causa deles.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 23), 2, 'Quem aplicará ao meu pensamento o açoite (das correcções)e (fará sentir) ao meu coração a disciplina da sabedoria, para eu não ser poupado no respeitante às minhas faltas, a fim de que não apareçam os meu pecados.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 23), 3, 'para que se não aumentem as minhas ignorâncias, se não multipliquem os meus delitos, não abundem os meus pecados, e eu não caia diante dos meus adversários.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 23), 4, 'e folgue de me ver arruinado o meu inimigo? Senhor, meu pai e Deus da minha vida, não me abandones às suas sugestões.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 23), 5, 'Não permitas a imodéstia dos meus olhares, e afasta de mim todo o (mau) desejo.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 23), 6, 'Afasta de mim a intemperança, e não se apodere de mim a paixão da impureza, e não me entregues a uma alma sem vergonha e sem recato.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 23), 7, 'Ouvi, filhos, as regras que vos dou sobre a moderação da língua Aquele que as guardar, não perecerá pelos lábios, nem cairá em acções criminosas.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 23), 8, 'O pecador será colhido na sua leviandade, e o soberbo e o maldizente encontrarão nela motivos de queda.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 23), 9, 'A tua boca não se acostume ao juramento, porque isto é causa de muitas quedas.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 23), 10, 'O nome de Deus não esteja sempre na tua boca (para jurar), e não mistures nas tuas conversas os nomes dos santos, porque nisto não serás isento de falta.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 23), 11, 'Pois, assim como o escravo, posto frequentemente à tortura, não se livra das pisaduras, assim todo o homem que jura e invoca (a cada passo) o nome de Deus, não será de todo isento de pecado.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 23), 12, 'O homem que jura muito será cheio de iniquidade, e a desgraça não se apartará de sua casa.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 23), 13, 'Se não cumprir o juramento, o seu pecado será sobre ele; se dissimular, peca duplamente.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 23), 14, 'Se jurar em vão, não terá desculpa, e a sua casa será cheia de castigos.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 23), 15, 'Há uma outra palavra que merece a morte, e nunca ela se ouça entre os descendentes de Jacob. (ver nota)'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 23), 16, 'Tudo isto será retirado dos homens pios, que não serão envoltos em tais pecados.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 23), 17, 'Não se acostume a tua boca a palavras desordenadas, porque nelas há sempre pecado.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 23), 18, 'Lembra-te do teu pai e da tua mãe, quando te sentares no meio dos grandes,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 23), 19, 'para não acontecer que Deus se esqueça de ti, diante desses mesmos grandes, e, enfatuado com a tua familiaridade, sofras algum impropério, (para não acontecer que) chegues a desejar antes não ter nascido, e amaldiçoes o dia do teu nascimento.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 23), 20, 'O homem acostumado a dizer impropérios nunca se corrigirá em toda a sua vida.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 23), 21, 'Duas sortes de pessoas pecam muitas vezes, e a terceira atrai a ira e a perdição. A alma ardente como um fogo aceso não se acalma sem ter devorado alguma coisa.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 23), 23, 'O homem, que abusa do seu corpo, não terá sossego enquanto não acender o fogo.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 23), 24, 'Todo o pão é doce para o homem voluptuoso; não se cansará de pecar até ao fim da vida. Todo o homem que desonra o seu tálamo (conjugal), despreza a sua alma, dizendo: Quem me vê?'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 23), 26, 'As trevas cercam-me, as paredes escondem-me, e ninguém de parte alguma olha para mim; de quem tenho eu receio? O Altíssimo não se lembrará dos meus pecados. (Esse homem) não considera que os olhos do Senhor vêem todas as coisas, que um semelhante temor humano expele de si o temor de Deus, e que os olhos dos homens são unicamente os que o fazem temer.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 23), 28, 'Não sabe que os olhos do Senhor são muito mais luminosos do que o Sol, que em torno estão vendo todos os caminhos dos homens, que penetram o profundo do abismo e os corações dos mesmos homens, até aos mais ocultos esconderijos.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 23), 29, 'Com efeito, o Senhor Deus, assim como conhecia todas as coisas antes de as ter criado, assim também agora, depois que as criou, as vê todas.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 23), 30, 'Este tal será punido nas praças da cidade, será posto em fuga como um potro de égua, e, onde ele menos o esperar, será apanhado. (ver nota)'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 23), 31, 'Será vexado diante de todos. por isso mesmo que não compreendeu o temor do Senhor.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 23), 32, 'Assim (perecerá) também toda a mulher que deixa o seu marido, e que lhe dá por herdeiro o fruto duma união adúltera.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 23), 33, 'Porque primeiramente ela foi desobediente à lei do Altíssimo; em segundo lugar pecou contra o seu marido: em terceiro lugar cometeu um adultério. e deu-se a si filhos doutro, que não era seu esposo.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 23), 34, 'Esta mulher será levada à assembleia, e serão lançados os olhares sobre seus filhos.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 23), 35, 'Os seus filhos não lançarão raízes, os ramos dela não darão fruto.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 23), 36, 'Deixará uma memória maldita, e nunca mais se apagará a sua infâmia.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 23), 37, 'E os que vierem depois dela conhecerão que não há coisa melhor do que o temor de Deus e que nada há mais doce do que observar os mandamentos do Senhor.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 23), 38, 'É uma grande glória seguir o Senhor, porque é dele que se receberá larga vida.');
INSERT INTO bible_chapters (book_id, chapter_number, total_verses)
INSERT INTO bible_verses (chapter_id, verse_number, text) VALUES
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 24), 1, 'A sabedoria faz o seu próprio elogio, honra-se em Deus, gloria-se no meio do seu povo; abre a sua boca na Assembleia do Altíssimo, glorifica-se diante dos seus exércitos, (ver nota)'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 24), 3, 'é exaltada no meio do seu povo, e admirada na assembleia santa.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 24), 4, 'Entre a multidão dos escolhidos, recebe louvores, e entre os abençoados recebe bênçãos.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 24), 5, 'Ela diz: Eu saí da boca do Altíssimo, primogénita antes de todas as criaturas.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 24), 6, 'Eu fiz com que nascesse nos céus uma luz indefectível, e como uma névoa cobri toda a terra.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 24), 7, 'Eu habitei nos lugares mais altos, e o meu trono é sobre uma coluna de nuvem.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 24), 8, 'Sozinha percorri a abóbada celeste, penetrei na profundidade do abismo, andei sobre as ondas do mar.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 24), 9, 'Caminhei por toda a terra. Imperei sobre todos os povos'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 24), 10, 'e sobre todas as nações.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 24), 11, 'Tive debaixo dos meus pés, com o meu poder, os corações de todos os grandes e pequenos; entre todos busquei um lugar de repouso, e uma morada na herança do Senhor.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 24), 12, 'Então o Criador de tudo deu-me os seus preceitos, falou-me; aquele que me criou descansou no meu tabernáculo.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 24), 13, 'Disse-me: Habita em Jacob, possui a tua herança em Israel, e lança raízes entre os meus escolhidos.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 24), 14, 'Eu fui criada desde o princípio, antes dos séculos, e não deixarei de existir até ao fim dos séculos, e exerci diante dele o meu ministério na morada santa.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 24), 15, 'Assim me fixei em Sião, repousei na cidade santa, e em Jerusalém está o meu poder.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 24), 16, 'Deitei raízes no meio dum povo glorioso, cuja herança está na parte do meu Deus, e na assembleia dos santos estabeleci a minha morada.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 24), 17, 'Elevei-me como o cedro do Líbano, como o cipreste do monte Sião. (ver nota)'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 24), 18, 'Cresci como a palmeira de Cades, como as roseiras de Jericó.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 24), 19, 'Elevei-me como uma formosa oliveira nos campos, como o plátano no caminho à beira das águas.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 24), 20, 'Difundi um perfume como o cinamomo e o bálsamo aromático, e como mirra escolhida exalei suave odor.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 24), 21, 'Perfumei a minha habitação como o estoraque, o gálbano, o onix e a mirra, e como a gota de incenso caída por si própria; a minha fragrância é como a dum bálsamo sem mistura.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 24), 22, 'Estendi os meus ramos como o terebinto; os meus ramos são ramos de honra e de graça.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 24), 23, 'Como a vide lancei flores dum agradável cheiro; e as minhas flores dão frutos de glória e de riqueza.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 24), 24, 'Eu sou a mãe do amor formoso, do temor, da ciência e da santa esperança.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 24), 25, 'Em mim há toda a graça do caminho e da verdade, em mim toda a esperança da vida e da virtude.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 24), 26, 'Vinde a mim todos os que me desejais, e enchei-vos dos meus frutos,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 24), 27, 'porque o meu espírito é mais doce do que o mel, e possuir-me é mais suave que o favo de mel.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 24), 28, 'A minha memória durará por toda a série dos séculos.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 24), 29, 'Aqueles que me comem terão ainda fome. e os que me bebem terão ainda sede. (ver nota)'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 24), 30, 'Aquele que me ouve não será confundido, e os que agem por mim não pecarão.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 24), 31, 'Aqueles que me tornam conhecida terão a vida eterna.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 24), 32, 'Tudo isto é o livro da vida, a aliança do altíssimo e o conhecimento da verdade. (ver nota)'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 24), 33, 'Moisés deu-nos a lei com os preceitos da justiça, a herança da casa de Jacob e as promessas feitas a Israel.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 24), 34, '(O Senhor) prometeu a Davide, seu servo, que faria sair dele um rei fortíssimo, o qual se sentaria sobre um trono de glória para sempre.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 24), 35, 'É ela (a lei) que espalha ,a sabedoria como o Fison (as suas águas), e como o Tigre no tempo dos frutos novos.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 24), 36, 'É ela que faz transbordar a inteligência como o Eufrates, como o Jordão no tempo da ceifa.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 24), 37, 'É ela que derrama a ciência como o Nilo, e que aumenta as suas águas como o Geon no tempo da vindima.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 24), 38, 'Nem o primeiro (que a estudou) a acabou de conhecer, nem, igualmente, o último de a descobrir.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 24), 39, 'Os seus pensamentos são mais vastos do que o mar, e os seus conselhos mais profundos do que o grande abismo.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 24), 40, 'Eu, a Sabedoria, fiz correr os rios. (ver nota)'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 24), 41, 'Eu sou como o caminho da água imensa derivada dum rio, como o canal duma ribeira, e como um aqueduto que sai do paraíso.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 24), 42, 'Eu disse: Regarei as plantas do meu jardim, saciarei de água os frutos do meu prado.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 24), 43, 'E eis que o meu curso de água se tornou um caudaloso rio, e o meu rio se tornou um mar.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 24), 44, 'Com efeito, a luz da doutrina, com que a todos ilustro, é como a luz da aurora; eu a manifestarei ao longe.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 24), 45, 'Penetrarei todas as partes inferiores da terra, lançarei os olhos por todos os que dormem, e iluminarei todos os que esperam no Senhor.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 24), 46, 'Continuarei a espalhar a minha doutrina como uma profecia, e deixá-la-ei aos que andam em busca da sabedoria, e não cessarei (de estar presente), de geração em geração, até ao século santo.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 24), 47, 'Vede que eu não trabalhei só para mim, mas para todos os que buscam a verdade.');
INSERT INTO bible_chapters (book_id, chapter_number, total_verses)
INSERT INTO bible_verses (chapter_id, verse_number, text) VALUES
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 25), 1, 'Em três coisas se compraz o meu espírito, as quais têm a aprovação de Deus e dos homens:'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 25), 2, 'A concórdia entre os irmãos, o amor dos próximos, a boa harmonia entre marido e mulher.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 25), 3, 'Há três sortes (de pessoas) que a minha alma aborrece, e cuja vida me é insuportável:'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 25), 4, 'Um pobre soberbo, um rico mentiroso, um velho fátuo e insensato.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 25), 5, 'O que não ajuntaste na tua mocidade, como o acharás na tua velhice?'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 25), 6, 'Quão belo é para os cabelos brancos o saber julgar, para os anciães o saber dar um conselho!'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 25), 7, 'Quão bem parece a sabedoria nos velhos, e a inteligência e o conselho nas pessoas de alta jerarquia!'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 25), 8, 'A experiência consumada é a coroa dos velhos, e o temor de Deus é a sua glória.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 25), 9, 'Nove coisas se apresentam ao meu espírito como muito felizes, e exporei uma décima aos homens por minhas palavras;'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 25), 10, 'Um homem que encontra a sua alegria em seus filhos; o que vive o bastante para ver a ruína de seus inimigos:'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 25), 11, 'aquele— feliz! — que vive com uma mulher de bom senso; o que não caiu pela sua língua; o que não serviu pessoas indignas dele;'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 25), 12, 'aquele— feliz!—que encontrou um amigo verdadeiro; o que fala da justiça a um ouvido que lhe dá atenção;'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 25), 13, 'aquele que — como é grande! — encontrou a sabedoria e a ciência; aquele que — a este nenhum se avantaja,— teme o Senhor.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 25), 14, 'O temor de Deus eleva-se sobre tudo.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 25), 15, 'Bem-aventurado o homem que recebeu o dom do temor de Deus; com quem se comparará aquele que o possui ?'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 25), 16, 'O temor de Deus é o princípio do seu amor, mas inseparavelmente se lhe deve ajuntar um princípio de fé.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 25), 17, 'A tristeza do coração é a maior chaga, e a maldade da mulher é uma consumada malícia.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 25), 18, 'Toda a chaga, não porém a chaga do coração;'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 25), 19, 'toda a malícia, não porém a malícia da mulher;'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 25), 20, 'toda a aflição, não porém a proveniente dos que nos têm ódio;'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 25), 21, 'toda a vingança, não porém a vingança que vem dos inimigos.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 25), 22, 'Não há veneno pior que o da serpente,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 25), 23, 'e não há ira pior que a da mulher. Será melhor viver com um leão e com um dragão, do que habitar com uma mulher má.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 25), 24, 'A maldade da mulher faz-lhe mudar de rosto, dá-lhe um aspecto sombrio como o dum urso, torna-o (escuro e áspero) como um saco. No meio dos seus vizinhos'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 25), 25, 'lamenta-se o seu marido, e, ouvindo-os, suspira amargamente.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 25), 26, 'Toda a malícia é leve comparada com a malícia da mulher; que a sorte dos pecadores caia sobre ela.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 25), 27, 'O que é para os pés dum velho o subir um monte de areia, isso é para um homem sossegado uma mulher desbocada.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 25), 28, 'Não olhes para a formosura da mulher, e não cobices uma mulher pela sua formosura.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 25), 29, 'Da mulher (má) provêm a cólera, a audácia e uma grande confusão.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 25), 30, 'Se a mulher tem o mando, levanta-se contra seu marido.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 25), 31, 'Coração abatido, rosto triste e chaga do coração, eis (o que produz) uma mulher má.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 25), 32, 'Mãos fracas e joelhos vacilantes, eis (o que causa) a mulher que não faz ditoso seu marido.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 25), 33, 'Da mulher nasceu o princípio do pecado, e é por causa dela que todos morremos. (ver nota)'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 25), 34, 'Não dês à tua água a mais ligeira abertura, nem à mulher má, liberdade de sair a público.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 25), 35, 'Se não andar sempre debaixo da tua mão, ela te cobrirá de confusão diante dos teus inimigos.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 25), 36, 'Separa-a do teu corpo, a fim de que não abuse sempre de ti. (ver nota)');
INSERT INTO bible_chapters (book_id, chapter_number, total_verses)
INSERT INTO bible_verses (chapter_id, verse_number, text) VALUES
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 26), 1, 'Ditoso o homem que tem uma virtuosa mulher, porque será dobrado o número dos seus anos. A mulher forte é a alegria de seu marido, derramará paz sobre os anos da sua vida.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 26), 3, 'A mulher virtuosa é uma sorte excelente, é o prêmio dos que temem a Deus, será dada ao homem pelas suas boas obras.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 26), 4, 'Terá (o marido dela) satisfeito o coração, seja rico ou pobre, e o seu rosto ver-se-á sempre alegre.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 26), 5, 'Três coisas receou o meu coração, e com a quarta se amedrontou o meu semblante:'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 26), 6, 'A acusação duma cidade (inteira), a sedição dum povo,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 26), 7, 'a calúnia, coisas estas mais pesadas que a morte;'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 26), 8, 'mas a mulher ciumenta é dor do coração e luto.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 26), 9, 'Na mulher ciosa a língua é um flagelo, que a todos atinge.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 26), 10, 'Como o jugo dos bois desajustado, assim é a mulher má; o que a toma, é como quem toma um escorpião. (ver nota)'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 26), 11, 'A mulher dada ao vinho é motivo de grande cólera e vergonha, e a sua infâmia não será oculta.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 26), 12, 'A impudicícia da mulher reconhece-se na desfaçatez do olhar e no mover das suas pálpebras.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 26), 13, 'Redobra de vigilância sobre a filha que não se retrai (dos homens) para que não se perca, se encontrar ocasião.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 26), 14, 'Vigia sobre todo o desavergonhamento dos seus olhos. e não estranhes se ela te desprezar.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 26), 15, 'Ela, como um viajante sequioso, abrirá a boca à fonte e beberá de toda a água que tiver a mão, junto de qualquer poste se assentará, e a toda a seta abrirá a aljava até mais não poder.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 26), 16, 'A graça duma mulher cuidadosa deleita o seu marido,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 26), 17, 'e o seu bom proceder infunde-lhe vigor até aos ossos. É um dom de Deus'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 26), 18, 'uma mulher sensata, amiga do silêncio; nada é comparável a uma mulher bem educada.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 26), 19, 'Graça sobre graça é a mulher santa e cheia de pudor.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 26), 20, 'Todo o preço é nada em comparação duma alma casta.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 26), 21, 'Como o Sol que se levanta para o mundo, nas alturas de Deus, assim é a beleza duma mulher virtuosa, ornamento da sua casa.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 26), 22, 'Como a lâmpada que brilha sobre o candelabro sagrado, assim é a graciosidade do rosto numa idade madura.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 26), 23, 'Como colunas de ouro sobre bases de prata, assim são, sobre as suas plantas, os pés esbeltos da mulher ponderada.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 26), 24, 'Como fundamentos eternos sobre a pedra sólida, assim são os mandamentos de Deus no coração da mulher santa.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 26), 25, 'Com duas coisas se entristeceu o meu coração, e a terceira provocou-me a cólera:'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 26), 26, 'Um homem de guerra que perece à míngua, tecem, um homem sábio que é desprezado, (ver nota)'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 26), 27, 'e aquele que passa da justiça ao pecado; a este último reservou Deus para a espada. (ver nota)'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 26), 28, 'Duas coisas me parecem difíceis e perigosas: Dificultosamente evitará as faltas o que negoceia, e o taberneiro não estará isento dos pecados da língua.');
INSERT INTO bible_chapters (book_id, chapter_number, total_verses)
INSERT INTO bible_verses (chapter_id, verse_number, text) VALUES
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 27), 1, 'Por causa da pobreza muitos delinquiram; aquele que procura enriquecer-se afasta os olhos. Como se finca um pau no meio da juntura de duas pedras, assim também se introduzirá o pecado entre a venda e a compra. (ver nota)'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 27), 3, 'O delito será destruído com o delinquente.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 27), 4, 'Se te não mantiveres firmemente no temor do Senhor, depressa a tua casa será arruinada.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 27), 5, 'Como quando se abana o crivo apenas ficam as alimpas, assim a perplexidade do homem fica no seu pensamento.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 27), 6, 'O forno prova os vasos do oleiro, e a prova dá tribulação, os homens justos. Como o cuidado que se tem da árvore se dá a conhecer no fruto, assim a palavra manifesta o que vai no coração do homem.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 27), 8, 'Não louves um homem antes de ele falar, porque esta é a prova dos homens.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 27), 9, 'Se fores atrás da justiça, alcançá-la-ás, dela te revestirás como duma vestidura talar de glória; com ela habitarás, ela te protegerá para sempre, e no dia do juízo acharás nela apoio.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 27), 10, 'As aves chegam-se para os seus semelhantes; assim a verdade volta para aqueles que a praticam.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 27), 11, 'O leão está sempre à espreita da presa; assim os pecados armam laços aos que praticam a iniquidade.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 27), 12, 'O homem santo persevera na sabedoria como o Sol; o insensato, porém, muda como a lua.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 27), 13, 'No meio dos insensatos guarda a palavra para outro tempo; (evita-os e) permanece, antes, de continuo entre os que pensam (bem).'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 27), 14, 'A conversação dos pecadores é odiosa, e o seu riso é nas delicias do pecado.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 27), 15, 'O discurso do que muito jura fará arripiar os cabelos da cabeça, e a sua irreverência fará tapar os ouvidos.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 27), 16, 'Na bulha dos soberbos há efusão de sangue; é penoso ouvir as suas maldições.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 27), 17, 'Aquele que descobre os segredos do amigo, perde o crédito e não encontrará mais um amigo a seu gosto.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 27), 18, 'Ama o teu próximo e sê leal na amizade com ele.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 27), 19, 'Se descobrires os seus segredos, não o voltarás a ganhar.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 27), 20, 'Como um homem que mata o seu amigo, assim é o que destrói a amizade do seu próximo.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 27), 21, 'Como aquele que deixa ir da sua mão o pássaro. assim tu deixaste ir o teu próximo, e não o conciliarás mais.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 27), 22, 'Não o sigas, porque já está muito distante; fugiu do laço como uma gazela. Porque foi ferida a sua alma,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 27), 23, 'não poderás mais atraí-lo a ti. Depois duma injúria há reconciliação;'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 27), 24, 'mas o revelar os segredos do amigo tira toda a esperança a uma alma infeliz.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 27), 25, 'O que pisca os olhos forja maus desígnios, e ninguém o pode afastar de si.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 27), 26, 'Na tua presença falará com doçura, admirará o que tu disseres, mas depois mudará de linguagem e armará laços às tuas palavras.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 27), 27, 'Muitas coisas aborreço, mas nenhuma como um tal homem; o Senhor o aborrece também.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 27), 28, 'Quando alguém lança uma pedra ao alto, ela cairá sobre a sua cabeça; assim a ferida traiçoeira abrirá feridas no traidor.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 27), 29, 'O que abre a cova, cairá nela; o que põe uma pedra no caminho para tropeço do próximo, tropeçará nela; o que arma um laço a outrem, nele perecerá.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 27), 30, 'O desígnio perverso recairá sobre o que o forja, que não saberá donde lhe vem o mal.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 27), 31, 'O escárnio e o ultraje são próprios dos soberbos, e a vingança, como um leão, armar-lhe-á ciladas.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 27), 32, 'Aqueles que se alegram com a queda dos justos, perecerão no laço, e a dor os consumirá antes da sua morte.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 27), 33, 'A ira e o furor são duas coisas execráveis; o pecador as terá em si mesmo.');
INSERT INTO bible_chapters (book_id, chapter_number, total_verses)
INSERT INTO bible_verses (chapter_id, verse_number, text) VALUES
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 28), 1, 'Aquele que quer vingar-se, encontrará a vingança do Senhor, o qual tirará exacta conta dos seus pecados.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 28), 2, 'Perdoa ao teu próximo que te ofendeu, e então, quando pedires, serão perdoados os teus pecados.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 28), 3, 'Um homem conserva a sua ira contra outro homem, e pede a Deus remédio?'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 28), 4, 'Não tem compaixão dum homem seu semelhante, e pede perdão dos seus pecados? Ele, que é carne, conserva rancor, e pede propiciação a Deus? Quem lha alcançará pelos seus delitos?'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 28), 6, 'Lembra-te do teu fim e deixa de nutrir inimizades, porque a corrupção e a morte ameaçam-te por detrás dos mandamentos do Senhor.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 28), 8, 'Lembra-te do temor de Deus, e não te ires contra o teu próximo.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 28), 9, 'Lembra-te da aliança do Altíssimo, e não tomes em conta a falta do próximo cometida por inadvertência.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 28), 10, 'Abstém-te de litígios, e diminuirás os pecados;'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 28), 11, 'o homem iracundo acende pendências; o homem pecador suscita discórdias entre os amigos, lança a inimizade no meio dos que vivem em paz.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 28), 12, 'O fogo ateia-se na proporção da madeira do bosque, e a cólera do homem (ateia-se) segundo o seu poder, aumenta em proporção da sua riqueza. (ver nota)'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 28), 13, 'A precipitação em discutir acende o fogo, a demanda irreflectida derrama sangue, e a língua que testifica (falsamente) trás a morte.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 28), 14, 'Se assoprares a uma faúlha ela se inflamará, se cuspires sobre ela, se apagará: ambas as coisas saem da boca.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 28), 15, 'O mexeriqueiro e o homem de duas línguas são malditos porque perturbam muitos que viviam em paz.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 28), 16, 'A _(má)_ língua dum terceiro abalou a muitos, dispersou-os de povo em povo.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 28), 17, 'Ela destruiu as cidades muradas dos ricos, e fez cair as casas dos grandes.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 28), 18, 'Desbaratou as forças dos povos, dispersou as nações fortes.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 28), 19, 'A (má) língua de um terceiro lançou fora de casa mulheres virtuosas e privou-as (do fruto) de seus trabalhos.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 28), 20, 'Aquele que a atende não terá descanso, nem terá amigo em que repouse.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 28), 21, 'O golpe dum açoite faz uma pisadura, mas o golpe da língua esmigalha os ossos.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 28), 22, 'Muitos morreram passados ao fio da espada, porém não tantos como os que morreram por culpa da sua língua.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 28), 23, 'Bem-aventurado aquele que está a coberto da língua iníqua, que não passou pela ira dela, que não atraiu para cima de si o seu jugo e que não foi ligado com as suas cadeias,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 28), 24, 'porque o seu jugo é um jugo de ferro, e as suas cadeias são cadeias de bronze.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 28), 25, 'A morte que ela causa é uma morte desgraçadíssima, e a sepultura é-lhe preferível.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 28), 26, 'Ela durará (algum, mas) não muito tempo; assenhorear-se-á dos caminhos dos injustos, mas a sua chama não queimará os justos. Os que deixam a Deus, cairão no poder dela. que os queimará, sem se extinguir; lançar-se-á sobre eles como um leão, e como um leopardo os despedaçará. (ver nota)'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 28), 27, 'Cerca os teus ouvidos com espinhos,não queiras ouvir a língua má, e põe na tua boca uma porta com ferrolhos.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 28), 28, 'Funde o teu ouro e a tua prata, e faze uma balança para (pesares) as tuas palavras, e um freio bem ajustado para a tua boca;'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 28), 29, 'olha, não escorregues no teu falar, para não caíres diante dos teus inimigos, que te armam ciladas, e para que não venha a tua queda a ser incurável e mortal.');
INSERT INTO bible_chapters (book_id, chapter_number, total_verses)
INSERT INTO bible_verses (chapter_id, verse_number, text) VALUES
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 29), 1, 'Aquele que usa de misericórdia, empresta a juro ao seu próximo: aquele que tem a mão generosa, guarda os mandamentos.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 29), 2, 'Cumpre a tua palavra, e trata lealmente com ele. e em todo o tempo acharás o que te é necessário. (ver nota)'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 29), 3, 'Muitos consideram o que se lhes emprestou como um achado, e causam desgosto àqueles que o ajudaram.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 29), 4, 'Beijara as mãos do que lhes empresta até que tenham recebido, e com voz humilde fazem (grandes) promessas;'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 29), 5, 'porém, chegando o prazo de pagar a dívida, pedem espera. dizem palavras de enfado e de murmuração, e desculpam-se com o tempo (dizendo que a rida está difícil).'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 29), 6, 'porém, chegando o prazo de pagar a dívida, pedem espera, dizem palavras de enfado e de murmuração, e desculpam-se com o tempo (dizendo que a rida está difícil).'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 29), 7, 'Ainda que possam pagar, porão dificuldades, depois darão dificilmente metade do capital, e dirão que se deve considerar isso como uma coisa achada.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 29), 8, 'Se não (podem pagar), privam o credor do seu dinheiro, e, sem causa alguma, o ficarão tendo por inimigo;'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 29), 9, 'pagar-lhe-ão com injúrias e maldições, e, à mercê e beneficio recebidos, corresponderão com ultrajes.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 29), 10, 'Muitos deixam de emprestar, não por desumanidade, mas porque temem ser defraudados sem o merecerem.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 29), 11, 'Apesar de tudo isto, sê magnânimo com o miserável e não o faças esperar pela esmola. (ver nota)'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 29), 12, 'Por causa do mandamento acode ao pobre, e não o deixes ir com as mãos vazias na sua indigência.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 29), 13, 'Perde o teu dinheiro por amor do teu irmão e do teu amigo, e não o escondas debaixo duma pedra para ficar perdido.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 29), 14, 'Emprega o teu tesouro segundo os preceitos do Altíssimo, e isto te aproveitará mais do que o ouro.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 29), 15, 'Encerra a esmola no coração do pobre, e ela rogará por ti para te livrar de todo o mal.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 29), 16, 'Mais do que o escudo e do que a lança do esfor-'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 29), 17, 'çado,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 29), 18, 'ela pelejará contra o teu inimigo.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 29), 19, 'O homem de bem dá fiança pelo seu próximo; e o que tiver perdido a vergonha o abandonará à sua sorte.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 29), 20, 'Não te esqueças do benefício que te fez o que ficou por teu fiador, porque ele expôs a sua vida por ti.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 29), 21, 'O pecador e o impuro fogem do seu fiador.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 29), 22, 'O pecador faz de conta que são seus os bens do seu fiador, e com coração ingrato abandona o seu libertador.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 29), 23, 'Um homem fica por fiador do seu próximo, e este, perdendo a vergonha, abandoná-lo-á.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 29), 24, 'Fianças imprudentes perderam a muitos que iam bem nos seus negócios, agitaram-nos como ondas do mar.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 29), 25, 'Fizeram emigrar para diversos lugares homens poderosos, que andaram errantes entre nações estranhas.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 29), 26, 'O pecador que viola o mandamento do Senhor meter-se-á em fianças ruinosas; e aquele que empreende muitos negócios, cairá sob a justiça.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 29), 27, 'Assiste ao teu próximo conforme as tuas posses, mas olha por ti, não caias tu também.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 29), 28, 'O essencial da vida do homem é a água, o pão, o vestuário e uma casa para cobrir a sua nudez.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 29), 29, 'Aquilo que o pobre come, debaixo de qualquer coberto de tábuas é melhor do que um festim magnífico numa casa estranha, quando se não tem domicílio próprio.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 29), 30, 'Contenta-te com o pouco ou muito que tiveres, e não ouvirás, com amargura, que és um estranho,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 29), 31, 'É uma vida desgraçada a daquele que se anda hospedando de casa em casa; em toda a parte em que for hóspede, não procederá com confiança, nem ousará abrir a boca.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 29), 32, 'Ele noutras ocasiões terá hospedado outros, terá dado de comer e de beber a ingratos, e, depois disto, ouvirá palavras amargas:'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 29), 33, 'Anda, hóspede, vai pôr a mesa, e dá de comer aos outros do que tens à mão:'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 29), 34, 'retira-te por causa da honra que devo aos meus amigos: necessito da minha casa para receber o meu irmão.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 29), 35, 'São duras estas (duas) coisas para um homem sensato: As palavras amargas dum hospedeiro e os insultos dum credor.');
INSERT INTO bible_chapters (book_id, chapter_number, total_verses)
INSERT INTO bible_verses (chapter_id, verse_number, text) VALUES
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 30), 1, 'Aquele que ama o seu filho, castiga-o com frequência, para que se alegre com isso mais tarde, e não ande a bater às portas dos outros.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 30), 2, 'Aquele que instruí o seu filho será louvado nele, e nele mesmo se gloriará entre os seus conhecidos.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 30), 3, 'Aquele que instruí o seu filho causa inveja ao seu inimigo, e entre os seus amigos se gloriará dele.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 30), 4, 'Morreu o seu pai, e foi como se não morresse, porque deixou depois de si um seu semelhante.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 30), 5, 'Em sua vida viu (o seu filho) e nele se alegrou; em sua morte não se entristeceu, nem se envergonhou diante dos seus adversários,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 30), 6, 'porque deixou um defensor da sua casa contra os inimigos, e alguém que será agradecido aos amigos.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 30), 7, 'Aquele que amimalha os seus filhos, terá que lhes pensar as feridas, e a qualquer palavra se turbarão as suas entranhas.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 30), 8, 'Um cavalo indomado torna-se intratável, e um filho deixado à sua vontade torna-se insolente.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 30), 9, 'Lisonjeia teu filho, e ele te causará terror; brinca com ele, e ele te entristecerá.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 30), 10, 'Não te ponhas a rir com ele, para que não venhas a sofrer por isso, para que, no fim, não tenhas de ranger os dentes. (ver nota)'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 30), 11, 'Não lhe dês largas na sua mocidade, e não feches os olhos ao que ele se lembrar de fazer.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 30), 12, 'Encurva-lhe a cerviz na mocidade, fustiga-o nos flancos enquanto é menino, para que não suceda endurecer-se e não te obedeça, e venha a ser a dor da tua alma.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 30), 13, 'Instrui o teu filho, e trabalha por formá-lo, para que te não desonre com a sua vida vergonhosa.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 30), 14, 'Um pobre são e cheio de força vale mais do que um rico fraco e atormentado de doenças.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 30), 15, 'A saúde da alma, na santidade da justiça, vale mais do que todo o ouro e prata; um corpo robusto vale mais do que imensos bens.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 30), 16, 'Não há riqueza maior do que a saúde do corpo, nem contentamento igual à alegria do coração. (ver nota)'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 30), 17, 'Melhor é a morte que uma vida amargurada, e o descanso eterno que um achaque perseverante.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 30), 18, 'Os bens escondidos numa boca cerrada são como manjares esquisitos postos num sepulcro.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 30), 19, 'De que servirá ao ídolo a oblação? Ele não a comerá, nem lhe tomará o cheiro.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 30), 20, 'Assim acontece ao que é repelido pelo Senhor e que leva o pago da sua iniquidade,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 30), 21, 'o qual vê (o alimento) com os seus olhos e geme, como um eunuco que abraça uma donzela e suspira. Não abandones a tua alma à tristeza, e não te aflijas a ti mesmo nos teus pensamentos. O júbilo do coração é a vida do homem e um tesouro inexaurível de santidade; a alegria do homem prolonga a sua vida.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 30), 24, 'Tem piedade da tua alma, procurando agradar a Deus, e aguenta-te; recolhe o teu coração na santidade do mesmo Deus e afugenta para longe de ti a tristeza. Com efeito, a tristeza tem matado a muitos, e não há utilidade nela. (ver nota)'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 30), 26, 'A inveja e a ira abreviam os dias, e os afans fazem chegar a velhice antes do tempo. Um coração generoso e bom está num contínuo festim, porque lhe preparam com diligência o seu alimento.');
INSERT INTO bible_chapters (book_id, chapter_number, total_verses)
INSERT INTO bible_verses (chapter_id, verse_number, text) VALUES
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 31), 1, 'As vigílias para enriquecer consomem as carnes, e a preocupação com isso tira o sono.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 31), 2, 'O pensamento inquieto sobre o que poderá suceder perturba o sossego, e a enfermidade grave torna a alma sóbria. (ver nota)'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 31), 3, 'O rico afadiga-se por juntar riquezas, e, quando se entrega ao repouso, goza dos seus bens. (ver nota)'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 31), 4, 'Trabalha o pobre para ter que comer, e no fim acha-se (ainda) necessitado.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 31), 5, 'Aquele que ama o ouro não estará sem pecado, e aquele que vai atrás da corrupção, será cheio dela.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 31), 6, 'Muitos caíram por causa do ouro, cuja beleza foi a sua perdição. O ouro é uma pedra de tropeço para os que lhe sacrificam. Ai daqueles que vão atrás dele! Por sua causa perecerá todo o insensato.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 31), 8, 'Bem-aventurado o rico que foi achado sem mancha, que não correu atraído pelo ouro, que não pôs a sua esperança no dinheiro nem nos tesouros.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 31), 9, 'Quem é este, para nós o louvarmos? Realmente fez coisas maravilhosas em sua vida.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 31), 10, 'Ao que foi provado pelo ouro e encontrado perfeito, está reservada uma glória eterna: pôde transgredir a lei de Deus, e não a transgrediu, pôde fazer o mal, e não o fez.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 31), 11, 'Por isso os seus bens foram assegurados no Senhor, e toda a assembleia dos santos celebrará as suas esmolas.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 31), 12, 'Sentaste-te a uma grande mesa? Não sejas tu o primeiro a abrir a boca.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 31), 13, 'Não digas: Que abundância de iguarias há sobre ela!'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 31), 14, 'Lembra-te que é má coisa um olho invejoso.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 31), 15, 'Que coisa há pior que semelhante olho ? Por isso chora com todo o seu rosto.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 31), 16, 'Quando olhar (aquele que te convidou), não sejas o primeiro a estender a mão, para que não cores, envergonhado pela tua gula.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 31), 17, 'Não comas à sobreposse, durante o banquete.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 31), 18, 'Julga das disposições do teu próximo pelas tuas.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 31), 19, 'Usa como um homem sóbrio do que te puser diante, não suceda que, por comeres muito, te tornes odioso.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 31), 20, 'Sê o primeiro a acabar em sinal da tua boa educação, e não te desmandes, para que não desgostes ninguém.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 31), 21, 'Se estás sentado entre muitas pessoas, não estendas a mão antes delas, nem sejas o primeiro a pedir de beber. Quão pouco vinho é suficiente para um homem regrado ! Assim, quando dormires, não te causará desassossego, nem sentirás dor.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 31), 23, 'Vigília, cólica e ânsias, terá o homem intemperante.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 31), 24, 'O homem sóbrio terá um sono salutar, dormirá até pela manhã, e a sua alma se deleitará com ele. Se fores obrigado a comer muito, levanta-te e vomita : achar-te-ás aliviado, e não atrairás ao teu corpo uma doença.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 31), 26, 'Ouve-me, filho, e não me desprezes: no fim reconhecerás a verdade das minhas palavras. Sê pronto em todas as tuas acções, e não te virá nenhuma enfermidade. (ver nota)'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 31), 28, 'Os lábios de muitos bem-dirão aquele que dá de comer liberalmente, e dar-se-á um testemunho fiel da sua generosidade. (ver nota)'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 31), 29, 'Toda a cidade murmurará contra o que é mesquinho em dar pão, e o testemunho que dá da sua mesquinhez é verdadeiro.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 31), 30, 'Não provoques (a beber) aqueles que são amigos do vinho, porque o vinho tem perdido muitos.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 31), 31, 'O fogo prova a dureza do ferro: assim o vinho bebido até embriagar dará a conhecer o coração dos soberbos.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 31), 32, 'O vinho bebido com sobriedade é como vida para os homens; se o beberes moderadamente, serás sóbrio.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 31), 33, 'Que vida é a daquele a quem falta o vinho?'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 31), 34, 'Que coisa é a que nos priva da vida? A morte.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 31), 35, 'O vinho desde o princípio foi criado para regozijo, e não para embriaguez.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 31), 36, 'O vinho bebido moderadamente é o júbilo da alma e do coração.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 31), 37, 'A temperança no beber é a saúde da alma e do corpo.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 31), 38, 'O vinho bebido com excesso produz a irritação, a ira e muitas ruínas.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 31), 39, 'O vinho bebido com excesso é a amargura da alma.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 31), 40, 'A embriaguez inspira audácia, faz cair o insensato, diminui as forças e ocasiona feridas.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 31), 41, 'Em um festim de vinho (abundante) não arguas o próximo, e não o desprezes no calor da sua alegria.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 31), 42, 'Não lhe digas palavras de censura e não o apertes com qualquer reclamação.');
INSERT INTO bible_chapters (book_id, chapter_number, total_verses)
INSERT INTO bible_verses (chapter_id, verse_number, text) VALUES
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 32), 1, 'Puseram-te a presidir? Não te ensoberbeças por isso; sê entre os outros como um deles.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 32), 2, 'Tem cuidado deles, e depois disso assenta-te; cumpridas todas as tuas obrigações, põe-te a comer,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 32), 3, 'a fim de que te causem alegria, e recebas a coroa, como um ornamento gracioso, e mostres que eras digno de ser escolhido.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 32), 4, 'Fala, tu que és o mais velho, pois é a ti que pertence falar primeiro.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 32), 5, '(mas fala) com conhecimento e acerto, e não impeças a música.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 32), 6, 'Não desperdices palavras, onde não há quem as ouça, e não te glories despropositadamente do teu saber. Correm igual paralelo uma pedrinha de carbúnculo, em engaste de ouro, e um concerto de músicos em festim de vinho.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 32), 8, 'Como um camafeu de esmeralda encastoado em ouro, assim é uma melodia musical entre um alegre e moderado vinho.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 32), 9, 'Ouve em silêncio, e a tua modéstia conciliar-te-á a simpatia (de todos).'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 32), 10, 'Tu, jovem, fala com dificuldade no que te diz respeito.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 32), 11, 'Se fores interrogado duas vezes, tenha concisão a tua resposta.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 32), 12, 'Porta-te em muitas coisas como se as ignorasses, e ouve, já calando, já também perguntando.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 32), 13, 'No meio dos grandes não tomes demasiada liberdade, e onde estão os velhos não fales muito.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 32), 14, 'Antes do trovão aparece o relâmpago e diante da modéstia vai a graça; pela tua circunspecção serás bem-quisto.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 32), 15, 'Chegada a hora de te levantares, não te detenhas; sê o primeiro a retirar-te para tua casa, e lá diverte-te e recreia o teu espírito.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 32), 16, 'Faze o que te aprouver, contanto que seja sem pecar e sem palavras soberbas.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 32), 17, 'Por todas estas coisas bem-dize ao Senhor, que te criou e que te cumula de todos os seus bens.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 32), 18, 'Aquele que teme o Senhor abraçará a sua doutrina, e os que velarem para o buscar receberão a sua bênção.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 32), 19, 'Aquele que busca a lei será cheio dela, e o que procede com hipocrisia tropeçará nela.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 32), 20, 'Aqueles que temem o Senhor encontrarão um juízo justo, e farão brilhar as suas justiças como uma luz.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 32), 21, 'O homem pecador evitará a repreensão, e encontrará interpretações (da lei) segundo o seu desejo.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 32), 22, 'O homem prudente não desprezará o instruir-se, o estranho, ou o soberbo, não tem nenhum temor;'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 32), 23, 'mas quando opera por si e sem conselho, as suas próprias empresas o condenarão.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 32), 24, 'Filho, não faças coisa alguma sem conselho, e não te arrependerás depois dela feita.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 32), 25, 'Não vás pelo caminho da ruína, e não tropeçarás nas pedras; nem te metas num caminho escabroso, para que não dês à tua alma ocasião de queda.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 32), 26, 'Guarda-te dos teus próprios filhos e acautela-te dos teus domésticos.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 32), 27, 'Em todas as tuas obras guarda a tua alma, porque é assim que se guardam os mandamentos.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 32), 28, 'Aquele que crê em Deus, atende aos seus mandamentos, e o que confia nele não será danificado.');
INSERT INTO bible_chapters (book_id, chapter_number, total_verses)
INSERT INTO bible_verses (chapter_id, verse_number, text) VALUES
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 33), 1, 'Aquele que teme o Senhor não sobrevirão desgraças, antes Deus o guardará na tentação e o livrará dos males.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 33), 2, 'O sábio não aborrece os mandamentos nem as leis, e não se fará em pedaços como o navio na tempestade.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 33), 3, 'O homem sensato crê na lei de Deus, e a lei é fiel para com ele.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 33), 4, 'Prepara o teu discurso, e, deste modo, serás ouvido; junta o teu saber e depois responde. O coração do insensato é como as rodas de um carro, e o seu pensamento é como um eixo que gira.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 33), 6, 'O amigo zombador é como um garanhão, que relincha debaixo de qualquer que o monta.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 33), 7, 'Por que é que um dia é preferido a outro dia, uma luz a outra luz, e um ano a outro ano, provindo todos do mesmo Sol?'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 33), 8, 'Foi a ciência do Senhor que os diferenciou, quando criou o Sol, o qual obedece às suas ordens.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 33), 9, 'Distinguiu as estações e os seus dias de festa, em que (os homens) celebram as solenidades a hora determinada.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 33), 10, 'Destes mesmos dias fez Deus a uns grandes e sagrados, e a outros pôs no número dos dias comuns. Assim, igualmente, todos os homens são feitos do pó, da terra de que Adão foi formado.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 33), 11, 'O Senhor, porém, pela grandeza da sua sabedoria, distinguiu-os, diversificou os seus caminhos.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 33), 12, 'A uns abençoou e exaltou; a outros santificou e tomou para si; a outros amaldiçoou e humilhou, e deitou abaixo do seu lugar. (ver nota)'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 33), 13, 'Como o barro está nas mãos do oleiro, para lhe dar a forma e disposição que deseja,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 33), 14, 'e para o empregar nos usos que lhe aprouver, assim o homem se encontra na mão daquele que o criou, e que lhe dará segundo o seu juízo. (ver nota)'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 33), 15, 'Contra o mal está o bem, e contra a morte a vida; assim também contra o homem justo está o pecador. Considera assim todas as obras do Altíssimo; achá-las-ás duas a duas, e uma oposta à outra.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 33), 16, 'E eu fui o ultimo que despertei, e fui como o que ajunta os bagos atrás dos vindimadores.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 33), 17, 'Eu também esperei na bênção de Deus, e enchi o lagar como o que vindima.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 33), 18, 'Olhai que eu não trabalhei só para mim, mas para todos os que buscam a instrução.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 33), 19, 'Ouvi-me, ó grandes e todos os povos, e vós, os que presidis às assembleias, aplicai os ouvidos.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 33), 20, 'Ao teu filho, à tua mulher, ao teu irmão, ao teu amigo não dês em tua vida poder sobre ti; não dês a outro os bens que possuis, para que não suceda arrependeres-te disso e tomares a pedir-lhos.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 33), 21, 'Enquanto viveres e respirares, ninguém te faça mudar sobre este ponto.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 33), 22, 'porque melhor é que teus filhos te peçam, do que estares tu olhando para as mãos de teus filhos.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 33), 23, 'Em todas as tuas obras conserva a tua superioridade.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 33), 24, 'Não manches o teu bom nome. No dia em que terminar o curso da tua vida, no tempo da tua morte, reparte a tua herança.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 33), 25, 'Ao asno, penso, vara e carga; ao escravo, pão, correcção e trabalho.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 33), 26, 'Ele trabalha quando o castigam, doutra sorte não cuida senão em descansar; afrouxa-lhe as mãos, e buscará a liberdade.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 33), 27, 'O jugo e as correias fazem curvar o pescoço duro, assim as tarefas contínuas amansam o escravo.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 33), 28, 'Ao escravo malévolo, tortura e ferros: manda-o para o trabalho a fim de que não esteja ocioso,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 33), 29, 'porque a ociosidade ensina muita malícia.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 33), 30, 'Põe-no ao trabalho, porque assim lhe convém. Mas, se ele te não obedecer, aperreia-o com grilhões; porém não cometas excessos seja com quem for, e não faças coisa alguma grave sem ter reflectido.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 33), 31, 'Se tens um escravo fiel, estima-o como a ti próprio, trata-o como um irmão, porque o adquiriste à custa do teu sangue. (ver nota)'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 33), 32, 'Se o tratares mal sem razão, fugir-te-á:'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 33), 33, 'e se ele se afasta de ti e se retira, não saberás a quem perguntar, nem por que caminho o hás-de buscar.');
INSERT INTO bible_chapters (book_id, chapter_number, total_verses)
INSERT INTO bible_verses (chapter_id, verse_number, text) VALUES
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 34), 1, 'É próprio do homem insensato sustentar-se de vãs esperanças e de mentira, e os sonhos dão asas à fantasia dos imprudentes.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 34), 2, 'Como o que procura agarrar uma sombra e vai atrás do vento, assim é o que atende a enganosas visões.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 34), 3, 'A visão dos sonhos é isto segundo aquilo, é como a imagem dum homem diante dele próprio.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 34), 4, 'Que coisa pura poderá vir dum impuro? E por um mentiroso que verdade será dita?'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 34), 5, 'A adivinhação do erro, os agouros falsos e os sonhos dos malfeitores são vaidade.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 34), 6, 'O teu coração, como o da mulher que está de parto, padecerá imaginações. Se pelo Altíssimo te não foi enviada alguma destas visões, não ponhas nelas o teu coração,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 34), 7, 'porque os sonhos têm feito extraviar muitos, que caíram, por terem posto neles a sua confiança.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 34), 8, 'A palavra da lei será cumprida sem mentira, e a sabedoria será clara na boca do homem fiel. (ver nota)'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 34), 9, 'Que sabe aquele que não foi provado? O homem experimentado em muitas coisas, tem muitos pensamentos; o que aprendeu muito, fala com sabedoria.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 34), 10, 'Aquele que não tem experiência, pouco sabe, mas o que se ocupou em muitos negócios adquire muita sagacidade.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 34), 11, 'Que sabe aquele que não foi tentado? O que foi enganado tornar-se-á muito esperto.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 34), 12, 'Muitas coisas tenho visto viajando, muitos costumes diferentes.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 34), 13, 'Algumas vezes me encontrei em perigo de morrer, por causa destas coisas, mas fui livre pela graça de Deus. (ver nota)'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 34), 14, 'O espírito daqueles que temem a Deus, será procurado; quando Deus olhar para eles (o seu espirito) será abençoado.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 34), 15, 'Com efeito, a sua esperança está posta naquele que os salva, e os olhos de Deus estão sobre os que o amam.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 34), 16, 'Aquele que teme o Senhor de nada tremerá, e não terá pavor algum, porque ele mesmo é a sua esperança.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 34), 17, 'Bem-aventurada a alma daquele que teme o Senhor.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 34), 18, 'Para quem olha ela, e quem é a sua fortaleza?'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 34), 19, 'Os olhos do Senhor estão sobre os que o temem; ele é um protector poderoso, um esteio forte, um abrigo contra o calor, uma protecção contra o ardor do meio-dia,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 34), 20, 'um sustentáculo contra o tropeção, um auxílio contra a queda; ele levanta a alma e alumia os olhos, dá saúde, vida e bênção.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 34), 21, 'A oblação daquele que sacrifica dos bens havidos com injustiça, é imunda, e não são agradáveis a Deus os escárnios dos injustos.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 34), 22, 'O Senhor é só para aqueles que o esperam no caminho da verdade e da justiça.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 34), 23, 'O Altíssimo não aprova os dons dos iníquos, não olha para as oblações dos maus, nem pela multidão dos seus sacrifícios lhes perdoará os seus pecados.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 34), 24, 'Aquele que oferece um sacrifício com os haveres dos pobres, é como o que degola um filho na presença de seu pai.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 34), 25, 'O pão dos necessitados é a vida dos pobres; aquele que lho tira é um homem sanguinário.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 34), 26, 'Quem tira a alguém o pão que ganhou com o seu suor, é como aquele que mata o seu próximo. Aquele que derrama sangue e o que defrauda o trabalhador, são irmãos.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 34), 28, 'Se um edifica, e outro destrói, que proveito lhes resulta daqui senão trabalho?'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 34), 29, 'Se um ora, e outro amaldiçoa, de qual ouvirá Deus a voz?'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 34), 30, 'Se alguém se lava, depois de ter tocado um morto, e o toca outra vez, de que lhe serve o ter-se lavado?'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 34), 31, 'Assim se porta o homem, que jejua pelos seu pecados e que, de novo, os comete: que proveito tira da sua mortificação? Quem ouvirá a sua oração?');
INSERT INTO bible_chapters (book_id, chapter_number, total_verses)
INSERT INTO bible_verses (chapter_id, verse_number, text) VALUES
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 35), 1, 'Aquele que observa a lei (por isso mesmo, como que) multiplica as oferendas. (ver nota)'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 35), 2, 'É um sacrifício salutar estar atento aos mandamentos, e apartar-se de toda a iniquidade.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 35), 3, 'É oferecer um sacrifício de propiciação pelas injustiças e orar pelos pecados, o afastarmo-nos da injustiça.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 35), 4, 'Aquele que oferece a flor da farinha dá graças a Deus; e o que exerce a misericórdia oferece um sacrifício.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 35), 5, 'É agradável ao Senhor o fugir da iniquidade; é uma deprecação pelos pecados o retirar-se da injustiça.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 35), 6, 'Não apareças com as mãos vazias diante do Senhor,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 35), 7, 'porque todas estas coisas se fazem por causa do mandamento de Deus.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 35), 8, 'A oblação do justo torna pingue o altar, e é um suave perfume diante do Altíssimo.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 35), 9, 'O sacrifício do justo é agradável (a Deus), o Senhor não se esquecerá dele.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 35), 10, 'De bom ânimo tributa glória a Deus, e não diminuas as primícias de tuas mãos.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 35), 11, 'Tudo o que dás, dá-o com semblante alegre, santifica os teus dízimos com regozijo.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 35), 12, 'Dá ao Altíssimo segundo o que ele te tem dado, oferece-lhe com ânimo generoso, segundo as tuas posses,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 35), 13, 'porque o Senhor é remunerador, recompensar-te-á tudo sete vezes mais.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 35), 14, 'Não lhe ofereças donativos perversos, porque os não receberá.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 35), 15, 'Não esperes nada dum sacrifício injusto, porque o Senhor é juiz, e não há para ele distinção de pessoas.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 35), 16, 'O Senhor não fará acepção de pessoas contra o pobre, e ouvirá a oração do oprimido.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 35), 17, 'Não desprezará os rogos do órfão, nem a viúva que lhe fala com os seus gemidos.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 35), 18, 'Não correm as lágrimas à viúva pelas suas faces, e não clama ela contra aquele que lhas faz derramar?'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 35), 19, 'Efectivamente, elas das faces (da viúva) sobem até ao céu, e o Senhor, que a ouve, não gostará de a ver chorar.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 35), 20, 'Aquele que adora a Deus com alegria será bem acolhido, e a sua prece chegará até às nuvens.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 35), 21, 'A oração do que se humilha penetrará as nuvens; ele não se consolará, enquanto ela não chegar (até Deus), e não se retirará, enquanto o Altíssimo não puser nela os olhos.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 35), 22, 'O Senhor não diferirá por muito tempo, mas julgará os justos e lhes fará justiça: o Fortíssimo não usará mais de paciência (com os opressores), mas quebrar-lhes-á o dorso.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 35), 23, 'Vingar-se-á das nações, até desfazer a multidão dos soberbos e quebrar os ceptros dos iníquos;'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 35), 24, 'até retribuir aos homens segundo as suas acções, segundo as obras e presunção de (qualquer descendente de) Adão;'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 35), 25, 'até fazer justiça ao seu povo e alegrar os justos com a sua misericórdia.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 35), 26, 'A misericórdia de Deus, no tempo da tribulação, é agradável, como a nuvem que se desfaz em chuva no tempo da seca.');
INSERT INTO bible_chapters (book_id, chapter_number, total_verses)
INSERT INTO bible_verses (chapter_id, verse_number, text) VALUES
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 36), 1, 'Tem piedade de nós, ó Deus de todas as coisas, volta para nós os teus olhos e mostra-nos a luz das tuas misericórdias;'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 36), 2, 'espalha o teu temor sobre as nações, que te não buscaram, para que elas reconheçam que não há outro Deus senão tu, e publiquem as tuas maravilhas,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 36), 3, 'Levanta a tua mão contra as nações estranhas, para que reconheçam o teu poder.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 36), 4, 'Assim como diante dos seus olhos mostraste em nós a tua santidade, assim também, à nossa vista, mostra nelas a tua grandeza, (ver nota)'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 36), 5, 'para que reconheçam, como também nós reconhecemos, que fora de ti, Senhor, não há outro Deus.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 36), 6, 'Renova os teus prodígios, faze novas maravilhas,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 36), 7, 'glorifica a tua mão e o teu braço direito.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 36), 8, 'Excita o teu furor e derrama a tua ira.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 36), 9, 'Destrói o adversário e aflige o inimigo.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 36), 10, 'Apressa o tempo, lembra-te do fim, para que publiquem as tuas maravilhas.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 36), 11, 'Na voracidade das chamas consumido seja o que escapar, e os que tiranizam o teu povo caiam na perdição.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 36), 12, 'Esmaga a cabeça aos chefes dos inimigos, que dizem: Não há outro (Senhor) fora de nós.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 36), 13, 'Ajunta todas as tribos de Jacob, para que conheçam que não há outro Deus senão tu, para que publiquem as tuas grandezas, e sejam herança tua como o foram desde o principio.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 36), 14, 'Tem misericórdia do teu povo, que foi chamado do teu nome, e de Israel, a quem tu tens tratado como teu primogênito.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 36), 15, 'Tem piedade da cidade que santificaste, de Jerusalém, cidade do teu repouso.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 36), 16, 'Enche Sião das tuas palavras inefáveis, e o teu povo da tua glória.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 36), 17, 'Dá testemunho em favor daqueles que, desde o princípio, são tuas criaturas, e suscita (o cumprimento dos) oráculos que em teu nome proferiram os primeiros profetas.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 36), 18, 'Dá a recompensa aos que pacientemente esperam em ti, para que os teus profetas sejam achados fiéis; ouve as orações dos teus servos,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 36), 19, 'segundo a bênção de Aarão ao teu povo, e encaminha-nos pela estrada da justiça, a fim de que todos os que habitam a terra saibam que tu és o Deus que contempla os séculos.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 36), 20, 'O estômago recebe toda a casta de alimentos, mas entre os alimentos um é melhor que outro.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 36), 21, 'O paladar discerne pelo gosto o prato de caça, e o coração sensato as palavras mentirosas.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 36), 22, 'O coração depravado causa tristeza, mas o homem hábil resistir-lhe-á.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 36), 23, 'A mulher pode tomar por esposo a qualquer homem, mas entre as filhas uma é melhor que outra.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 36), 24, 'A formosura da mulher alegra o rosto do seu marido, e ultrapassa todos os desejos do homem.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 36), 25, 'Se a sua língua sabe curar, possui também a doçura e a bondade: o seu marido não será (infeliz ou pouco feliz) como os (outros) filhos dos homens.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 36), 26, 'O que possui uma mulher boa começa a formar a sua fortuna; tem um auxílio, que lhe é semelhante, e uma coluna de apoio.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 36), 27, 'Onde não há sebe, será roubada a fazenda; onde não há mulher, o homem suspira na indigência. (ver nota)'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 36), 28, 'Quem é que se fia daquele que não tem ninho, que passa a noite onde quer que ela o surpreende, como salteador pronto para tudo, que vagueia de cidade em cidade?');
INSERT INTO bible_chapters (book_id, chapter_number, total_verses)
INSERT INTO bible_verses (chapter_id, verse_number, text) VALUES
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 37), 1, 'Todo o amigo dirá: Eu também contraí amizade contigo. Porém há amigos que o são somente de nome. Não causa isto uma dor que se avizinha da morte.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 37), 2, 'que o companheiro e o amigo se convertam em inimigos?'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 37), 3, 'Ó perversíssimo pensamento, onde tiveste a tua origem, para cobrir a terra com a tua malícia e com a tua perfídia?'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 37), 4, 'Um amigo alegra-se com o seu amigo na prosperidade; no tempo da tribulação será seu adversário.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 37), 5, 'Um amigo condói-se do seu amigo, no interesse do seu ventre; à vista do inimigo, tomará o escudo.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 37), 6, 'Não te esqueças em teu coração do teu amigo, não percas a lembrança dele no meio da tua riqueza.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 37), 7, 'Não te aconselhes com aquele que te arma traições, e esconde os teus desígnios dos que te têm inveja.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 37), 8, 'Todo o que é consultado dá o seu conselho, mas há conselheiros que só atendem a si próprios.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 37), 9, 'Vê bem com quem te aconselhas; informa-te primeiro quais são os seus interesses, porque ele pensa neles dentro de si próprio.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 37), 10, 'Isto, para que não suceda talvez que finque na terra uma estaca,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 37), 11, 'e te diga: O teu caminho é bom — enquanto se põe do outro lado, para ver o que te acontecerá.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 37), 12, 'Consulta sobre santidade um homem sem religião, um injusto sobre justiça, uma mulher sobre outra de quem ela tem ciúme, um covarde a respeito de guerra, um negociante acerca do tráfico de mercadorias, um comprador sobre a venda, um invejoso sobre o reconhecimento.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 37), 13, 'um ímpio sobre a piedade, um desonesto sobre a honestidade, um operário do campo sobre qualquer trabalho'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 37), 14, 'um jornaleiro por ano sobre o que ele deve fazer durante um ano, um servo preguiçoso a respeito dum grande trabalho!... Nunca te aconselhes com estes sobre tais coisas.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 37), 15, 'Comunica, sim, continuamente com um homem santo, que tu reconheceres fiel ao temor de Deus,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 37), 16, 'cuja alma é segundo a tua alma, e que se condoerá de ti, quando andares titubeando nas trevas.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 37), 17, 'Forma dentro de ti um coração de bom conselho, porque não tens outra coisa de maior preço do que ele. (ver nota)'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 37), 18, 'A alma dum homem santo descobre algumas vezes melhor a verdade, do que sete sentinelas postadas num lugar elevado para atalaiar.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 37), 19, 'Mas sobre tudo pede ao Altíssimo que dirija o teu caminho em verdade.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 37), 20, 'Preceda todas as tuas obras a palavra verídica, e todos os teus empreendimentos nm conselho estável'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 37), 21, 'Uma palavra má transtorna o coração, de que nascem quatro coisas: o bem e o mal, a vida e a morte; sobre elas quem domina de contínuo é a língua. Há homem hábil que ensina a muitos, mas que é inútil para si. (ver nota)'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 37), 22, 'Outro é prudente e instrui a muitos, e é agradável (ou útil) a si próprio.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 37), 23, 'Aquele que usa duma linguagem pretenciosamente sábia é odioso; será privado de tudo. (ver nota)'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 37), 24, 'Não lhe foi dada a graça pelo Senhor, porque carece de toda a sabedoria.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 37), 25, 'Há sábio, que é sábio para si: o fruto da sua sabedoria é louvável.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 37), 26, 'O homem sábio instrui o seu povo, e os frutos da sua sabedoria são estáveis.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 37), 27, 'O homem sábio será cheio de bênçãos, e louvá-lo-ão os que o virem.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 37), 28, 'A vida do homem reduz-se a um certo número de dias, porém os dias de Israel são inumeráveis.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 37), 29, 'O sábio herdará honra no seio do povo, e o seu nome viverá eternamente.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 37), 30, 'Filho, prova a tua alma durante a tua vida; se coisa lhe é prejudicial, não lha concedas,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 37), 31, 'porque nem todas as coisas convêm a todos, nem todas as pessoas se comprazem nas mesmas coisas.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 37), 32, 'Não sejas glutão em banquete algum, nem te lances a todos os pratos,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 37), 33, 'porque no excesso de alimento está a doença, e a intemperança conduz à cólica.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 37), 34, 'Por causa da intemperança morrem muitos; porém o homem sábio prolonga a sua vida.');
INSERT INTO bible_chapters (book_id, chapter_number, total_verses)
INSERT INTO bible_verses (chapter_id, verse_number, text) VALUES
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 38), 1, 'Honra o médico, por causa da necessidade; com efeito, foi o Altíssimo que o criou.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 38), 2, 'Toda a medicina vem de Deus. e (o médico) receberá donativos do rei.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 38), 3, 'A ciência do médico exaltará a sua cabeça, e ele será louvado na presença dos grandes.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 38), 4, 'O Altíssimo produziu da terra os medicamentos; o homem prudente não os aborrecerá.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 38), 5, 'Porventura não foi por meio dum lenho que se tornou doce a água amargosa?'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 38), 6, 'Ao conhecimento dos homens chegou a virtude dos medicamentos. O Altíssimo deu aos homens a ciência para ser por eles honrado nas suas maravilhas.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 38), 7, 'Com eles cura e mitiga a dor; o farmacêutico faz compostos agradáveis, compõe unguentos salutares, de forma que as criaturas de Deus não pereçam.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 38), 8, '(Pela sua acção) a paz de Deus estende-se sobre a face da terra.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 38), 9, 'Filho, não te descuides na tua enfermidade, mas faze oração ao Senhor, e ele te curará. (ver nota)'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 38), 10, 'Aparta-te do pecado, endireita as tuas mãos, purifica o teu coração de todo o delito.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 38), 11, 'Oferece um (incenso de) cheiro suave, uma lembrança de flor de farinha imola vitimas pingues; (depois disto) dá lugar ao médico,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 38), 12, 'pois para isso é que o Senhor o estabeleceu. E não se aparte de ti, porque te é necessária a sua assistência.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 38), 13, 'Virá tempo em que cairás nas mãos deles,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 38), 14, 'e eles mesmos rogarão ao Senhor que envie por meio deles o alívio e a saúde, em atenção à sua vida recta.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 38), 15, 'Aquele que peca na presença de quem o criou, virá a cair nas mãos do médico.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 38), 16, 'Filho, derrama lágrimas sobre o morto, põe-te a chorar como quem recebeu um rude golpe: enterra o seu corpo segundo o costume, e não desprezes a sua sepultura.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 38), 17, 'Chora-o amargamente durante um dia, para evitar a maledicência, e depois consola-te da tua tristeza;'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 38), 18, 'Toma este nojo segundo o merecimento da pessoa, um dia ou dois, para não dares lugar à detracção.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 38), 19, 'Porque a tristeza faz apressar a morte, tira o vigor, e a melancolia do coração faz descair a cabeça.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 38), 20, 'A tristeza conserva-se na solidão; e a vida do pobre é como o seu coração.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 38), 21, 'Não entregues o teu coração à tristeza, mas lança-a fora de ti; lembra-te do teu fim. Não te esqueças dele, porque não há retorno; em nada aproveitarás ao morto, e a ti mesmo farás um grave dano.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 38), 23, 'Lembra-te da minha sorte (te dirá o morto): a tua será semelhante; ontem para mim, hoje para ti.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 38), 24, 'No repouso do morto deixa descansar a sua memória; e consola-o ao exalar o último suspiro.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 38), 25, 'O letrado adquire sabedoria no tempo do ócio, e o que tem poucas ocupações alcançará a sabedoria. De que sabedoria será cheio'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 38), 26, 'o que pega no arado, que faz timbre de saber picar os bois com o aguilhão, que se ocupa constantemente com os trabalhos deles, e cuja conversação é somente sobre novilhos de touros?'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 38), 27, 'Ele aplicará o seu coração em tirar (bem) os sulcos, e os seus desvelos em engordar as bezerras.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 38), 28, 'Assim sucede com todo o carpinteiro e arquitecto, que passa trabalhando a noite e o dia; com o que grava as figuras dos sinetes, e que todo se cansa em as variar, que aplica o seu coração em reproduzir o debuxo, e, à força de vigílias, completa a obra.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 38), 29, 'Assim sucede com o ferreiro, assentado ao pé da bigorna, atento ao ferro que está trabalhando; o vapor do fogo cresta as suas carnes, e ele aguenta-se contra o calor da frágua.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 38), 30, 'O estrondo do martelo fere-lhe sem cessar os ouvidos, e os seus olhos estão fixos no modelo da sua obra.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 38), 31, 'Aplica o coração a completar os seus trabalhos, com o seu desvelo os aformoseia, dando-lhes a última demão.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 38), 32, 'Assim sucede com o oleiro que, assentado a realizar a sua tarefa, dá voltas à roda com os pés, sempre cuidadoso pela sua obra, levando por conta tudo o que faz.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 38), 33, 'Com seu braço dá forma ao barro, e com os seus pés torna-o flexível.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 38), 34, 'Ele aplica o seu coração a vidrar a obra perfeitamente, e a sua diligência em limpar o forno.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 38), 35, 'Todos estes têm confiança na indústria das suas mãos, e cada um é sabido na sua arte.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 38), 36, 'Sem eles não se edificaria uma cidade.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 38), 37, 'não se habitaria nela, nem se passearia. Porém esses mesmos não entrarão nas assembleias.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 38), 38, 'não se assentarão nas cadeiras dos juízes, não entenderão as leis da justiça, não ensinarão as regras da moral nem do direito, e não se acharão ocupados nas parábolas.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 38), 39, 'Entretanto sustentam as coisas temporais, e os seus votos são para fazerem bem as obras da sua arte.');
INSERT INTO bible_chapters (book_id, chapter_number, total_verses)
INSERT INTO bible_verses (chapter_id, verse_number, text) VALUES
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 39), 1, 'Outrotanto não sucede com o que aplica o seu espirito à lei do Altíssimo e nela medita. Investiga a sabedoria de todos os antigos, e dedica-se ao estudo dos profetas. Conserva no seu coração as narrações dos homens célebres, e penetra também nas subtilezas das parábolas.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 39), 3, 'Indaga o sentido oculto dos provérbios, e ocupa-se dos enigmas das parábolas.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 39), 4, 'serve no meio dos grandes, e aparece diante do que governa. Percorre a terra de nações estranhas, para reconhecer o que há de bom e mau entre os homens.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 39), 6, 'Aplica o seu coração a velar de madrugada, ante o Senhor que o criou, e na presença do Altíssimo faz a sua oração. Abre a sua boca para orar, e pede perdão de seus pecados.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 39), 8, 'Se o soberano Senhor assim o quiser, enchê-lo-á do espirito de inteligência,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 39), 9, 'e, então, ele derramará as palavras da sua sabedoria como chuva, e na oração louvará o Senhor.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 39), 10, 'Regulará os seus conselhos e instruções e meditará nos segredos de Deus.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 39), 11, 'Exporá publicamente a doutrina que aprendeu e fará consistir a sua glória na lei da aliança do Senhor.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 39), 12, 'Muitos louvarão a sua sabedoria, que jamais ficará no esquecimento.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 39), 13, 'Não perecerá a sua memória, e o seu nome será repetido de geração em geração.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 39), 14, 'As nações publicarão a sua sabedoria, e a assembleia publicará o seu louvor.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 39), 15, 'Enquanto viver, terá maior reputação do que mil outros, e, quando repousar, a sua fama aumentará com isso.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 39), 16, 'Quero ainda continuar a expor as minhas reflexões, porque estou cheio de entusiasmo.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 39), 17, 'Uma voz me diz; Ouvi-me vós, que sois rebentos divinos, e, como rosal plantado sobre as correntes das águas, frutificai. (ver nota)'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 39), 18, 'Difundi um cheiro suave como o Líbano.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 39), 19, 'Dai flores como o lírio, exalai perfume, lançai graciosos ramos, entoai cantos de louvor e bem-dizei o Senhor nas suas obras.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 39), 20, 'Proclamai magnificentemente o seu nome, glorificai-o com a voz dos vossos lábios, com os cânticos da vossa boca e ao som das harpas. Direis assim em seu louvor:'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 39), 21, 'Todas as obras do Senhor são muito boas.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 39), 22, 'À sua voz conteve-se a água como um montão, a uma palavra da sua boca, as águas recolheram-se como em reservatórios.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 39), 23, 'À sua ordem, tudo o que lhe apraz se realiza, e a salvação que ele dá, não será apoucada.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 39), 24, 'Estão à sua vista as acções de todos os homens, não há nada escondido a seus olhos.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 39), 25, 'O seu olhar estende-se de século em século, e nada é maravilhoso para ele.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 39), 26, 'Não se pode dizer: Que é isto, ou que é aquilo? Com efeito, todas as coisas foram criadas para seus usos.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 39), 27, 'A sua bênção é como um rio que inunda.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 39), 28, 'Como o dilúvio inundou a terra, assim a ira do Senhor será a sorte das gentes que o não buscaram.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 39), 29, 'Assim como ele converteu as águas em secura, e a terra ficou enxuta, e os seus caminhos são dirigidos aos caminhos deles, assim, na sua ira, (esses mesmos caminhos) são, para os pecadores, motivos de queda.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 39), 30, 'Os bens, desde o princípio, foram criados para os bons, e os males (foram criados) para os maus.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 39), 31, 'As coisas mais necessárias à vida do homem são; a água, o fogo, o ferro, o sal, o leite, o pão da flor da farinha, o mel, as uvas, o azeite e o vestuário.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 39), 32, 'Assim como todas estas coisas são um bem para os bons, assim para os ímpios e pecadores se tornam em mal.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 39), 33, 'Há espíritos que foram criados para a vingança, e no seu furor fazem com que os maus sofram continuamente os seus castigos.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 39), 34, 'No tempo do extermínio eles empregarão a sua força, aplacarão o furor daquele que os criou.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 39), 35, 'O fogo, a saraiva, a fome e a morte, todas estas coisas foram criadas para castigo,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 39), 36, '(como também) os dentes das feras, os escorpiões, as serpentes, e a espada que pune os ímpios até ao extermínio.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 39), 37, '(Todas estas coisas) executarão com alegria as ordens do Senhor, estarão prestes sobre a terra no momento necessário, e, chegando o tempo, executarão pontualmente as suas ordens.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 39), 38, 'Por isso desde o princípio estou convencido disto, que meditei e deixei por escrito.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 39), 39, 'Todas as obras do Senhor são boas, e cada uma delas, chegada a sua hora, fará o seu serviço.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 39), 40, 'Não se pode dizer: Isto é pior do que aquilo — porque todas as coisas serão achadas boas a seu tempo. (ver nota)'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 39), 41, 'E agora, de todo o coração e com a boca, louvai, e bem-dizei o nome do Senhor.');
INSERT INTO bible_chapters (book_id, chapter_number, total_verses)
INSERT INTO bible_verses (chapter_id, verse_number, text) VALUES
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 40), 1, 'Grande preocupação foi imposta a todos os homens, pesado jugo carrega sobre os filhos de Adão, desde o dia em que eles saem do ventre de sua mãe, até ao da sua sepultura (em que eles entram) no seio da mãe comum de todos;'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 40), 2, 'Os seus pensamentos, os temores do coração, a apreensão do que esperam e o dia em que tudo acaba, (perturbam-nos a todos),'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 40), 3, 'desde o que está sentado sobre um trono de glória, até àquele que jaz abatido na terra e na cinza;'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 40), 4, 'desde aquele que está vestido de purpura e traz coroa, até ao que se cobre de pano grosseiro. Furor, inveja, inquietação, perplexidade, temor da morte, rancor obstinado e contendas (tudo isto faz sofrer o homem).'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 40), 5, 'Até no tempo em que repousa na cama, o sono da noite lhe perturba as ideias.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 40), 6, 'Breve ou quase nenhum é o seu repouso, e ainda no seu mesmo sono, como sentinela que está de guarda,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 40), 7, 'é perturbado pelas visões do seu coração, como quem foge no dia da batalha; quando se imagina salvo, desperta, e admira-se do seu vão temor.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 40), 8, 'Isto acontece a todos os viventes, desde os homens até aos animais, mas para os pecadores é sete vezes pior.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 40), 9, 'Além disso, a morte, o sangue, as contendas, a espada, as opressões, a fome a ruína e os (outros) flagelos,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 40), 10, 'tudo isto foi criado para os maus. e por causa deles (é que também) veio o dilúvio.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 40), 11, 'Tudo o que é da terra, tornar-se-á em terra, como todas as águas voltam ao mar.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 40), 12, 'Toda a dádiva (oferecida para corromper) e toda a (riqueza adquirida com) iniquidade perecerão, porém a rectidão subsistirá eternamente.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 40), 13, 'As riquezas dos injustos secar-se-ão como uma torrente, e farão muito estrondo como um grande trovão quando chove.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 40), 14, 'Alegrar-se-á o homem, ao abrir as suas mãos; porém os prevaricadores serão completamente consumidos.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 40), 15, 'Os descendentes dos ímpios não multiplicarão os ramos: são como raízes viciadas que se agitam no alto dum rochedo.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 40), 16, 'A verdura que cresce sobre as águas, à borda dum rio, será arrancada antes de toda a outra erva.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 40), 17, 'A bondade é como um paraíso de bênçãos, e a misericórdia permanece para sempre.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 40), 18, 'A vida do operário que se basta a si próprio será doce; acharás nela um tesouro.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 40), 19, 'Os filhos e a fundação duma cidade dão fama duradoira, mas será preferida a tudo isto uma mulher irrepreensível.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 40), 20, 'O vinho e a música alegram o coração, mas o amor da sabedoria excede ambas estas coisas.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 40), 21, 'A flauta e a harpa produzem uma suave melodia, mas a língua doce sobrepuja ambas estas coisas. A graça e a beleza deleitam a tua vista, mas a verdura dos campos leva vantagem a ambas estas coisas.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 40), 23, 'O amigo e o companheiro auxiliam-se mutuamente na ocasião (própria), mas, mais do que estes dois, a mulher e o marido.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 40), 24, 'Os irmãos são um auxílio no tempo da tribulação; porém a misericórdia livrará mais do que eles.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 40), 25, 'O ouro e a prata são a firmeza dos pés; mas um bom conselho excede ambas estas coisas.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 40), 26, 'As riquezas e a força exaltam o coração; mas o temor do Senhor avantaja-se a estas duas coisas. Nada falta ao que tem o temor do Senhor, e com ele não há necessidade de outro auxílio.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 40), 28, 'O temor do Senhor é como um paraíso bem-dito; acha-se revestido duma glória superior a toda a glória.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 40), 29, 'Filho, não leves vida de mendicante, porque é melhor morrer do que mendigar.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 40), 30, 'A vida do homem, que se atém à mesa alheia, não é realmente vida, porque se alimenta com manjares dos outros.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 40), 31, 'Mas o varão bem educado e instruído se guardará disto.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 40), 32, 'Na boca do insensato será doce a mendicidade, mas em seu ventre arderá como fogo.');
INSERT INTO bible_chapters (book_id, chapter_number, total_verses)
INSERT INTO bible_verses (chapter_id, verse_number, text) VALUES
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 41), 1, 'ó morte, quão amarga é a tua memória para o homem que tem paz no meio das suas riquezas, para o homem tranqüilo e afortunado em tudo, e que aluda se encontra em estado de tomar alimento !'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 41), 3, 'Ó morte, que doce é a tua sentença para o homem necessitado, que se acha falto de forças,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 41), 4, 'para o homem já decrépito e consumido de cuidados, e para o que se vê sem esperança (de melhoras), e a quem falta a paciência!'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 41), 5, 'Não temas o decreto da morte. Lembra-te dos que existiram antes de ti, e dos que virão depois de ti: É um decreto que o Senhor promulgou para todos os mortais.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 41), 6, 'Que coisa te sobrevirá de acordo com o beneplácito do Altíssimo? Viva um homem dez, cem ou mil anos.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 41), 7, 'na morada dos mortos não se toma em conta a (duração da) vida.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 41), 8, 'Os filhos dos pecadores tornam-se (ordinariamente) filhos de abominação, assim como os que frequentam as casas dos ímpios.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 41), 9, 'A herança dos filhos dos pecadores perecerá, e com a sua linhagem andará continuamente o opróbrio.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 41), 10, 'Os filhos dum ímpio queixam-se do seu pai, pois se acham, por causa dele, no opróbrio.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 41), 11, 'Desgraçados de vós homens ímpios, que deixastes a lei do Senhor Altíssimo!'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 41), 12, 'Se nasceis, na maldição nasceis, se morreis, a maldição é a vossa herança.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 41), 13, 'Tudo o que é da terra tornar-se-á em terra; assim os ímpios (cairão) da maldição na perdição.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 41), 14, 'O pranto dos homens é sobre o seu cadáver, mas o nome dos ímpios será apagado do mundo. (ver nota)'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 41), 15, 'Tem cuidado da tua boa reputação, poi-que esta será para ti um bem mais estável do que mil tesouros grandes e preciosos.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 41), 16, 'A vida boa tem somente um certo número de dias, mas o bom nome permanecerá para sempre.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 41), 17, 'Conservai, filhos, em paz a minha instrução, porque, se a sabedoria está escondida e o tesouro é invisível, que utilidade pode haver em ambas estas coisas?'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 41), 18, 'Melhor é o homem que esconde a sua estultícia, do que o homem que esconde a sua sabedoria.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 41), 19, 'Tende, pois, vergonha do que vos vou indicar,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 41), 20, 'porque não é bom ter vergonha de tudo, nem todas as coisas são julgadas por todos segundo a verdade. (ver nota)'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 41), 21, 'Envergonhai-vos da fornicação, diante do vosso pai e da vossa mãe, e da mentira, diante do que governa e do poderoso;'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 41), 22, 'de um delito diante do príncipe e do juiz; da iniquidade diante da assembleia e do povo;'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 41), 23, 'da injustiça diante do companheiro e do amigo;'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 41), 24, 'de cometer algum furto, no lugar em que habitas, por causa da verdade de Deus e da sua aliança: de apoiar, (à mesa), o cotovelo sobre os pães; de usar de engano, no dar e receber;'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 41), 25, 'de não responder aos que te saúdam; de fixar os olhos na mulher prostituta; de voltar o rosto a um parente.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 41), 26, 'Não voltes o rosto para não veres o teu próximo, e envergonha-te de lhe tirar a parte que lhe toca, e de lha não restituires.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 41), 27, 'Não olhes para a mulher alheia; não te entretenhas com a sua criada, nem te ponhas junto do seu leito.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 41), 28, '(envergonha-te) de dizer palavras injuriosas aos teus amigos; quando tiveres dado alguma coisa, não a lances em rosto.');
INSERT INTO bible_chapters (book_id, chapter_number, total_verses)
INSERT INTO bible_verses (chapter_id, verse_number, text) VALUES
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 42), 1, 'Não repitas o que tiveres ouvido, não reveles um segredo; assim serás verdadeiramente isento de confusão, e acharás graça diante de todos os homens. Não te envergonhes de coisa alguma das que te vou dizer, e não tenhas respeito humano, até ao ponto de pecar.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 42), 2, 'Não te envergonhes da lei do Altíssimo e da sua aliança, da sentença que absolve o ímpio (naquilo em que está inocente),'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 42), 3, 'de tratar com companheiros e peregrinos, de legar os bens aos amigos,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 42), 4, 'da fidelidade da balança e dos pesos, da aquisição do muito ou do pouco,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 42), 5, 'do preço da venda dos negociantes, da correcção freqüente dos filhos, de açoutar o dorso do escravo péssimo até que salte o sangue.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 42), 6, 'Sobre a mulher má, bom é pôr-se o selo. (ver nota)'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 42), 7, 'Onde há muitas mãos, guarda (tudo) fechado, e, tudo quanto entregares, dá-o por conta e por peso; aponta tudo o que deres e receberes.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 42), 8, '(Não te envergonhes) de corrigir o insensato e o néscio, nem (de defender) os velhos, que são condenados pelos jovens; assim te mostrarás sábio em tudo, e serás bem visto diante de todos os vivos.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 42), 9, 'Uma filha é para seu pai uma oculta preocupação, o cuidado dela tira-lhe o sono: receia que passe a flor da sua idade sem se casar, ou que, quando enfim estiver com seu marido, lhe seja odiosa;'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 42), 10, 'receia que na sua virgindade seja corrompida, e se ache pejada na casa de seu pai, ou que, habitando com seu marido, falte à fé conjugal, ou seja estéril.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 42), 11, 'Sobre a filha desenvolta vigia com dobrado resguardo, para que não faça de ti o opróbrio dos teus inimigos, o objecto de detracção da cidade e do ludíbrio da plebe, e te envergonhe diante da multidão do povo.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 42), 12, 'Não fixes os olhos sobre a beleza de ninguém, nem te detenhas no meio de mulheres.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 42), 13, 'porque dos vestidos sai a traça, e da mulher a maldade do homem.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 42), 14, 'É melhor a malvadez do homem que a bondade da mulher, quando esta é um motivo de confusão e de vergonha.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 42), 15, 'Lembrar-me-ei das obras do Senhor, e anunciarei o que tenho visto. Pelas palavras do Senhor existem as suas obras.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 42), 16, 'O Sol contempla todas as coisas, que Ilumina; a glória do Senhor enche a sua obra.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 42), 17, 'Porventura não fez o Senhor que os Santos publicassem todas as suas maravilhas, as quais o mesmo Senhor omnipotente solidamente estabeleceu, para que subsistam para sua glória?'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 42), 18, 'Ele sonda o abismo e o coração dos homens, e penetra os seus pensamentos mais subtis.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 42), 19, 'Realmente o Senhor conhece toda a ciência, contempla os sinais do tempo (que há-de vir), manifesta o passado e o futuro, descobre os rastos das coisas ocultas.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 42), 20, 'Não lhe escapa nenhum pensamento, não se esconde dele palavra alguma.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 42), 21, 'Adornou as maravilhas da sua sabedoria. Existe antes dos séculos e para sempre. Nada se lhe pode acrescentar,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 42), 22, 'nem diminuir, nem necessita do conselho de ninguém.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 42), 23, 'Quão amáveis são todas as suas obras! E todavia não podemos ver delas mais que uma centelha.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 42), 24, 'Todas estas coisas vivem e permanecem para sempre, e, em tudo o que é preciso, todas lhe obedecem.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 42), 25, 'Todas as coisas se acham aos pares, uma oposta à outra; (Deus) nada fez que ficasse incompleto.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 42), 26, 'Confirmou os bens (ou as propriedades) de cada uma Quem se saciará de contemplar a sua glória?');
INSERT INTO bible_chapters (book_id, chapter_number, total_verses)
INSERT INTO bible_verses (chapter_id, verse_number, text) VALUES
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 43), 1, 'O firmamento é a formosura do céu, e a abóbada celeste é um espectáculo de majestade.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 43), 2, 'O Sol, ao sair, glorifica o Senhor; é um vaso admirável, uma obra do Excelso.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 43), 3, 'Ao meio-dia queima a terra; quem pode suportar o seu ardor? O ferreiro serve-se da forja para trabalhar ao fogo;'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 43), 4, 'O Sol abrasa três vezes mais os montes, despedindo raios de fogo, cujo resplendor deslumbra os olhos.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 43), 5, 'Grande é o Senhor que o criou; ele apressa a sua carreira para lhe obedecer.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 43), 6, 'A lua, em todas as suas revoluções, é a marca dos tempos e o sinal do futuro.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 43), 7, 'Os dias de festa são determinados pela lua, cujo brilho diminui, depois de atingir o máximo.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 43), 8, 'O mês toma dela o nome; ela cresce, dum modo admirável, até ficar cheia.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 43), 9, 'É o farol dos exércitos das alturas; brilha gloriosamente no firmamento dos céus.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 43), 10, 'O brilho das estrelas é a beleza do céu, (por elas) o Senhor ilumina o mundo nas alturas.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 43), 11, 'A palavra do Santo estão prontas a executar as suas ordens, e nunca se cansam de fazer sentinela.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 43), 12, 'Contempla o arco-íris e bem-dize aquele que o fez; é muito formoso no seu resplendor.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 43), 13, 'Ele cerca o céu com um círculo de glória; são as mãos do Excelso que o estendem.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 43), 14, 'O Senhor com o seu império faz precipitar a neve, e acelera os raios (para a execução) dos seus juízos.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 43), 15, 'Por esta causa se abrem os seus tesouros, e voam as nuvens como aves. (ver nota)'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 43), 16, 'Pela grandeza do seu poder condensa as nuvens, e fragmentam-se as pedras da saraiva. (ver nota)'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 43), 17, 'Quando ele aparece, abalam-se os montes, e ao seu querer, sopra o vento do meio-dia.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 43), 18, 'A voz do seu trovão fere a terra, a tempestade do norte e o redemoinho dos ventos (causam destruição).'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 43), 19, 'Espalha a neve como aves que pousam sobre a terra; ela cai na terra como gafanhotos que se abatem sobre o solo.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 43), 20, 'Os olhos admiram a beleza da sua brancura, e o coração maravilha-se de a ver cair.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 43), 21, 'Ele derrama sobre a terra a geada como sal; quando esta se congela, torna-se como em pontas de abrolhos.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 43), 22, 'Sopra o vento frio do norte, e a água congela como um cristal, que repousa sobre todos os depósitos de águas, revestindo-as como de uma couraça.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 43), 23, 'Devora os montes, queima os desertos, seca a verdura como fogo.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 43), 24, 'O remédio de todos estes males é uma nuvem que venha depressa; um orvalho, que sobrevenha temperado, abrandará o seu rigor.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 43), 25, 'A uma palavra sua, acalma-se o vento; só com o seu pensar, aplaca o mar profundo, no meio do qual o Senhor plantou as ilhas.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 43), 26, 'Os que navegam sobre o mar, contem os seus perigos, que nós, escutando-os nos admiraremos.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 43), 27, 'Ali se encontram obras preclaras e maravilhosas, alimárias de todas as espécies e criaturas monstruosas.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 43), 28, 'Graças a ele tudo pende para o seu fim, por uma ordem estável; a sua palavra regula todas as coisas. (ver nota)'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 43), 29, 'Por muito que digamos, muito nos ficará por dizer, mas o resumo de todo o nosso discurso é este: Ele está em todas as coisas.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 43), 30, 'Que podemos nós para o glorificar? Sendo o Todo-Poderoso, é superior a todas as suas obras.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 43), 31, 'O Senhor é terrível e soberanamente grande, maravilhoso o seu poder.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 43), 32, 'Glorificai o Senhor quanto puderdes, que ele ficará sempre acima (dos vossos louvores), porque é admirável a sua magnificência.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 43), 33, 'Bem-dizei o Senhor, exaltai-o quanto puderdes, porque ele está acima de todo o louvor.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 43), 34, 'Para o exaltar, revesti-vos de toda a fortaleza, não vos canseis (de o exaltar), porque jamais chegareis ao fim. (ver nota)'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 43), 35, 'Quem o poderá ver e descrever? Quem o poderá engrandecer, como ele é, desde o princípio?'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 43), 36, 'Muitas obras suas, maiores do que estas, nos são escondidas, pois nós somente vemos um pequeno número delas.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 43), 37, 'O Senhor fez todas as coisas, e deu sabedoria aos que vivem piamente.');
INSERT INTO bible_chapters (book_id, chapter_number, total_verses)
INSERT INTO bible_verses (chapter_id, verse_number, text) VALUES
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 44), 1, 'Louvemos os varões ilustres, nossos maiores, a cuja geração pertencemos.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 44), 2, 'O Senhor operou (neles) muita glória. (manifestou) a sua magnificência desde o princípio.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 44), 3, 'Eles governaram os seus estados, foram homens grandes em poder e dotados de prudência; as predições que anunciaram adquiriram-lhes a dignidade de profetas;'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 44), 4, 'governaram o povo do seu tempo, e com a virtude da prudência deram instruções muito santas aos povos.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 44), 5, 'Com a sua habilidade compuseram melodias, escreveram cânticos das escrituras.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 44), 6, 'Eram homens ricos, poderosos, dados ao culto da beleza, pacíficos em suas casas. Todos eles alcançaram glória entre as gerações do seu povo, e foram louvados no seu tempo.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 44), 8, 'Os que deles nasceram deixaram um nome, que faz recordar os seus louvores.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 44), 9, 'Há outros, cuja memória já não existe: pereceram, como se não tivessem existido, nasceram, como se não tivessem nascido, — eles e os seus filhos.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 44), 10, 'Porém aqueles foram varões de misericórdia, cujas obras de piedade não foram esquecidas.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 44), 11, 'Na sua descendência permanecem os seus bens;'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 44), 12, 'os seus netos são uma santa herança, a sua posteridade manteve-se (fiel) na aliança (de Deus).'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 44), 13, 'É por causa deles que os seus filhos permanecem para sempre; nem a sua raça nem a sua glória terão fim.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 44), 14, 'Os seus corpos foram sepultados em paz, e o seu nome vive de geração em geração.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 44), 15, 'Celebrem os povos a sua sabedoria, publiquem-se os seus louvores nas assembleias.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 44), 16, 'Henoch agradou a Deus; foi transportado ao paraíso, para excitar as nações à penitência.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 44), 17, 'Noé foi encontrado perfeito e justo, e no tempo da ira tornou-se a reconciliação (dos homens).'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 44), 18, 'Por isso foram deixados uns restos (de seres vivos) sobre a terra, quando veio o dilúvio.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 44), 19, 'Com ele foi feita uma aliança eterna, para que não pudesse ser destruída por outro dilúvio toda a carne.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 44), 20, 'Abraão foi o glorioso pai duma multidão de nações, e não foi encontrado outro semelhante a ele em glória. Guardou a lei do Excelso, e com ele entrou em aliança.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 44), 21, 'Em sua carne (o Senhor) marcou esta aliança; na prova foi achado fiel.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 44), 22, 'Por isso jurou o Senhor que o havia de glorificar na sua descendência, que ele se multiplicaria como o pó da terra.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 44), 23, 'que exaltaria a sua posteridade como as estrelas, e que lhe daria por herança (o continente) de mar a mar, e desde o rio (Eufrates) até às extremidades da terra,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 44), 24, 'Com Isaac procedeu do mesmo modo, por amor de Abraão, seu pai.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 44), 25, 'O Senhor deu-lhe a bênção de todas as nações, e confirmou a sua aliança sobre a cabeça de Jacob.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 44), 26, 'Distinguiu-o com suas bênçãos, deu-lhe a herança, e repartiu-lha entre as doze tribos. E conservou-lhe homens de misericórdia, que fossem amados por todas as gentes.');
INSERT INTO bible_chapters (book_id, chapter_number, total_verses)
INSERT INTO bible_verses (chapter_id, verse_number, text) VALUES
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 45), 1, 'Moisés foi amado de Deus e dos homens; a sua memória está em bênção.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 45), 2, '(O Senhor) fê-lo semelhante em glória aos santos, engrandeceu-o e tornou-o terrível aos seus inimigos; (o mesmo Senhor) com as palavras dele (Moisés) fez cessar os prodígios.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 45), 3, 'Glorificou-o diante dos reis, prescreveu-lhe preceitos diante do seu povo, e fez-lhe ver a sua glória.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 45), 4, 'Pela sua fé e mansidão o santificou, e o escolheu dentre todos os homens. (Deus) ouviu-o a ele, escutou a sua voz, e fê-lo entrar na nuvem.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 45), 6, 'Deu-lhe os seus preceitos, frente a frente; e a lei da vida e da ciência, para ensinar a sua aliança a Jacob, e as suas ordens a Israel. (ver nota)'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 45), 7, 'Exaltou seu irmão Aarão, semelhante a ele, da tribo de Levi.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 45), 8, 'Estabeleceu com ele um pacto eterno, deu-lhe o sacerdócio do seu povo, encheu-o de felicidade e de glória,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 45), 9, 'cingiu-o dum cinto de honra, revestiu-o duma vestidura de glória, coroou-o com as insígnias do poder.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 45), 10, 'Pôs-lhe a vestidura talar, a túnica interior e o éfode, com uma cercadura de numerosas campainhas ouro,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 45), 11, 'a fim de que elas tocassem quando ele andasse, e se ouvisse o seu som no templo para advertir os filhos do seu povo.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 45), 12, '(Deu-lhe) uma vestidura santa, tecida de ouro, de jacinto e de púrpura, obra dum varão sábio, dotado de juízo e de verdade. (ver nota)'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 45), 13, 'Era uma obra de artista, de fio de escarlate, com pedras preciosas gravadas encastoadas em ouro, e trabalhadas por indústria do lapidário, para memória das doze tribos de Israel.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 45), 14, 'Sobre a sua tiara (colocou) uma coroa de ouro, onde estava gravado o selo da santidade e a glória soberana; era uma obra primorosa e um adorno que arrebatava os olhos. (ver nota)'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 45), 15, 'Não houve, nunca, antes deste (adorno sacerdotal) coisas tão preciosas, desde o princípio do mundo.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 45), 16, 'Dele se não vestiu pessoa alguma doutra família, mas só os seus filhos e os seus netos, por todo o decurso das idades.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 45), 17, 'Os seus sacrifícios eram diariamente consumidos pelo fogo.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 45), 18, 'Moisés encheu-lhe as mãos, e ungiu-o com óleo santo.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 45), 19, 'Foi-lhe concedido, por um pacto eterno, e aos seus descendentes enquanto durarem os dias do céu, o exercer as funções do sacerdócio, cantar os louvores (de Deus), e abençoar o seu povo em seu nome.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 45), 20, 'Ele o escolheu dentre os viventes para oferecer a Deus o sacrifício, o incenso e o perfume de lembrança, e para fazer a expiação pelo povo.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 45), 21, 'Deu-lhe poder relativamente aos seus preceitos e às disposições dos seus julgamentos, para ensinar os seus mandamentos a Jacob, e para dar a Israel a inteligência da sua lei.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 45), 22, 'Sublevaram-se contra ele uns estranhos (ao sacerdócio); por inveja o cercaram no deserto homens, que eram do partido de Datan e Abiron, e a facção de Coré, toda acesa em ira.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 45), 23, 'Viu isto o Senhor Deus, e não lhe agradou, e foram consumidos pela impetuosidade da sua cólera.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 45), 24, 'Operou contra eles prodígios, e consumiu-os com chamas de fogo.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 45), 25, 'Acrescentou a glória a Aarão, deu-lhe uma herança, concedeu-lhe as primícias dos frutos da terra.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 45), 26, 'Nas primícias preparou-lhe alimento em abundância; com efeito (os sacerdotes) devem comer dos sacrifícios do Senhor, os quais lhe deu a ele e à sua descendência. Mas não tem herança na terra das nações. nem porção entre os do seu povo, porque o mesmo Deus é a sua porção e herança.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 45), 28, 'Fineias, filho de Eleazar, é o terceiro em glória, imitando-o (a Moisés) no temor do Senhor.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 45), 29, 'Permaneceu firme no meio da queda vergonhosa do povo; pela bondade e zelo da sua alma aplacou Deus em favor de Israel.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 45), 30, 'Por isso é que Deus fez com ele uma aliança de paz, constituindo-o príncipe do santuário e do seu povo. a fim de que a dignidade sacerdotal pertencesse sempre a ele e à sua descendência.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 45), 31, '(Deus) também fez uma aliança (semelhante) com o rei Davide, filho de Jessé, da tribo de Judá, constituindo-o herdeiro (do reino), a ele e à sua linhagem, a fim de dar sabedoria ao nosso coração, e julgar o seu povo com justiça. para que não se perdesse a sua felicidade. É tornou eterna a glória destes (rarões) em sua nação. (ver nota)');
INSERT INTO bible_chapters (book_id, chapter_number, total_verses)
INSERT INTO bible_verses (chapter_id, verse_number, text) VALUES
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 46), 1, 'Josué, filho de Nun, valente na guerra, sucedeu a Moisés na missão de profeta; foi grande, grande como denota o seu nome, multo grande salvador dos escolhidos de Deus, para derrotar os inimigos que contra ele se levantavam, a fim de conseguir para Israel a sua herança.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 46), 3, 'Que glória não alcançou ele em levantar as suas mãos, e em brandir a lança contra as cidades (dos Amorreus)!'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 46), 4, 'Quem antes dele combateu assim? De facto, o mesmo Senhor lhe trouxe às mãos os seus inimigos. Não é assim que, por impulso do seu zelo, o sol parou, e que um só dia se tornou tão longo como dois?'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 46), 6, 'Ele invocou o Altíssimo Poderoso, quando atacava os inimigos por todas as partes, e o grande e santo Deus o ouviu, e fez cair saraiva de grande força. Investiu impetuosamente contra as hostes Inimigas, e derrotou os contrários na descida (do vale),'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 46), 8, 'para que as nações conhecessem o poder divino, (e aprendessem) que não é fácil pelejar contra Deus. Ele seguiu sempre o Todo-Poderoso,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 46), 9, 'e nos dias de Moisés fez uma acção de misericórdia, ele e Caleb, filho de Jefone, resolvendo fazer frente ao inimigo, impedindo o povo de pecar, e apaziguando a murmuração que a malícia tinha excitado. (ver nota)'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 46), 10, 'Sendo escolhidos estes dois, foram livres de perigo, dentre o número de seiscentos mil homens de pé, para introduzir o povo na sua herança, na terra que mana leite e mel.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 46), 11, 'O Senhor deu fortaleza ao mesmo Caleb; o seu vigor durou até à velhice, para subir a um lugar elevado do país, que a sua descendência possuiu por herança,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 46), 12, 'para que todos os filhos de Israel vissem que é bom obedecer ao Deus santo.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 46), 13, 'Em seguida vieram os juízes, apontados cada um por seu nome, cujo coração não foi pervertido, e que não se apartaram do Senhor.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 46), 14, 'para que a sua memória seja abençoada, para que os seus ossos reverdeçam nos sepulcros,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 46), 15, 'e dure perpétuamente o seu nome, passando aos seus filhos com a glória desses santos varões.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 46), 16, 'Samuel, profeta do Senhor, amado do Senhor seu Deus, instituiu um governo novo, e ungiu príncipes na sua nação.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 46), 17, 'Julgou o povo segundo a lei do Senhor, e Deus olhou propiciamente para Jacob. Pela sua fidelidade manifestou-se como profeta,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 46), 18, 'foi reconhecido fiel nas suas palavras, porque viu o Deus de luz.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 46), 19, 'Invocou o Senhor omnipotente, quando os inimigos o cercavam de todos os lados, e ofereceu um cordeiro sem mancha.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 46), 20, 'O Senhor trovejou do céu, com um grande estrondo fez ouvir a sua voz,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 46), 21, 'e destroçou os príncipes de Tyro e todos os chefes dos Filisteus.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 46), 22, 'Antes do tempo do sono eterno, deu testemunho, na presença do Senhor e do seu Ungido, de que não tinha recebido, de pessoa alguma, dinheiro nem sequer umas sandálias, e ninguém o pôde acusar.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 46), 23, 'Depois disto, Samuel morreu e apareceu ao rei (Saul), predizendo-lhe o fim da sua vida; levantou a sua voz de debaixo da terra, profetizando, para destruir a impiedade do povo.');
INSERT INTO bible_chapters (book_id, chapter_number, total_verses)
INSERT INTO bible_verses (chapter_id, verse_number, text) VALUES
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 47), 1, 'Depois disto, levantou-se Natan profeta no tempo de Davide.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 47), 2, 'Assim como a gordura da vítima se separa da carne, assim Davide foi separado (ou escolhido) dentre os filhos de Israel. (ver nota)'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 47), 3, 'Brincou com os leões como com cordeiros, e tratou os ursos como cordeirinhos.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 47), 4, 'Não foi ele quem, na sua mocidade, matou o gigante, e quem tirou o opróbrio do seu povo?'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 47), 5, 'Levantando a mão, com a pedra da funda fez cair por terra o orgulho de Golias,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 47), 6, 'porque ele invocou o Senhor Todo-Poderoso, o qual deu à sua dextra força para derrubar um homem valente na guerra, e para exaltar o poder do seu povo. Também foi celebrado por causa (da morte) dos dez mil homens, tornou-se ilustre com as bênçãos do Senhor, e foi-lhe oferecida uma coroa de glória,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 47), 8, 'porque desbaratou os inimigos por todas as partes, exterminou os Filisteus, seus adversários, até ao dia de hoje, abateu o seu poder para sempre.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 47), 9, 'Em todas as suas obras deu graças ao Santo e ao Excelso com palavras de louvor.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 47), 10, 'Louvou o Senhor de todo o seu coração, amou a Deus que o criou e lhe deu força contra os inimigos.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 47), 11, 'Estabeleceu cantores para estarem diante do altar, e compôs suaves melodias para os seus cânticos.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 47), 12, 'Deu esplendor às festividades, brilho aos dias solenes até ao fim da sua vida, para que louvassem o santo nome do Senhor, e engrandecessem desde manhã a santidade de Deus.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 47), 13, 'O Senhor o purificou dos seus pecados, exaltou para sempre o seu poder, e assegurou-lhe, por um pacto, a realeza e um trono de glória em Israel.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 47), 14, 'Sucedeu-lhe seu filho sábio; o Senhor, por amor dele, destruiu todo o poder dos seus inimigos.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 47), 15, 'Salomão reinou em dias de paz; Deus submeteu-lhe todos os seus inimigos, para que fundasse uma casa ao seu nome, e lhe preparasse um santuário eterno. Quão bem instruído foste na tua mocidade!'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 47), 16, 'Foste cheio de sabedoria, como um rio. A tua alma cobriu a terra,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 47), 17, 'e encheste-la de sentenças misteriosas. O teu nome tornou-se célebre até às ilhas remotas, e foste amado na tua paz.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 47), 18, 'Os teus cânticos, provérbios, parábolas e interpretações foram admirados por toda a terra.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 47), 19, 'Em nome do Senhor Deus, que é chamado o Deus de Israel,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 47), 20, 'ajuntaste ouro, como se fosse estanho, e amontoaste prata como chumbo;'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 47), 21, '(mas) depois inclinaste-te para as mulheres, entregaste à libertinagem o teu corpo,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 47), 22, 'puseste mácula na tua glória, profanaste a tua geração, fazendo com que viesse a ira sobre os teus filhos, o castigo sobre a tua loucura,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 47), 23, 'causando com isso um cisma no reino, e fazendo sair de Efraim uma dominação cruel.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 47), 24, 'Mas Deus não abandonará a sua misericórdia, não destruirá nem aniquilará as suas obras, não arrancará pela raiz a posteridade de (Daride) seu escolhido, não exterminará a linhagem desse varão amante do Senhor.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 47), 25, 'Por isso deixou um resto a Jacob, e a Davide (um rebento) da sua linhagem.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 47), 26, 'E morreu Salomão com seus pais.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 47), 27, 'Deixou depois de si um filho, (que foi causa da) loucura do povo.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 47), 28, 'um homem falto de prudência, chamado Roboão, que afastou de si o povo com o seu (mau) conselho;'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 47), 29, 'e Joroboão, filho de Nabat, que fez pecar Israel, e abriu a Efraim o caminho do pecado. Houve grandíssima inundação dos seus crimes,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 47), 30, 'por causa dos quais foram muitas vezes lançados fora da sua terra.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 47), 31, '(Israel) entregou-se a todo o género de maldades, até que veio a vingança, que pôs um termo a todos os pecados. (ver nota)');
INSERT INTO bible_chapters (book_id, chapter_number, total_verses)
INSERT INTO bible_verses (chapter_id, verse_number, text) VALUES
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 48), 1, 'Surgiu depois o profeta Elias, como um fogo. As suas palavras ardiam como um facho. Fez vir sobre eles a fome. Os que o irritavam pela sua inveja foram reduzidos a um pequeno número, porque não podiam suportar os preceitos do Senhor. (ver nota)'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 48), 3, 'Com a palavra do Senhor fechou o céu, e fez cair fogo do mesmo céu por três vezes.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 48), 4, 'Quão glorioso te tornaste, Elias, pelos teus prodígios! Quem pode gloriar-se de ser como tu?'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 48), 5, 'Tu que fizeste sair um morto do sepulcro, arrancando-o à morte, em virtude da palavra do Senhor Deus;'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 48), 6, 'que precipitaste os reis na desgraça, que desfizeste sem trabalho o seu poder, e, no meio da sua glória, os fizeste cair do leito (na sepultura); que ouviste sobre o Sinai o juízo do Senhor, e sobre o Horeb os decretos da sua vingança; (ver nota)'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 48), 8, 'que sagraste reis para vingar crimes, e estabeleceste profetas para teus sucessores;'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 48), 9, 'que foste arrebatado (ao céu) num redemoinho de fogo, num carro tirado por cavalos ardentes;'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 48), 10, 'tu, que foste designado nos decretos dos tempos para abrandar a ira do Senhor, para reconciliar o coração dos pais com os filhos, e para restabelecer as tribos de Jacob.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 48), 11, 'Bem-aventurados os que te viram, e que foram honrados com a tua amizade!'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 48), 12, 'Quanto a nos, vivemos só durante esta vida, e depois da morte não teremos um nome como o teu.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 48), 13, 'Elias foi envolto num redemoinho, mas o seu espírito ficou em Eliseu, o qual não temeu príncipe algum em seus dias, e, em poder, não foi vencido por ninguém.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 48), 14, 'Nada houve que o pudesse dominar, e, ainda depois de morto, o seu corpo profetizou.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 48), 15, 'Em sua vida fez prodígios, e na morte operou maravilhas.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 48), 16, 'Com todas estas maravilhas o povo não fez penitência, não se afastou dos seus pecados, até que foi expulso da sua terra, e espalhado por todo o mundo.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 48), 17, 'Ficou muito pouca gente (na Palestina), e (somente) um príncipe da casa de Davide.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 48), 18, 'Alguns deles fizeram o que era do agrado de Deus, outros cometeram muitos pecados.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 48), 19, 'Ezequias fortificou a sua cidade, conduziu água para o centro dela, abriu com ferro um rochedo, e fez reservatórios para água.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 48), 20, 'Durante o seu reinado veio Senaquerib. que enviou Rabsaces, o qual levantou a sua mão contra eles. estendeu a sua mão contra Sião, ensoberbecendo-se com o seu poder.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 48), 21, 'Então (os Israelitas) ficaram sobressaltados nos seus corações e nas suas mãos sentiram dores como as mulheres que estão de parto.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 48), 22, 'Invocaram o Senhor misericordioso, levantando ao céu as suas mãos estendidas, e o Santo, o Senhor Deus, ouviu logo a sua voz.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 48), 23, 'Não mais se lembrou dos seus pecados, não os entregou aos seus inimigos, mas purificou-os por mão do santo profeta Isaías.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 48), 24, 'Dissipou o Acampamento dos Assírios, e o anjo do Senhor os exterminou. Porque Ezequias fez o que era do agrado de Deus, andou com fortaleza pelo caminho de Davide seu Pai, como lhe tinha recomendado Isaías, profeta grande e fiel diante de Deus.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 48), 26, 'Em seus dias, o Sol voltou para trás, e ele (o profeta) prolongou a vida do rei.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 48), 27, 'Com o seu grande espírito (profético) viu os últimos tempos, e consolou os que choravam em Sião. Até ao fim dos séculos'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 48), 28, 'mostrou o que devia acontecer, e as coisas ocultas antes que sucedessem.');
INSERT INTO bible_chapters (book_id, chapter_number, total_verses)
INSERT INTO bible_verses (chapter_id, verse_number, text) VALUES
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 49), 1, 'A memória de Josias é como uma composição de aromas feita por arte do perfumista. Em toda a boca será doce a sua lembrança como o mel, e como a música em banquete de (abundante) vinho.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 49), 3, 'Foi destinado por Deus para excitar a nação à penitência, e exterminou as abominações da impiedade.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 49), 4, 'Dirigiu o seu coração para o Senhor, e nos dias dos pecadores fortificou a piedade.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 49), 5, 'Excepto Davide, Ezequias e Josias, todos cometeram o pecado:'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 49), 6, 'os reis de Judá deixaram a lei do Altíssimo, desprezaram o temor de Deus.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 49), 7, 'Por isso tiveram de entregar a outros o seu reino, e a sua glória a uma nação estrangeira,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 49), 8, 'Incendiaram a cidade escolhida, a cidade santa, e reduziram a um deserto as suas ruas, conforme a predição de Jeremias,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 49), 9, 'porque maltrataram aquele que foi consagrado profeta desde o ventre de sua mãe, para derrubar, arrancar e destruir, mas para depois reedificar e renovar.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 49), 10, 'Ezequiel teve uma visão de glória. que o Senhor lhe mostrou no carro dos querubins.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 49), 11, 'Anunciou a chuva para os inimigos de Deus, e os bens reservados para aqueles que seguiam o caminho recto.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 49), 12, 'Reverdeçam também os ossos dos doze profetas, nos seu túmulos, porque eles fortificaram Jacob, e salvaram-no por uma fé corajosa.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 49), 13, 'Como engrandeceremos nós a Zorobabel? Ele foi como um anel na mão direita. (ver nota)'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 49), 14, 'Do mesmo modo, Jesus, filho de Josedec. Eles em seus dias edificaram a casa (de Deus). e levantaram ao Senhor o seu santo templo, destinado a uma glória sempiterna.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 49), 15, 'Também Neemias viverá na memória por largo tempo, ele que reergueu os nossos muros derribados, refez as portas e as fechaduras, e reedificou as nossas casas.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 49), 16, 'Nenhum nasceu no mundo como Henoch, o qual foi arrebatado da terra,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 49), 17, 'nem como José, que nasceu para ser o príncipe de seus irmãos, o esteio da nação, o governador dos seus irmãos, o firme arrimo do povo.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 49), 18, 'Os seus ossos foram visitados; depois da sua morte profetizaram,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 49), 19, 'Set e Sem alcançaram glória entre os homens, mas, sobre todos os seres vivos da criação, está Adão.');
INSERT INTO bible_chapters (book_id, chapter_number, total_verses)
INSERT INTO bible_verses (chapter_id, verse_number, text) VALUES
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 50), 1, 'Simão filho de Onias sumo sacerdote, em sua vida reparou a casa (do Senhor), e em seus dias fortificou o templo. (ver nota)'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 50), 2, 'Foi ele que fundou a alta construção do templo, o edifício duplo e as elevadas muralhas do mesmo templo.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 50), 3, 'Em seus dias correram os mananciais das águas dos reservatórios, que se encheram extraordinariamente, como o mar (de bronze).'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 50), 4, 'Teve cuidado do seu povo, livrou-o da perdição. Conseguiu engrandecer a cidade; nas suas relações com o povo alcançou glória, e alargou a entrada do templo e do átrio.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 50), 6, 'Como a estrela da manhã, no meio da névoa, como a Lua resplandecente no plenilúnio, e como um Sol brilhante, assim luziu no templo de Deus.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 50), 8, '(Ele era) como o arco-íris que reluz entre as nuvens iluminadas, como a flor das roseiras nos dias da primavera, como os lírios que estão junto da corrente de água, como o incenso que exala fragrância em dias de verão,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 50), 9, 'como a chama refulgente, e o incenso que arde no fogo:'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 50), 10, 'como um vaso de ouro maciço, ornado de toda a casta de pedras preciosas.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 50), 11, 'como a oliveira que brota e como o cipreste que se eleva ao alto, quando tomava a sua vestidura de glória, e quando se revestia de todos os ornamentos da sua dignidade.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 50), 12, 'Quando subia ao altar santo, honrava as vestiduras sagradas.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 50), 13, 'Recebia as porções (das vítimas) da mão dos sacerdotes, conservando-se de pé junto do altar, e, em volta, os seus irmãos formavam uma coroa, como uma plantação de cedros do Líbano.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 50), 14, 'Estavam em torno dele, como os ramos duma palmeira, todos os filhos de Aarão na sua glória,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 50), 15, 'A oblação destinada ao Senhor estava nas mãos deles, na presença de toda a assembleia de Israel. Para consumar o sacrifício sobre o altar, para tornar mais solene a oblação ao Rei excelso.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 50), 16, 'estendia a sua mão para fazer a libação, e derramava o sangue da uva.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 50), 17, 'Derramava-o ao pé do altar, como um perfume divino ao Príncipe excelso.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 50), 18, 'Então os filhos de Aarão levantavam ás suas vozes, tocavam as suas trombetas de metal batido e faziam ressoar um grande concerto para renovarem diante do Senhor a memória (da sua aliança).'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 50), 19, 'Todo o povo se apressava e prostrava-se com o rosto por terra, para adorar o Senhor seu Deus e fazer orações ao Deus omnipotente e excelso.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 50), 20, 'Os cantores levantavam as suas vozes, e naquela grande casa retinia um som cheio de suavidade.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 50), 21, 'O povo fazia as suas preces ao Senhor excelso, até ficar de todo completo o culto do Senhor, até terminarem as funções sagradas.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 50), 22, 'Então (o sumo sacerdote), descendo (do altar), levantava as suas mãos sobre todo o congresso dos filhos de Israel, para dar glória a Deus com seus lábios, e para se glorificar no seu nome.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 50), 23, '(Então o povo) repetia a sua oração, querendo manifestar o poder de Deus.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 50), 24, 'E agora rogai ao Deus de todas as criaturas, que fez grandes coisas em toda a terra, que aumentou os nossos dias desde o ventre materno, e que nos tratou sempre segundo a sua misericórdia.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 50), 25, 'Conceda-nos ele a alegria do coração, e reine a paz em Israel em nossos dias e para sempre,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 50), 26, 'a fim de que Israel creia que está connosco a misericórdia de Deus, e para que ele nos livre no seu dia. (ver nota)'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 50), 27, 'Dois povos aborrece a minha alma, e o terceiro, que eu aborreço nem sequer é um povo:'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 50), 28, 'Os que habitam no monte Seir, os Filisteus, e a gente insensata que habita em Siquém.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 50), 29, 'Estas são as instruções de sabedoria e de disciplina, que deixou escritas neste livro Jesus, filho de Sirach, natural de Jerusalém, o qual derramou a sabedoria do seu coração.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 50), 30, 'Bem-aventurado o que se dá a estes bons ensinamentos; o que os conserva em seu coração será sempre sábio.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 50), 31, 'Com efeito, se praticar estas coisas, será capaz de tudo, porque a luz de Deus guiará os seus passos.');
INSERT INTO bible_chapters (book_id, chapter_number, total_verses)
INSERT INTO bible_verses (chapter_id, verse_number, text) VALUES
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 51), 1, 'Oração de Jesus, filho de Sirach. Glorificar-te-ei, ó Senhor rei, louvar-te-ei, Deus, salvador meu.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 51), 2, 'Glorificarei o teu nome, porque te fizeste o meu auxílio e protector,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 51), 3, 'livraste o meu corpo da perdição, do laço da língua iníqua e dos lábios dos forjadores da mentira; à vista dos que estavam contra mim, foste o meu defensor.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 51), 4, 'Livraste-me, segundo a grandeza da misericórdia do teu nome, dos que rugiam, preparados para me devorarem, das mãos dos que procuravam tirar-me a vida, do poder das tribulações que me assaltavam,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 51), 6, 'da violência da chama que me envolvia. — no melo do fogo (da perseguição) não me queimei — das profundas entranhas da morada dos mortos, da língua impura, da palavra de mentira, dum rei iníquo e da língua injusta.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 51), 8, 'A minha alma louvará o Senhor até à morte,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 51), 9, 'pois a minha vida estava prestes a cair nas profundezas da morada dos mortos.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 51), 10, 'Cercaram-me de todas as partes, e não havia quem me ajudasse. Volvia os olhos em busca do socorro dos homens, e não apareciam.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 51), 11, 'Lembrei-me da tua misericórdia. Senhor, do que tens feito desde o princípio do mundo,'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 51), 12, 'porque livras os que esperam em ti. Senhor, porque os salvas das mãos das nações.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 51), 13, 'Tu exaltaste a minha habitação sobre a terra, e eu roguei-te quando vinha sobre mim a torrente de morte.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 51), 14, 'Invoquei o Senhor, pai do meu Senhor, para que me não abandonasse, no dia da minha tribulação, sem socorro, durante o domínio dos soberbos.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 51), 15, 'Louvarei incessantemente o teu nome, celebrá-lo-ei nas minhas acções de graças, pois foi atendida a minha oração.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 51), 16, 'porque me livraste da perdição, me salvaste no tempo calamitoso.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 51), 17, 'Por Isso eu te glorificarei, cantarei os teus louvores, e bem-direi o nome do Senhor.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 51), 18, 'Quando eu ainda era jovem, antes de andar errante, busquei abertamente a sabedoria com a minha oração.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 51), 19, 'Diante do templo eu a pedia, e buscá-la-ei até ao fim da minha vida. Ela floresceu (em mim) como uva temporã;'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 51), 20, 'O meu coração alegrou-se nela; os meus pés andaram por caminho direito; desde a minha mocidade tenho ido em seguimento dela.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 51), 21, 'Apliquei um pouco o meu ouvido, e logo a percebi. Encontrei muita sabedoria em mim mesmo, e fiz nela grandes progressos.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 51), 23, 'Ao que me deu a sabedoria, dar-lhe-ei gloria.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 51), 24, 'Resolvi-me a pô-la em prática; tive zelo do bem, e não me envergonharei.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 51), 25, 'Lutou a minha alma por ela, conservei-me constante em a praticar.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 51), 26, 'Levantei as minhas mãos ao alto, e chorei a loucura da minha alma.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 51), 27, 'Dirigi para ela a minha alma, e encontrei-a. ao procurar conhecê-la.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 51), 28, 'Possuí, graças a ela, o meu coração desde o princípio, e, por isso, não serei desamparado (por Deus).'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 51), 29, 'As minhas entranhas comoveram-se em busca dela; por isso consegui um bem excelente.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 51), 30, 'O Senhor deu-me em recompensa uma língua (eloquente); com ela o louvarei.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 51), 31, 'Aproximai-vos de mim, ó ignorantes, e reuni-vos na casa da instrução.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 51), 32, 'Por que tardais vós ainda? E que dizeis a isto? As vossas almas estão sequiosas em extremo.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 51), 33, 'Eu abri a minha boca e disse: Vinde buscá-la sem dinheiro.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 51), 34, 'submetei o vosso pescoço ao seu jugo, e receba a vossa alma a instrução, porque perto se pode encontrá-la.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 51), 35, 'Vede com os vossos olhos o pouco que trabalhei, e como adquiri muito descanso.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 51), 36, 'Recebei a instrução, como uma grande soma de dinheiro. e possuireis com ela grande abundância de ouro.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 51), 37, 'Alegre-se a vossa alma na misericórdia do Senhor, e nunca ficareis confundidos, quando o louvardes.'),
((SELECT id FROM bible_chapters WHERE book_id = (SELECT id FROM bible_books WHERE abbrev = 'undefined') AND chapter_number = 51), 38, 'Realizai a vossa obra, antes que passe o tempo, e ele vos dará a seu tempo a vossa recompensa.');
